// SEARCH_DB 제거 — Yahoo Finance 실시간 검색으로 대체
// 잘못된 코드 600개 전부 삭제

const COLORS=Array.from({length:10},function(_,i){return 'var(--stock-'+(i+1)+')';});

function guessEtfDiv(n){
  n=n||'';
  if(n.match(/커버드콜|프리미엄액티브/))return{isDv:true,dy:10.0,df:'월배당'};
  if(n.match(/배당다우존스/))           return{isDv:true,dy:4.0, df:'월배당'};
  if(n.match(/배당100/))                return{isDv:true,dy:7.0, df:'월배당'};
  if(n.match(/고배당/))                 return{isDv:true,dy:5.0, df:'분기배당'};
  if(n.match(/배당성장/))               return{isDv:true,dy:3.5, df:'월배당'};
  if(n.match(/배당/))                   return{isDv:true,dy:3.0, df:'분기배당'};
  return{isDv:false,dy:0,df:'없음'};
}

function toSym(n){
  if(!n)return '';
  // 보유 종목에서 찾기 (이름 또는 심볼)
  const h=D&&D.h&&D.h.find(x=>x.n===n||(x.sym&&x.sym===n));
  if(h&&h.sym)return h.sym;
  // 6자리 숫자 코드
  if(/^\d{6}$/.test(n))return n+'.KS';
  // 알파벳+숫자 6-7자리 KRX 코드
  if(/^[A-Z0-9]{6,7}$/.test(n)&&!/^[A-Z]{1,5}$/.test(n))return n+'.KS';
  // 미국 주식 티커 (1~5자 대문자)
  if(/^[A-Z]{1,5}$/.test(n.trim()))return n.trim();
  return n.toUpperCase();
}

function isKRName(n){
  if(!n)return false;
  if(/[가-힣]/.test(n))return true;
  if(/^(KODEX|TIGER|RISE|ACE|SOL|HANARO|KBSTAR|ARIRANG|TIMEFOLIO|TIME|PLUS|KIWOOM|WON|FOCUS|1Q|HK|KB|NH|한국|미래|키움|삼성|신한|우리|하나)/.test(n))return true;
  // 보유 종목에서 확인
  const h=D&&D.h&&D.h.find(x=>x.n===n);
  if(h&&h.sym)return isKR(h.sym);
  return false;
}
// 한글 별칭이 붙은 미국주식(예: 브로드컴→AVGO) 오라우팅 방지용 헬퍼
// 순수 미국 티커(1~5자 알파벳) 또는 잘못 .KS/.KQ 접미사가 붙은 미국 티커(예: AVGO.KS)면 true
function _isUSSym(s){
  if(!s)return false;
  const base=s.replace(/\.(KS|KQ)$/i,'');
  return /^[A-Z]{1,5}$/.test(base);
}
function load(){
  try{
    const d=JSON.parse(localStorage.getItem('pf6'))||{h:[],rate:1380,at:'',sells:[],goalMon:0};
    if(!d.sells)d.sells=[];if(!d.goalMon)d.goalMon=0;return d;
  }catch{return{h:[],rate:1380,at:'',sells:[],goalMon:0};}
}
function save(){try{localStorage.setItem('pf6',JSON.stringify(D));}catch(e){console.warn('save failed',e);}}
let D=load(),TAB='list',FLT='all',SORT='default',SIM_TAB='general',LDS=new Set(),LDALL=false,SILENT_REFRESHING=false,PIE=null,BUY_ID=null,SELL_ID=null;

// 절세 계좌 판정 헬퍼 (tax/isa/irp/pension 모두 절세로 간주)
function _isTaxAcct(a){return a==='tax'||a==='isa'||a==='irp'||a==='pension';}
function _acctGroup(a){return _isTaxAcct(a)?'tax':'general';}

// ═══ 실효 배당세율 헬퍼 (B 휴리스틱 + D 학습) ═══
// ETF 타입/종목 특성에 따라 기본 세율 추정 (일반계좌 기준 세율)
// 절세계좌 여부는 호출측에서 acct 확인해서 0%로 덮어쓸 것
function _inferTaxRate(h){
  // ═══ 앱 내 기본세율 (2025-2026 기준) ═══
  // 1. 해외상장 주식/ETF (미국): 15% (한미조세조약, 현지 원천징수)
  // 2. 커버드콜 ETF (옵션프리미엄 분배): 10.2% (과표기준가 방식 · 실효세율 평균)
  //    → 옵션프리미엄은 과세 대상에서 빠지는 비중이 커 실효세율이 낮음
  //    → 사용자가 SMART TAX RATE로 실측 입력 시 학습된 값으로 덮어씀
  // 3. 국내 ETF/주식 (일반): 15.4% (소득세14% + 지방소득세1.4%)
  // 4. 절세계좌 (ISA/IRP/연금저축): 비과세 / 이연 → 0%
  var sym=(h.sym||'').toUpperCase();
  var n=(h.n||'');
  var isKrSym = /\.(KS|KQ)$/i.test(sym);
  var isUsTicker = !isKrSym && /^[A-Z]{1,5}(\.\w+)?$/i.test(sym);

  // 해외상장 (미국 ETF/주식) → 15%
  if(isUsTicker){
    return {rate:15.0, mode:'auto', reason:'미국 원천징수 15% (한미조세조약)'};
  }
  // 국내상장 커버드콜 → 10.2% (과표기준가 + 옵션프리미엄 특성 반영)
  if(/커버드콜|CoveredCall|Covered\s*Call/i.test(n)){
    return {rate:10.2, mode:'auto', reason:'커버드콜 과표기준가 방식 (학습으로 보정)'};
  }
  // 국내 ETF/주식 → 15.4% (법정 명목세율)
  return {rate:15.4, mode:'auto', reason:'국내 배당소득세 15.4% (소득세14%+지방세1.4%)'};
}

// 세율 취득: auto 모드면 항상 최신 휴리스틱으로 재계산 (기존 잘못 저장된 값 무시)
function _getTaxRate(h){
  var mode = h.taxRateMode || 'auto';
  if((mode === 'learned' || mode === 'manual') && h.taxRate != null && isFinite(h.taxRate)){
    return Number(h.taxRate);
  }
  return _inferTaxRate(h).rate;
}

// 학습: 세전/세후 → 실효세율 역산
function _calcEffectiveRate(gross, net){
  var g = Number(gross)||0, ne = Number(net)||0;
  if(g<=0 || ne<0) return null;
  var rate = (g - ne) / g * 100;
  return Math.max(0, Math.min(30, rate)); // 0~30% 범위 제한
}

// 학습값 갱신: taxHistory에 기록 추가하고 평균 세율을 taxRate로
function _updateTaxRateFromHistory(h){
  var hist = Array.isArray(h.taxHistory) ? h.taxHistory.filter(function(x){return x && isFinite(x.rate);}) : [];
  if(!hist.length) return;
  // 최근 6회 평균
  var recent = hist.slice(-6);
  var avg = recent.reduce(function(s,x){return s+x.rate;},0) / recent.length;
  h.taxRate = parseFloat(avg.toFixed(2));
  h.taxRateMode = 'learned';
}

// 세율 카드 렌더링 (종목 상세 모달 안)
function renderTaxRateCard(h, id){
  if(!h || !h.isDv) return ''; // 배당주만 표시

  // buys 기반 계좌 구성 판정 (어느 계좌에 얼마나 있는지)
  var buys = Array.isArray(h.buys) ? h.buys : [];
  var genQty=0, taxQty=0;
  if(buys.length){
    buys.forEach(function(b){
      var bq=Number(b.qty)||0;
      if(_isTaxAcct(b.acct||'general')) taxQty+=bq; else genQty+=bq;
    });
  } else {
    // buys 없으면 h.acct 기준
    if(_isTaxAcct(h.acct)) taxQty=h.qty||0; else genQty=h.qty||0;
  }
  var totalQty = genQty+taxQty;
  var allTax = totalQty>0 && genQty===0;
  var hasMix = genQty>0 && taxQty>0;

  // 전량 절세계좌면 비과세 카드
  if(allTax){
    return '<div class="tr-card">'
      + '<div class="tr-top">'
        + '<div class="tr-lbl"><span class="tr-lbl-icon">🛡️</span><span>SMART TAX RATE</span></div>'
        + '<div class="tr-row">'
          + '<div class="tr-rate">0.0<span class="sym">%</span></div>'
          + '<span class="tr-badge">비과세</span>'
        + '</div>'
        + '<div class="tr-sub">전량 절세계좌 보유 · 배당 수령 시 비과세</div>'
      + '</div>'
      + '</div>';
  }

  // 일반계좌 보유분이 있음 (혼합 또는 전량 일반)
  var inf = _inferTaxRate(h);
  var mode = h.taxRateMode || inf.mode; // 'auto'|'learned'|'manual'
  var rate = _getTaxRate(h);
  var hist = Array.isArray(h.taxHistory) ? h.taxHistory : [];
  var histCount = hist.length;

  var badgeHtml, reason;
  if(mode === 'manual'){
    badgeHtml = '<span class="tr-badge manual">✓ 직접 설정</span>';
    reason = '직접 설정한 값';
  } else if(mode === 'learned'){
    badgeHtml = '<span class="tr-badge">✨ 학습됨</span>';
    reason = '최근 수령 내역 ' + histCount + '건 기반 · 정확도 높음';
  } else {
    badgeHtml = '<span class="tr-badge auto">⚡ 자동 추정</span>';
    reason = inf.reason;
  }
  // 혼합 보유 시 안내 추가
  if(hasMix){
    var tPct = Math.round(taxQty/totalQty*100);
    reason += ' · 혼합 보유 (절세 ' + tPct + '%)';
  }

  // 학습 진행도 (최대 6회)
  var progress = Math.min(100, Math.round(histCount / 6 * 100));
  var progressLbl = histCount + ' / 6';

  // 체크리스트
  var step1Done = histCount >= 1;
  var step2Done = histCount >= 3;
  var step3Done = histCount >= 6;

  var step1 = '<div class="tr-learn-row">'
    + '<span class="tr-dot ' + (step1Done?'done':'pending') + '">' + (step1Done?'✓':'○') + '</span>'
    + '<span class="tr-learn-text' + (step1Done?'':' pending') + '">첫 수령액 기록</span>'
    + '<span class="tr-learn-val' + (step1Done?'':' pending') + '">' + (step1Done?histCount+'건':'0건') + '</span>'
    + '</div>';

  var step2 = '<div class="tr-learn-row">'
    + '<span class="tr-dot ' + (step2Done?'done':'pending') + '">' + (step2Done?'✓':'○') + '</span>'
    + '<span class="tr-learn-text' + (step2Done?'':' pending') + '">3회 이상 · 평균 세율 산출</span>'
    + '<span class="tr-learn-val' + (step2Done?'':' pending') + '">' + (step2Done?rate.toFixed(2)+'%':'3회 필요') + '</span>'
    + '</div>';

  var step3 = '<div class="tr-learn-row">'
    + '<span class="tr-dot ' + (step3Done?'done':'pending') + '">' + (step3Done?'✓':'○') + '</span>'
    + '<span class="tr-learn-text' + (step3Done?'':' pending') + '">6회 기록 · 정확도 MAX</span>'
    + '<span class="tr-learn-val' + (step3Done?'':' pending') + '">' + (step3Done?'완료':(6-histCount)+'회 남음') + '</span>'
    + '</div>';

  return '<div class="tr-card">'
    + '<div class="tr-top">'
      + '<div class="tr-lbl"><span class="tr-lbl-icon">⚡</span><span>SMART TAX RATE</span>' + (hasMix?'<span style="margin-left:auto;font-size:9.5px;color:#1e40af;opacity:.7;font-weight:700">일반계좌분 기준</span>':'') + '</div>'
      + '<div class="tr-row">'
        + '<div class="tr-rate">' + rate.toFixed(2) + '<span class="sym">%</span></div>'
        + badgeHtml
      + '</div>'
      + '<div class="tr-sub">' + reason + '</div>'
      + '<div class="tr-progress-wrap">'
        + '<div class="tr-progress-head">'
          + '<span class="tr-progress-lbl">학습 진행도</span>'
          + '<span class="tr-progress-val">' + progressLbl + '</span>'
        + '</div>'
        + '<div class="tr-bar"><div class="tr-bar-fill" style="width:' + progress + '%"></div></div>'
      + '</div>'
    + '</div>'
    + '<div class="tr-learn">'
      + step1 + step2 + step3
      + '<button class="tr-cta" onclick="openTaxRateInput(' + id + ')">＋ 이번 달 수령액 기록하기</button>'
      + '<button class="tr-cta-sec" onclick="openTaxRateManual(' + id + ')">세율 직접 설정</button>'
    + '</div>'
    + '</div>';
}

// 수령액 입력 모달 열기 (계좌 단위)
function openTaxRateInput(id){
  var h = D.h.find(function(x){return x.id===id;});
  if(!h) return;
  window._taxInputId = id;

  // 최근 세전 주당 배당금 (KRW 환산)
  var isUs = !(isKR(h.sym||'') || isKRName(h.n||''));
  var fxRate = Number(D.rate)||1380;
  var divs = Array.isArray(h.divHistory) ? h.divHistory.filter(function(d){return Number(d.amount||0)>0;}) : [];
  var latest = divs.length ? divs[0] : null;
  var amtPerShareKrw = 0;
  if(latest){
    var a = Number(latest.amount)||0;
    amtPerShareKrw = isUs ? Math.round(a * fxRate) : Math.round(a);
  }

  // 기본 주식 수: 일반계좌 보유 주식 수
  var buys = Array.isArray(h.buys) ? h.buys : [];
  var defaultQty = 0;
  if(buys.length){
    buys.forEach(function(b){
      if(!_isTaxAcct(b.acct||'general')) defaultQty += Number(b.qty)||0;
    });
  } else {
    if(!_isTaxAcct(h.acct)) defaultQty = Number(h.qty)||0;
  }
  if(!defaultQty) defaultQty = Number(h.qty)||0; // fallback

  var today = new Date().toISOString().slice(0,10);
  var initGross = amtPerShareKrw * defaultQty;

  var body = document.getElementById('taxInputBody');
  body.innerHTML = '<div class="tri-head">'
    + '<div class="tri-icon">💵</div>'
    + '<div class="tri-ttl">실제 수령액 입력</div>'
    + '<div class="tri-sub">한 계좌만 확인해서 입력하면 돼요<br>증권사별로 합산할 필요 없음</div>'
    + '</div>'
    + '<div class="tri-field">'
      + '<div class="tri-lbl"><span>종목</span></div>'
      + '<input class="tri-inp" value="' + (h.n||'').replace(/"/g,'&quot;') + '" readonly>'
    + '</div>'
    + '<div class="tri-field">'
      + '<div class="tri-lbl"><span>세전 주당 배당금 <span class="tri-src-badge">AUTO</span></span></div>'
      + '<div class="tri-inp-wrap">'
        + '<input class="tri-inp" id="triPerShare" type="number" value="' + amtPerShareKrw + '" inputmode="numeric" style="padding-right:58px">'
        + '<span class="tri-unit">원 / 주</span>'
      + '</div>'
    + '</div>'
    + '<div class="tri-field">'
      + '<div class="tri-lbl"><span>이 계좌의 주식 수</span><span class="tri-hint">이 증권사 일반계좌만</span></div>'
      + '<div class="tri-inp-wrap">'
        + '<input class="tri-inp" id="triQty" type="number" value="' + defaultQty + '" inputmode="numeric" style="padding-right:32px">'
        + '<span class="tri-unit">주</span>'
      + '</div>'
    + '</div>'
    + '<div class="tri-auto-calc">'
      + '<span class="tri-auto-calc-lbl">⚡ 세전 실배당금</span>'
      + '<span class="tri-auto-calc-val" id="triGrossAuto">' + fN(initGross) + '<span class="sym">원</span></span>'
    + '</div>'
    + '<div class="tri-arrow">↓</div>'
    + '<div class="tri-field" style="margin-top:10px">'
      + '<div class="tri-lbl"><span>실제 입금된 금액 (세후)</span><span class="tri-hint">증권사 앱 참고</span></div>'
      + '<div class="tri-inp-wrap">'
        + '<input class="tri-inp" id="triNet" type="number" placeholder="금액 입력" inputmode="numeric" style="padding-right:32px" autofocus>'
        + '<span class="tri-unit">원</span>'
      + '</div>'
    + '</div>'
    + '<div class="tri-result" id="triResult" style="display:none">'
      + '<div class="tri-result-lbl">⚡ 자동 계산된 실효세율</div>'
      + '<div class="tri-result-val" id="triResultVal">-<span class="sym">%</span></div>'
      + '<div class="tri-result-sub" id="triResultSub"></div>'
    + '</div>'
    + '<div class="tri-field">'
      + '<div class="tri-lbl"><span>배당 지급일</span></div>'
      + '<input class="tri-inp" id="triDate" type="date" value="' + today + '">'
    + '</div>'
    + '<div class="tri-btn-row">'
      + '<button class="tri-btn cancel" onclick="closeModal(\'taxInput\')">취소</button>'
      + '<button class="tri-btn save" onclick="saveTaxRateInput()">저장 &amp; 학습</button>'
    + '</div>';

  // 실시간 계산
  var perShareInp = document.getElementById('triPerShare');
  var qtyInp = document.getElementById('triQty');
  var netInp = document.getElementById('triNet');
  var grossAuto = document.getElementById('triGrossAuto');
  var res = document.getElementById('triResult');

  function recalc(){
    var ps = Number(perShareInp.value)||0;
    var qty = Number(qtyInp.value)||0;
    var gross = ps * qty;
    grossAuto.innerHTML = fN(gross) + '<span class="sym">원</span>';

    var net = Number(netInp.value)||0;
    if(gross>0 && net>0 && net<=gross){
      var r = _calcEffectiveRate(gross, net);
      if(r != null){
        res.style.display = 'block';
        document.getElementById('triResultVal').innerHTML = r.toFixed(2) + '<span class="sym">%</span>';
        var taxAmt = gross - net;
        if(taxAmt === 0){
          document.getElementById('triResultSub').innerHTML = '세금 0원 (옵션프리미엄 등 비과세 분배금)<br>이 값이 일반 계좌 전체 배당 계산에 적용됩니다';
        } else {
          document.getElementById('triResultSub').innerHTML = '제세금 ' + fN(taxAmt) + '원 = ' + r.toFixed(2) + '%<br>이 값이 일반 계좌 전체 배당 계산에 적용됩니다';
        }
      } else {
        res.style.display = 'none';
      }
    } else {
      res.style.display = 'none';
    }
  }
  perShareInp.addEventListener('input', recalc);
  qtyInp.addEventListener('input', recalc);
  netInp.addEventListener('input', recalc);

  openModal('taxInput');
  setTimeout(function(){netInp.focus();}, 150);
}

// 수령액 저장 + 학습
function saveTaxRateInput(){
  var id = window._taxInputId;
  if(!id) return;
  var h = D.h.find(function(x){return x.id===id;});
  if(!h) return;
  var ps = Number(document.getElementById('triPerShare').value)||0;
  var qty = Number(document.getElementById('triQty').value)||0;
  var gross = ps * qty;
  var net = Number(document.getElementById('triNet').value)||0;
  var date = document.getElementById('triDate').value || new Date().toISOString().slice(0,10);
  if(ps<=0 || qty<=0){alert('세전 주당 배당금과 주식 수를 확인해주세요');return;}
  if(net<=0){alert('실제 입금액을 입력해주세요');return;}
  if(net > gross){alert('실지급액이 세전 배당금보다 클 수 없습니다\n(세전 주당 배당금을 확인해주세요)');return;}
  // net == gross → 세율 0% (옵션프리미엄 등 비과세 분배금 케이스) 허용
  var rate = _calcEffectiveRate(gross, net);
  if(rate == null){alert('세율 계산 실패');return;}

  // taxHistory 추가 + 평균 반영
  if(!Array.isArray(h.taxHistory)) h.taxHistory = [];
  h.taxHistory.push({date:date, gross:gross, net:net, rate:rate, qty:qty, amtPerShare:ps});
  h.taxHistory.sort(function(a,b){return String(a.date).localeCompare(String(b.date));});
  _updateTaxRateFromHistory(h);

  // 저장
  D.h = D.h.map(function(x){return x.id===id ? h : x;});
  save();
  closeModal('taxInput');
  try{ renderHistOv(id); }catch(e){}
  render();
}

// 수동 세율 직접 설정
function openTaxRateManual(id){
  var h = D.h.find(function(x){return x.id===id;});
  if(!h) return;
  var curRate = _getTaxRate(h);
  var inp = prompt('실효 배당세율(%)을 직접 입력하세요:\n(0 ~ 30 사이 숫자)', curRate.toFixed(2));
  if(inp == null) return;
  var r = parseFloat(inp);
  if(isNaN(r) || r<0 || r>30){alert('0~30 사이 숫자를 입력해주세요');return;}
  h.taxRate = r;
  h.taxRateMode = 'manual';
  D.h = D.h.map(function(x){return x.id===id ? h : x;});
  save();
  try{ renderHistOv(id); }catch(e){}
  render();
}

function fmt(n){n=Math.round(n||0);const a=Math.abs(n),s=n<0?'-':'';if(a>=100000000)return s+(a/100000000).toFixed(1)+'억원';if(a>=10000)return s+Math.round(a/10000)+'만원';return n.toLocaleString()+'원';}
function fN(n){return Math.round(n||0).toLocaleString();}
function dvN(df){return df==='주배당'?52:df==='격주배당'?26:df==='월배당'?12:df==='격월배당'?6:df==='분기배당'?4:df==='반기배당'?2:1;}
function isKR(s){return s&&(s.endsWith('.KS')||s.endsWith('.KQ'));}

// ────────────────────────────────────────────────────────────
// 배당 지급일 보정 (Yahoo/네이버는 배당락일만 제공 → payDate 보정)
// 데이터 소스: 한국 100대 기업 2024~2025 실제 배당락→지급 소요일 중앙값
