// 배당주기별 폴백 (매칭 실패 시)
const _DIV_LAG_FALLBACK_KR = {'분기배당':45,'반기배당':60,'월배당':15,'격월배당':15,'주배당':7,'격주배당':10,'연배당':49};
const _DIV_LAG_DEFAULT_KR  = 48; // 한국 100대 종목 전체 중앙값
const _DIV_LAG_DEFAULT_US  = 3; // 미국 ETF 관례: exDate가 분기 말일이라 +3일이면 같은 달 유지 (SCHD/VIG 등 3·6·9·12월 분기배당)

// 종목명 정규화 (매칭용: 공백 제거, 우선주 표기 제거)
function _normDivName(n){
  if(!n) return '';
  var s = String(n).trim().replace(/\s/g,'');
  // 우선주 표기 제거 (예: "삼성전자우" → "삼성전자")
  s = s.replace(/우[BC]?$/,'');
  return s;
}

// 배당락일(exDate) + 종목명/티커/주기 → 추정 지급일(payDate) 반환
// exDateStr: 'YYYY-MM-DD' 형태 문자열
// sym: 티커 (예: '005930.KS', 'AAPL')
// name: 종목명 (한국 매칭용, 없으면 빈 문자열)
// df: 배당주기 (한국 매칭 실패시 폴백용)
function getPayDate(exDateStr, sym, name, df){
  if(!exDateStr) return exDateStr;
  var d = new Date(exDateStr);
  if(isNaN(d.getTime())) return exDateStr;
  var isKor = isKR(sym||'');
  var lag;
  if(isKor){
    var key = _normDivName(name);
    if(key && DIV_PAY_LAG[key] != null){
      lag = DIV_PAY_LAG[key];
    } else if(df && _DIV_LAG_FALLBACK_KR[df] != null){
      lag = _DIV_LAG_FALLBACK_KR[df];
    } else {
      lag = _DIV_LAG_DEFAULT_KR;
    }
  } else {
    lag = _DIV_LAG_DEFAULT_US;
  }
  d.setDate(d.getDate() + lag);
  var y = d.getFullYear();
  var m = String(d.getMonth()+1).padStart(2,'0');
  var dd = String(d.getDate()).padStart(2,'0');
  return y+'-'+m+'-'+dd;
}

// 카페24 서버 API (Naver Finance 직접 호출 — CORS 없음, 가장 신뢰)
// SERVER_URL을 빈 문자열로 두면 현재 접속 도메인을 자동으로 사용 (divflow.kr, mycafe24.com 등)
const SERVER_URL = '';

function _toServerCode(code){
  let c = code.replace(/\.(KS|KQ)$/i,'');
  // 한국 ETF 접두사 A + 6자리 숫자만 제거 (예: A005930 → 005930)
  // 미국 티커(AVGO, AAPL, AMZN 등)의 맨 앞 A는 절대 제거하지 않음
  if(/^A\d{6}$/.test(c)) c = c.slice(1);
  // 6자리 숫자 코드만 padding (미국 티커는 그대로)
  return /^\d+$/.test(c) ? c.padStart(6,'0') : c;
}

async function serverPrice(code){
  try{
    let c=_toServerCode(code);
    // 서버 버그 우회: price.php가 맨 앞 A를 자동 제거 → A로 시작하는 미국 티커는 A 하나 더 붙임
    if(/^A[A-Z]{0,4}$/.test(c))c='A'+c;
    const ctrl=new AbortController();
    const t=setTimeout(()=>ctrl.abort(),5000);
    const r=await fetch(`${SERVER_URL}/price.php?code=${c}`,{signal:ctrl.signal});
    clearTimeout(t);
    if(!r.ok)return null;
    const j=await r.json();
    if(!j.price||j.price<=0)return null;
    if(j.currency&&j.currency!=='KRW'&&j.price<10000)return fxToKrw(j.price,j.currency,code);
    return j.price;
  }catch{return null;}
}

// 미국 주식 시세 - us_price.php 엔드포인트 사용 (별도 파일)
// 업로드: us_price.php 를 index.html 과 같은 폴더에 두면 됨
async function serverUSPrice(sym){
  if(!sym||!/^[A-Z]{1,5}$/.test(sym))return null;
  try{
    const ctrl=new AbortController();
    const t=setTimeout(()=>ctrl.abort(),6000);
    const r=await fetch(`${SERVER_URL}/us_price.php?sym=${encodeURIComponent(sym)}`,{signal:ctrl.signal});
    clearTimeout(t);
    if(!r.ok)return null;
    const j=await r.json();
    if(!j.price||j.price<=0)return null;
    return {price:j.price,currency:j.currency||'USD'};
  }catch{return null;}
}

// 코드 → 종목명 검증 (서버가 네이버 실제 종목명을 반환)
async function serverVerify(code){
  try{
    const c=_toServerCode(code);
    const ctrl=new AbortController();
    const t=setTimeout(()=>ctrl.abort(),4000);
    const r=await fetch(`${SERVER_URL}/price.php?verify=${c}`,{signal:ctrl.signal});
    clearTimeout(t);
    if(!r.ok)return null;
    return await r.json(); // {code, name, price, valid}
  }catch{return null;}
}

// 배당 내역 서버 조회
async function serverDividend(code){
  try{
    const c=_toServerCode(code);
    // KR 종목은 Yahoo Finance가 005930.KS 형식 필요 → .KS 유지
    const divCode=/^[0-9][0-9A-Z]{5}$/.test(c)?(c+'.KS'):c;
    const ctrl=new AbortController();
    const t=setTimeout(()=>ctrl.abort(),6000);
    const r=await fetch(`${SERVER_URL}/price.php?div=${divCode}`,{signal:ctrl.signal});
    clearTimeout(t);
    if(!r.ok)return null;
    const j=await r.json();
    return j.dividends||null;
  }catch{return null;}
}

async function naverDividend(sym){
  // 네이버 증권 배당 내역 (KS/KQ 종목)
  if(!isKR(sym)&&!isKRName(sym||''))return null;
  try{
    const code=sym.replace(/\.(KS|KQ)$/i,'').replace(/^A/,'').padStart(6,'0');
    const ctrl=new AbortController();
    const t=setTimeout(()=>ctrl.abort(),6000);
    // price.php에 naver_div 파라미터로 요청 (PHP쪽에서 처리)
    const r=await fetch(`${SERVER_URL}/price.php?naver_div=${code}`,{signal:ctrl.signal});
    clearTimeout(t);
    if(!r.ok)return null;
    const j=await r.json();
    return j.dividends||null;
  }catch{return null;}
}

