const PROXIES=[
  u=>'https://corsproxy.io/?'+encodeURIComponent(u),
  u=>'https://api.allorigins.win/raw?url='+encodeURIComponent(u),
  u=>'https://api.codetabs.com/v1/proxy?quest='+encodeURIComponent(u),
];

function naverACJsonp(q,limit){
  return new Promise(function(res,rej){
    var id='_nac_'+Date.now()+'_'+Math.random().toString(36).slice(2,6);
    var s=document.createElement('script');
    var done=false;
    function cleanup(){try{s.parentNode&&s.parentNode.removeChild(s);}catch{}delete window[id];}
    window[id]=function(data){if(done)return;done=true;cleanup();res(data);};
    s.onerror=function(){if(done)return;done=true;cleanup();rej();};
    setTimeout(function(){if(done)return;done=true;cleanup();rej();},4000);
    s.src='https://ac.finance.naver.com/ac?q='+encodeURIComponent(q)+'&q_enc=UTF-8&st=111&sug_typ=1&r_format=json&r_enc=UTF-8&r_lt='+(limit||20)+'&r_unicode=1&r_escape=1&callback='+id;
    document.head.appendChild(s);
  });
}
function acItems(data){return data&&(data.items||data.ac||[]);}

// 여러 Promise 중 첫 번째 truthy 값 반환 (실패/null 무시)
function firstValid(promises){
  return new Promise(function(resolve){
    var left=promises.length;
    if(!left){resolve(null);return;}
    promises.forEach(function(p){
      Promise.resolve(p).then(function(v){
        if(v!=null&&v!==false&&!isNaN(v)){resolve(v);}
        else if(--left===0)resolve(null);
      }).catch(function(){if(--left===0)resolve(null);});
    });
  });
}

async function yahooQuote(sym){
  const syms=[sym];
  const code=sym.split('.')[0];
  const ext=sym.split('.')[1];
  if(ext==='KS'||ext==='KQ'){
    if(/^A/i.test(code)){syms.unshift(code.slice(1)+'.'+ext);}
    else if(/^[0-9]/.test(code)){syms.push('A'+code+'.'+ext);}
  }
  function getUrls(s){return[
    'https://query1.finance.yahoo.com/v8/finance/chart/'+encodeURIComponent(s)+'?interval=1d&range=1d',
    'https://query2.finance.yahoo.com/v8/finance/chart/'+encodeURIComponent(s)+'?interval=1d&range=1d',
    'https://query1.finance.yahoo.com/v7/finance/quote?symbols='+encodeURIComponent(s),
  ];}
  function parseYahoo(text,s){
    try{
      const raw=text.startsWith('{"contents"')?JSON.parse(text).contents:text;
      const j=JSON.parse(raw);
      const meta=j?.chart?.result?.[0]?.meta;
      const p1=meta?.regularMarketPrice;
      if(p1&&p1>0)return{price:p1,currency:meta?.currency||'USD',name:meta?.longName||meta?.shortName||null,resolvedSym:s};
      const q=j?.quoteResponse?.result?.[0];
      const p2=q?.regularMarketPrice;
      if(p2&&p2>0)return{price:p2,currency:q?.currency||'USD',name:q?.longName||q?.shortName||null,resolvedSym:s};
    }catch{}
    return null;
  }
  for(const s of syms){
    for(const url of getUrls(s)){
      // 모든 프록시를 병렬 시도 → 먼저 온 유효값 사용
      const result=await Promise.race([
        firstValid(PROXIES.map(mkP=>
          fetch(mkP(url),{signal:AbortSignal.timeout?AbortSignal.timeout(3500):undefined})
            .then(r=>r.ok?r.text():null)
            .then(text=>text?parseYahoo(text,s):null)
            .catch(()=>null)
        )),
        new Promise(r=>setTimeout(()=>r(null),3500))
      ]);
      if(result)return result;
    }
  }
  throw new Error('조회실패');
}

// 미국주식 가격 조회 (Yahoo Finance, USD 반환)
async function fhQuote(sym){
  const res=await yahooQuote(sym);
  return res.price;
}

async function fetchOne(id){
  const h=D.h.find(x=>x.id===id);if(!h)return;
  // 비배당 자산(현금/코인/기타)은 시세 조회 불필요 - 유저가 수동 입력한 값 유지
  if(h.assetType&&h.assetType!=='stock'){LDS.delete(id);return;}
  LDS.add(id);render();
  const DONE=Symbol();
  const overall=new Promise(r=>setTimeout(()=>r(DONE),10000)); // 15→10s
  const work=(async()=>{
    let sym=h.sym||toSym(h.n);
    // 미국 티커에 잘못 붙은 .KS/.KQ 접미사 청소 (예: AVGO.KS → AVGO)
    if(sym && /^[A-Z]{1,5}\.(KS|KQ)$/i.test(sym)){
      sym=sym.replace(/\.(KS|KQ)$/i,'');
      D.h=D.h.map(x=>x.id===h.id?{...x,sym}:x);save();
    }
    // DB에서 정확한 코드 재확인 (잘못 저장된 sym 재매핑) — 미국 티커는 스킵
    if(sym && !_isUSSym(sym)){
      const _dbCheck=getAllDB().find(x=>x.n===h.n||(x.c&&x.c===sym.replace(/\.(KS|KQ)$/,'').replace(/^A/,'')));
      if(_dbCheck&&_dbCheck.c&&_dbCheck.c!==sym.replace(/\.(KS|KQ)$/,'').replace(/^A/,'')){
        const _newSym=_dbCheck.c+(_dbCheck.m==='KQ'?'.KQ':'.KS');
        D.h=D.h.map(x=>x.id===h.id?{...x,sym:_newSym}:x);save();
        sym=_newSym;
      }
    }
    let p,resolvedName=null;

    if(!sym||sym==='___KR___'||(!isKR(sym)&&isKRName(h.n)&&!_isUSSym(sym))){
      const found=await Promise.race([findKRSymbol(h.n),new Promise(r=>setTimeout(r,2000))]); // 4000→2000ms
      if(found)sym=found;
      else if(!sym||sym==='___KR___')sym=h.n.replace(/\s+/g,'')+'.KS';
    }

    if((isKR(sym)||isKRName(h.n))&&!_isUSSym(sym)){
      // serverPrice(네이버 직접) + Yahoo 동시 시도 → 먼저 온 것 사용
      // serverPrice는 종목명도 함께 반환 → 코드 오매핑 감지
      const code=sym.replace(/\.(KS|KQ)$/,'').replace(/^A/,'');
      const srvCode=_toServerCode(sym);
      const srvFullP=(async()=>{
        try{
          const ctrl=new AbortController();
          const t=setTimeout(()=>ctrl.abort(),5000);
          const r=await fetch(`${SERVER_URL}/price.php?code=${srvCode}`,{signal:ctrl.signal});
          clearTimeout(t);
          if(!r.ok)return null;
          const j=await r.json();
          if(!j.price||j.price<=0)return null;
          // 코드-이름 불일치 감지 (30% 이하 글자 겹침 = 잘못된 코드)
          if(j.name&&h.n){
            const isKoreanName=/[\uAC00-\uD7A3]/.test(h.n);
            // 숫자 코드(441640) 또는 영문 티커(AAPL)로만 저장된 경우: syncDivInfo에서 복구 중이므로 skip
            const isJustCode=/^[0-9][0-9A-Z]{5}(\.(KS|KQ))?$/i.test(h.n)||/^[A-Z]{1,6}$/.test(h.n);
            // 한글 종목명이면 Yahoo는 항상 영문 반환 → 비교 무의미
            if(!isKoreanName&&!isJustCode){
              const sn=j.name.replace(/[\s()（）]/g,'').toLowerCase();
              const hn=h.n.replace(/[\s()（）]/g,'').toLowerCase();
              if(sn.length>2&&hn.length>2){
                const overlap=hn.split('').filter(c=>sn.includes(c)).length;
                D.h=D.h.map(x=>x.id===id?{...x,
                  nameWarn:overlap/hn.length<0.3?j.name:undefined
                }:x);
              }
            } else {
              D.h=D.h.map(x=>x.id===id?{...x,nameWarn:undefined}:x);
            }
          }
          return j.currency&&j.currency!=='KRW'&&j.price<10000
            ?fxToKrw(j.price,j.currency,sym):j.price;
        }catch{return null;}
      })();
      const yahooP=Promise.race([
        yahooQuote(sym),
        new Promise((_,r)=>setTimeout(r,3500))
      ]).then(res=>{
        if(res.resolvedSym&&res.resolvedSym!==sym)sym=res.resolvedSym;
        return Math.round(res.price);
      }).catch(()=>null);

      p=await firstValid([srvFullP,yahooP]);

      if(!p){
        const code2=sym.replace(/\.(KS|KQ)$/,'').replace(/^A/,'');
        p=await firstValid([
          Promise.race([stooqPrice(code2),new Promise(r=>setTimeout(r,2500))]),
          Promise.race([naverPrice(code2),new Promise(r=>setTimeout(r,2500))])
        ]);
      }
      if(/^\d{6}$/.test(h.n)){resolvedName=await resolveKoreanName(code)||h.n;}
    }else{
      // 미국 주식 - 우선순위: 서버 us_price 엔드포인트 → 기존 code= (A우회) → Yahoo 직접
      const srvUSP = serverUSPrice(sym).then(r=>r?fxToKrw(r.price,r.currency,sym):null).catch(()=>null);
      // 기존 code= 엔드포인트 (A자동제거 버그 우회)
      const srvSym = /^A[A-Z]{0,4}$/.test(sym) ? 'A'+sym : sym;
      const srvP = (async()=>{
        try{
          const ctrl=new AbortController();
          const t=setTimeout(()=>ctrl.abort(),6000);
          const r=await fetch(`${SERVER_URL}/price.php?code=${encodeURIComponent(srvSym)}`,{signal:ctrl.signal});
          clearTimeout(t);
          if(!r.ok)return null;
          const j=await r.json();
          if(!j.price||j.price<=0)return null;
          return j.currency&&j.currency!=='KRW'?fxToKrw(j.price,j.currency,sym):j.price;
        }catch{return null;}
      })();
      // Yahoo 직접 (CORS 프록시 경유) - 대부분 실패하지만 혹시 뚫리면
      const directP=Promise.race([
        yahooQuote(sym).then(res=>fxToKrw(res.price,res.currency||'USD',sym)),
        new Promise((_,r)=>setTimeout(r,4000))
      ]).catch(()=>null);
      p=await firstValid([srvUSP, srvP, directP]);
    }
    // 알파뉴메릭 코드 ETF hardcode 가격 fallback
    if(!p||isNaN(p)){
      var _HCPRICE={'0132K0':9260};
      var _sc=(sym||'').replace(/\.(KS|KQ)$/i,'');
      if(_HCPRICE[_sc])p=_HCPRICE[_sc];
    }
    if(!p||isNaN(p))throw new Error('가격 없음');
    D.h=D.h.map(x=>x.id===id?{...x,cur:p,sym,err:0,...(resolvedName?{n:resolvedName}:{})}:x);
    D.at=new Date().toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'});save();
  })();
  try{
    const result=await Promise.race([work,overall]);
    if(result===DONE){
      // 타임아웃 - 스피너 먼저 끄고 백그라운드 재시도
      LDS.delete(id);render();
      setTimeout(async()=>{
        // 스피너 없이 조용히 재시도
        try{await work;}catch{}
        D.h=D.h.map(x=>x.id===id&&!x.cur?{...x,err:1}:x);
        render();
      },3000);
      return;
    }else{await work.catch(()=>{D.h=D.h.map(x=>x.id===id?{...x,err:1}:x);});}
  }catch{
    // work가 overall보다 먼저 reject된 경우 → err:1 설정
    D.h=D.h.map(x=>x.id===id?{...x,err:1}:x);
  }finally{
    LDS.delete(id);render(); // 반드시 스피너 제거
  }
}

// 네이버 시세 직접 조회 (국내주식 최종 fallback)
// 네이버 시세 직접 fetch (CORS 허용 여부 먼저 확인)
// stooq.com - CORS 허용, 한국 주식 커버 (Yahoo에 없는 신규 ETF도 포함)
async function stooqPrice(code){
  const cleaned=(code||'').replace(/^A/i,'').replace(/\.(KS|KQ)$/i,'');
  // 방어 가드: 한국 코드 형식(6자리 숫자, 혹은 알파뉴메릭 ETF 코드)만 허용
  // 순수 알파벳 미국 티커(예: AVGO → "VGO")가 잘못 넘어오는 것을 차단
  if(!/^[0-9]{3,6}$/.test(cleaned) && !/^[0-9]{1,4}[A-Z0-9]{1,3}[0-9]?$/i.test(cleaned)) return null;
  if(!/[0-9]/.test(cleaned)) return null; // 숫자 하나도 없으면 한국 코드 아님
  const c=cleaned.padStart(6,'0');
  for(const suf of['.ks','.kq']){
    const url=`https://stooq.com/q/l/?s=${c}${suf}&f=sd2t2ohlcv&h&e=csv`;
    for(const mkP of[u=>u,...PROXIES]){
      try{
        const ctrl=new AbortController();
        const t=setTimeout(()=>ctrl.abort(),3000); // 개별 fetch 3초 타임아웃
        const r=await fetch(mkP(url),{signal:ctrl.signal});
        clearTimeout(t);
        if(!r.ok)continue;
        const text=await r.text();
        if(!text||text.includes('N/D'))continue;
        const lines=text.trim().split('\n');
        if(lines.length<2)continue;
        const cols=lines[1].split(',');
        const p=parseFloat(cols[6]); // Close price
        if(p>100)return Math.round(p);
      }catch{}
    }
  }
  return null;
}

async function naverPriceDirect(c){
  const urls=[
    `https://polling.finance.naver.com/api/realtime/domestic/stock/${c}`,
    `https://m.stock.naver.com/api/stock/${c}/basic`,
    `https://fchart.stock.naver.com/sise.nhn?symbol=${c}&timeframe=day&count=1&requestType=0`,
  ];
  function parse(text){
    const fc=text.match(/data=['"][\d]+\|[\d]+\|[\d]+\|[\d]+\|([\d]+)\|/);
    if(fc){const p=+fc[1];if(p>100)return p;}
    try{
      const raw=text.startsWith('{"contents"')?JSON.parse(text).contents:text;
      const j=JSON.parse(raw);
      const r=j?.result||j?.data||{};
      const v=r?.tradePrice??r?.closePrice??r?.price??j?.closePrice??j?.currentPrice??j?.tradePrice??j?.price;
      const p=Math.round(Number(String(v??0).replace(/,/g,'')));
      if(p>100)return p;
    }catch{}
    return 0;
  }
  for(const url of urls){
    try{
      const r=await fetch(url,{signal:AbortSignal.timeout?AbortSignal.timeout(3000):undefined});
      if(r.ok){const p=parse(await r.text());if(p>100)return p;}
    }catch{}
  }
  return 0;
}

async function naverPriceJsonp(code){
  const c=code.replace(/^A/i,'').replace(/\.(KS|KQ)$/,'').padStart(6,'0');
  // 1) 직접 fetch 시도 (CORS 허용 시 가장 빠름)
  const direct=await naverPriceDirect(c);
  if(direct>100)return direct;
  // 2) CORS 프록시 순차 시도
  return null;
}

async function naverPrice(code){
  function parseNum(v){if(v==null)return 0;const n=Number(String(v).replace(/,/g,''));return isNaN(n)?0:Math.round(n);}
  function unwrap(text){
    // allorigins/corsproxy가 {"contents":"..."} 로 감싸는 경우 unwrap
    if(!text)return '';
    try{if(text.startsWith('{"contents"')){const j=JSON.parse(text);return j.contents||j.data||text;}}catch{}
    return text;
  }
  function parsePrice(raw){
    // fchart XML: data='날짜|시가|고가|저가|종가|거래량'
    const fc=raw.match(/data=['"][\d]+\|[\d]+\|[\d]+\|[\d]+\|([\d]+)\|/);
    if(fc){const p=parseNum(fc[1]);if(p>100)return p;}
    // JSON
    try{
      const j=JSON.parse(raw);
      const r=j?.result||j?.data||{};
      const p1=parseNum(r?.tradePrice??r?.closePrice??r?.price??r?.현재가);
      if(p1>100)return p1;
      const p2=parseNum(j?.closePrice??j?.currentPrice??j?.tradePrice??j?.stockPrice??j?.price);
      if(p2>100)return p2;
    }catch{}
    // HTML - 다양한 패턴
    const patterns=[
      /id=["']now_val["'][^>]*>([\d,]+)/,
      /id=["']now_value["'][^>]*>([\d,]+)/,
      /"regularMarketPrice":([\d.]+)/,
      /class=["']no_today["'][^>]*>[\s\S]*?<em[^>]*>([\d,]+)/,
    ];
    for(const pat of patterns){const m=raw.match(pat);if(m){const p=parseNum(m[1]);if(p>100)return p;}}
    return 0;
  }
  const c=code.replace(/^A/i,'').replace(/\.(KS|KQ)$/,'').padStart(6,'0');

  // 1) 직접 fetch 시도 (CORS 허용 시)
  const directP=await naverPriceDirect(c);
  if(directP>100)return directP;

  // 2) 프록시 순차 시도
  const allProxies=[
    u=>'https://corsproxy.io/?'+encodeURIComponent(u),
    u=>'https://api.allorigins.win/get?url='+encodeURIComponent(u),
    u=>'https://api.allorigins.win/raw?url='+encodeURIComponent(u),
  ];
  const allUrls=[
    `https://fchart.stock.naver.com/sise.nhn?symbol=${c}&timeframe=day&count=1&requestType=0`,
    `https://polling.finance.naver.com/api/realtime/domestic/stock/${c}`,
  ];
  for(const url of allUrls){
    for(const mkP of allProxies){
      try{
        const r=await fetch(mkP(url));
        if(!r.ok)continue;
        const text=await r.text();
        if(!text||text.length<5)continue;
        const p=parsePrice(unwrap(text));  // 반드시 unwrap 후 파싱
        if(p>100)return p;
      }catch{}
    }
  }
  return null;
}

async function findKRSymbol(name){
  // Yahoo Finance 검색으로 정확한 심볼 찾기 (PRIMARY)
  try{
    const url='https://query1.finance.yahoo.com/v1/finance/search?q='+encodeURIComponent(name)+'&lang=ko-KR&region=KR&quotesCount=5&newsCount=0';
    for(const mkP of[u=>u,...PROXIES]){
      try{
        const r=await fetch(mkP(url));if(!r.ok)continue;
        const text=await r.text();
        const j=JSON.parse(text.startsWith('{"contents"')?JSON.parse(text).contents:text);
        const quotes=j?.quotes||[];
        // 정확히 일치하는 이름 우선
        const exact=quotes.find(q=>
          (q.shortname===name||q.longname===name)&&
          ((q.symbol||'').endsWith('.KS')||(q.symbol||'').endsWith('.KQ'))
        );
        if(exact)return exact.symbol;
        // 한국 종목 중 첫 번째
        const krHit=quotes.find(q=>(q.symbol||'').endsWith('.KS')||(q.symbol||'').endsWith('.KQ'));
        if(krHit)return krHit.symbol;
      }catch{}
    }
  }catch{}
  return null;
}

async function resolveKoreanName(code){
  // 네이버 AC에서 코드로 한국어 종목명 조회
  try{
    const url='https://ac.finance.naver.com/ac?q='+encodeURIComponent(code)+'&q_enc=UTF-8&st=111&sug_typ=1&u_os=Android&u_ie=utf8&u_timezoneoffset=540&collapse=1&r_format=json&r_enc=UTF-8&r_lt=20&r_unicode=1&r_escape=1';
    for(const mkP of PROXIES){
      try{
        const r=await fetch(mkP(url));if(!r.ok)continue;
        const text=await r.text();
        const raw=text.startsWith('{"contents"')?JSON.parse(text).contents:text;
        const j=JSON.parse(raw);
        const found=(j.items||[]).flat().find(x=>x[1]===code);
        if(found)return found[0];
      }catch{}
    }
  }catch{}
  return null;
}
async function fhDivs(sym){
  const syms=[sym];
  const code=sym.split('.')[0], ext=sym.split('.')[1];
  if(ext==='KS'||ext==='KQ'){
    if(/^A/i.test(code)) syms.push(code.slice(1)+'.'+ext);
    else syms.push('A'+code+'.'+ext);
  }
  const krCode=code.replace(/^A/i,'').padStart(6,'0');

  // KR: 네이버 모바일 배당 API (CORS 프록시)
  if(ext==='KS'||ext==='KQ'){
    // 네이버 모바일
    const mobileUrl=`https://m.stock.naver.com/api/stock/${krCode}/finance/dividend`;
    for(const mkP of [u=>u,...PROXIES]){
      try{
        const r=await fetch(mkP(mobileUrl));
        if(!r.ok)continue;
        const j=await r.json();
        const list=j?.dividendList||j?.list||j||[];
        if(Array.isArray(list)&&list.length>0){
          const result=list.map(d=>({
            date:d.dividendPaymentDate||d.date||'',
            amount:parseFloat(d.dividendAmount||d.dividend||d.amount||0)
          })).filter(d=>d.amount>0&&d.date).sort((a,b)=>b.date.localeCompare(a.date)).slice(0,12);
          if(result.length)return result;
        }
      }catch{}
    }

    // 네이버 PC HTML 폴백
    const naverUrl=`https://finance.naver.com/item/sise_div.naver?code=${krCode}`;
    for(const mkP of PROXIES){
      try{
        const r=await fetch(mkP(naverUrl));
        if(!r.ok)continue;
        const text=await r.text();
        const rows=[...text.matchAll(/(\d{4}\.\d{2}\.\d{2})[^<]*<[^>]+>[^<]*<[^>]+>([\d,]+)원/g)];
        if(rows.length>0){
          return rows.slice(0,12).map(m=>({
            date:m[1].replace(/\./g,'-'),
            amount:parseInt(m[2].replace(/,/g,''))
          })).filter(d=>d.amount>0);
        }
      }catch{}
    }
  }

  // 미국/KR Yahoo Finance 시도
  for(const s of syms){
    const url=`https://query1.finance.yahoo.com/v8/finance/chart/${encodeURIComponent(s)}?interval=1mo&range=2y&events=dividends`;
    for(const mkP of [u=>u,...PROXIES]){
      try{
        const r=await fetch(mkP(url));
        if(!r.ok)continue;
        const text=await r.text();
        const j=JSON.parse(text.startsWith('{"contents"')?JSON.parse(text).contents:text);
        const divEvents=j?.chart?.result?.[0]?.events?.dividends;
        if(!divEvents)continue;
        const divArr=Object.values(divEvents)
          .map(d=>({date:new Date(d.date*1000).toISOString().split('T')[0],amount:d.amount||0}))
          .filter(d=>d.amount>0)
          .sort((a,b)=>b.date.localeCompare(a.date))
          .slice(0,12);
        if(divArr.length>0)return divArr;
      }catch{}
    }
  }

  return[];
}

// Yahoo 데이터 없는 한국 ETF → 배당률 기반 추정값 생성
function estimateDivHistory(h){
  if(!h.isDv||!h.dy||h.dy<=0)return[];
  const cur=h.cur||h.avg;
  if(!cur)return[];
  const n=dvN(h.df); // 연간 지급 횟수
  const perPayment=cur*h.dy/100/n; // 지급당 주당 배당금
  const result=[];
  const now=new Date();
  for(let i=0;i<Math.min(6,n);i++){
    const d=new Date(now);
    d.setMonth(d.getMonth()-(i*(12/n)));
    result.push({
      date:d.toISOString().split('T')[0],
      amount:perPayment,
      estimated:true
    });
  }
  return result;
}

async function fetchDivs(id){
  const h=D.h.find(x=>x.id===id);if(!h)return;
  const btn=document.querySelector(`button[onclick="fetchDivs(${id})"]`);
  if(btn){btn.textContent='⏳ 조회 중...';btn.disabled=true;}
  try{
    const sym=h.sym||toSym(h.n);
    let divs=null;
    const isKorean = (isKR(sym) || isKRName(h.n||'')) && !_isUSSym(sym);

    // 국내 종목 → 네이버 우선 (한국 증권사 실데이터, 정확)
    // 해외 종목 → Yahoo 우선 (서버 프록시 경유)
    if(isKorean){
      divs = await naverDividend(sym);
      if(!divs||!divs.length) divs = await serverDividend(sym);
    } else {
      divs = await serverDividend(sym);
      if(!divs||!divs.length) divs = await naverDividend(sym);
    }
    // 3순위: 브라우저 직접 시도 (CORS 될 경우 대비)
    if(!divs||!divs.length) divs=await fhDivs(sym);
    // 4순위: 알파뉴메릭 코드 ETF 하드코딩 fallback (서버가 처리 못하는 경우)
    if(!divs||!divs.length){
      var _hc=D.h.find(x=>x.id===id);
      var _code=(_hc&&_hc.sym||'').replace(/\.(KS|KQ)$/i,'');
      var _HARDCODED={
        '0132K0':{divs:[
          {payDate:'2026-03-17',date:'2026-03-13',amount:195},
          {payDate:'2026-02-20',date:'2026-02-13',amount:200},
          {payDate:'2026-01-19',date:'2026-01-15',amount:212},
          {payDate:'2025-12-17',date:'2025-12-15',amount:25}
        ],price:9260,df:'월배당',isDv:true,dy:parseFloat((212*12/9260*100).toFixed(2))}
      };
      if(_HARDCODED[_code]){
        divs=_HARDCODED[_code].divs;
        // 가격도 없으면 갱신
        if(_hc&&(!_hc.cur||_hc.cur<=0)){
          D.h=D.h.map(x=>x.id===id?{...x,cur:_HARDCODED[_code].price,err:0}:x);save();
        }
      }
    }

    // ── payDate 보정: API 소스는 배당락일만 제공. 종목별 실제 지연일로 payDate 추정 ──
    // (DIV_PAY_LAG 테이블 우선 → 배당주기 폴백 → 국가 기본값)
    // 📌 exDate 필드가 별도로 있고 payDate도 이미 정확하면 그대로 유지 (네이버 특수 케이스)
    if(divs && divs.length){
      var _hForLag = D.h.find(x=>x.id===id);
      var _symForLag = _hForLag ? (_hForLag.sym||'') : '';
      var _nameForLag = _hForLag ? (_hForLag.n||'') : '';
      var _dfForLag = _hForLag ? (_hForLag.df||'') : '';
      divs = divs.map(function(dv){
        // 이미 exDate와 payDate가 별도로 있고 서로 다르면 → 정확한 데이터이므로 보존
        if(dv.exDate && dv.payDate && dv.exDate !== dv.payDate){
          return dv;
        }
        // 그 외: date 또는 payDate를 배당락일로 간주하고 보정
        var exStr = dv.date || dv.exDate || dv.payDate || '';
        if(!exStr) return dv;
        return Object.assign({}, dv, { payDate: getPayDate(exStr, _symForLag, _nameForLag, _dfForLag) });
      });
    }

    // ── 미국 배당주 자동 인식: isDv/dy/df 업데이트 ──
    // US 종목은 추가 시 estimateDividend()가 영문 티커를 모르므로 isDv:false, dy:0으로 저장됨.
    // 실제 배당 내역이 조회되면 여기서 자동으로 isDv/dy/df를 산출해 시뮬에 반영.
    let extraFields = {};
    if(divs && divs.length > 0){
      const hNow = D.h.find(x=>x.id===id);
      const isUS = hNow && !isKR(hNow.sym||'') && !isKRName(hNow.n||'');
      const isKRStock = hNow && (isKR(hNow.sym||'')||isKRName(hNow.n||''));
      if((isUS||isKRStock) && (!hNow.isDv || !hNow.dy)){
        // 날짜 간격으로 배당 주기 감지 (2건 이상이면 간격 판단, 1건이면 개수 기반)
        const histForFreq = divs
          .map(d=>({_t:new Date(d.payDate||d.date||'').getTime(),_a:d.amount||0}))
          .filter(d=>!isNaN(d._t)&&d._a>0)
          .sort((a,b)=>b._t-a._t);
        // ─── 주기 결정: DB 힌트 → 이름 힌트 → 간격 감지(3건+) → 기존 df ───
        const dbHint_f = _dbHint(hNow.sym||'', hNow.n||'');
        const nameHint_f = _nameFreqHint(hNow.n||'');
        const detectedInterval = _detectDivFreq(histForFreq);
        let df, freq;
        if(dbHint_f && dbHint_f.df){
          df = dbHint_f.df;
        } else if(nameHint_f){
          df = nameHint_f;
        } else if(detectedInterval && histForFreq.length >= 3){
          df = detectedInterval.df;
        } else {
          const existingDf = String(hNow.df||'').trim();
          const validDfs = ['월배당','격월배당','분기배당','반기배당','연배당','주배당','격주배당'];
          df = validDfs.includes(existingDf) ? existingDf : '분기배당';
        }
        freq = dvN(df);
        if(df==='격월배당') freq = 6;
        if(df==='격주배당') freq = 26;
        if(df==='주배당') freq = 52;

        // 연간 배당금 추정: avg * freq
        const avg_div = histForFreq.reduce((s,d)=>s+d._a,0) / Math.max(histForFreq.length,1);
        const annualDivRaw = avg_div * freq;
        const priceKRW = hNow.cur || hNow.avg;
        if(isKRStock){
          // 국내주식: amount가 KRW 단위
          if(priceKRW > 0 && annualDivRaw > 0){
            const dy = parseFloat((annualDivRaw / priceKRW * 100).toFixed(2));
            extraFields = { isDv:true, dy, df };
          }
        } else {
          // 미국주식: amount가 USD 단위
          const priceUSD = priceKRW / (D.rate||1380);
          if(priceUSD > 0 && annualDivRaw > 0){
            const dy = parseFloat((annualDivRaw / priceUSD * 100).toFixed(2));
            extraFields = { isDv:true, dy, df };
          }
        }
      }
    }
    // KR 종목: divs 없어도 isDv:true 유지 (배당 데이터 미조회 상태 보존)
    const _hNowFinal=D.h.find(x=>x.id===id);
    const _keepIsDv=_hNowFinal&&(isKR(_hNowFinal.sym||'')||isKRName(_hNowFinal.n||''))&&_hNowFinal.isDv&&(!divs||!divs.length);
    if(_keepIsDv) extraFields={...extraFields,isDv:true};
    // 강화: divs 가져오는 데 성공했으면 (실제 배당 이력 있음) 무조건 isDv:true
    if(divs && divs.length && divs.some(d=>Number(d.amount||0)>0)){
      extraFields={...extraFields,isDv:true};
      if(!extraFields.df){
        const existingDf=String((_hNowFinal&&_hNowFinal.df)||'').trim();
        const validDfs=['월배당','격월배당','분기배당','반기배당','연배당','주배당','격주배당'];
        extraFields.df=validDfs.includes(existingDf)?existingDf:'분기배당';
      }
    }
    D.h=D.h.map(x=>x.id===id?{...x,...extraFields,divHistory:divs||[],divErr:0}:x);save();
  }catch{D.h=D.h.map(x=>x.id===id?{...x,divHistory:[],divErr:1}:x);}
  render();
  if(document.getElementById('histOv').classList.contains('show'))openBuyHistory(id);
}

function renderDivHistory(h,id){
  const isKorean = isKR(h.sym||'') || isKRName(h.n||'');
  const isUsSym = !isKorean && h.sym && /^[A-Z]{1,5}$/.test(h.sym);
  if(!h.isDv && !isKorean && !isUsSym) return'';
  if(h.divHistory==null){
    return`<div class="sh-card full" style="text-align:center">
      <div style="font-size:12px;color:var(--c-label)">⏳ 배당 내역 조회 중...</div>
    </div>`;
  }
  if(!h.divHistory.length){
    return`<div class="sh-card full" style="text-align:center">
      <div style="font-size:13px;color:var(--c-label)">📭 배당 지급 이력 없음</div>
    </div>`;
  }
  const isUS=!(isKR(h.sym||'')||isKRName(h.n||''));
  // 외화 통화 정보 (HKD/JPY/EUR/GBP 대응, 없으면 USD)
  const _fCurDv=_symForeignCurrency(h.sym);
  const rate=_fCurDv?(D.fxMap&&D.fxMap[_fCurDv.cur]||D.rate||1380):(D.rate||1380);
  const _sign=_fCurDv?_fCurDv.sign:'$';
  const _dp=_fCurDv?_fCurDv.dp:2;
  function fmtDiv(a){
    if(isUS) return`<span style="color:var(--c-blue-700)">${_sign}${a.toFixed(Math.max(_dp,4)).replace(/0+$/,'').replace(/\.$/,'')}</span> <span style="font-size:10px;color:var(--c-label)">(≈${fN(Math.round(a*rate))}원)</span>`;
    return fN(Math.round(a))+'원';
  }
  function fmtMyDiv(a){
    if(isUS){
      const fx=(a*h.qty).toFixed(_dp);
      const krw=fmt(Math.round(a*h.qty*rate));
      return `<span style="color:var(--c-blue-700)">${_sign}${fx}</span> <span style="color:var(--c-label)">≈${krw}</span>`;
    }
    return fmt(Math.round(a*h.qty));
  }
  function fmtTot(tot){
    if(isUS){
      const fx=_sign+tot.toFixed(Math.max(_dp,4)).replace(/0+$/,'').replace(/\.$/,'');
      const krw=fmt(Math.round(tot*rate));
      return `<span style="color:var(--c-blue-700)">${fx}</span> <span style="font-size:10px;font-weight:600;color:var(--c-label)">≈${krw}/주</span>`;
    }
    return fN(Math.round(tot))+'원';
  }
  function fmtTotMy(tot){
    if(isUS){
      const fx=_sign+(tot*h.qty).toFixed(_dp);
      const krw=fmt(Math.round(tot*h.qty*rate));
      return `<span style="color:var(--c-blue-700)">${fx}</span> <span style="color:var(--c-label)">≈${krw}</span>`;
    }
    return fmt(Math.round(tot*h.qty));
  }

  const isEstimated=h.divHistory.some(d=>d.estimated);
  const display=h.divHistory.slice(0,6);  // 최근 6번
  const tot=display.reduce((s,d)=>s+(d.amount||0),0);
  const rows=display.map(d=>{
    const a=d.amount||0;
    return`<div class="sh-div-line">
      <div class="sh-div-date">${d.payDate||d.date||''}</div>
      <div class="sh-div-dot"></div>
      <div class="sh-div-per">${fmtDiv(a)}</div>
      <div class="sh-div-mine">${fmtMyDiv(a)}</div>
    </div>`;
  }).join('');
  return`<div class="sh-card full">
    <div class="sh-div-head">
      <span class="sh-div-ttl">📋 최근 ${display.length}번 배당${isEstimated?' <span style="font-size:9.5px;color:var(--c-label);font-weight:600;margin-left:3px">(추정)</span>':''}</span>
      <span class="sh-div-sum">주당 ${fmtTot(tot)}</span>
    </div>
    <div class="sh-div-sub">내 수령액 합계 <span style="color:var(--c-text);font-weight:700">${fmtTotMy(tot)}</span></div>
    ${rows}
  </div>`;
}
// 외화 → KRW 변환 (USD/HKD/JPY/EUR/GBP 지원, 나머지는 USD로 fallback)
// sym이 제공되면 접미사 기반 통화 override (Yahoo/서버가 해외 주식을 USD로 잘못 반환하는 경우 대비)
function fxToKrw(price, currency, sym){
  if(!price||isNaN(price))return price;
  // 심볼 접미사로 통화 강제 판별 (가장 확실한 정보원)
  if(sym){
    const ext=String(sym).split('.').pop().toUpperCase();
    const symCurMap={
      'HK':'HKD', 'T':'JPY', 'L':'GBP',
      'DE':'EUR','PA':'EUR','AS':'EUR','BR':'EUR','MI':'EUR',
      'MC':'EUR','LS':'EUR','VI':'EUR','HE':'EUR','ST':'EUR'
    };
    if(symCurMap[ext]) currency=symCurMap[ext];
  }
  if(!currency||currency==='KRW')return price;
  const fx=(D.fxMap&&D.fxMap[currency])||D.rate||1380;
  return Math.round(price*fx);
}

// 심볼 접미사 기반 외화 정보 (가격 표시용: 통화 기호, 소수점 자릿수)
function _symForeignCurrency(sym){
  if(!sym)return null;
  const ext=String(sym).split('.').pop().toUpperCase();
  const map={
    'HK':{cur:'HKD', sign:'HK$', dp:2},
    'T' :{cur:'JPY', sign:'¥',   dp:0},
    'L' :{cur:'GBP', sign:'£',   dp:2},
    'DE':{cur:'EUR', sign:'€',   dp:2},'PA':{cur:'EUR', sign:'€', dp:2},
    'AS':{cur:'EUR', sign:'€',   dp:2},'BR':{cur:'EUR', sign:'€', dp:2},
    'MI':{cur:'EUR', sign:'€',   dp:2},'MC':{cur:'EUR', sign:'€', dp:2},
    'LS':{cur:'EUR', sign:'€',   dp:2},'VI':{cur:'EUR', sign:'€', dp:2},
    'HE':{cur:'EUR', sign:'€',   dp:2},'ST':{cur:'EUR', sign:'€', dp:2}
  };
  return map[ext]||null;
}
async function fetchRate(){
  // 방법 0: 카페24 서버 API (USD/KRW만) - 캐시 우회해서 항상 최신 환율
  try{
    const ctrl=new AbortController();
    const t=setTimeout(()=>ctrl.abort(),5000);
    const res=await fetch(`${SERVER_URL}/price.php?rate=1&_=${Date.now()}`,{signal:ctrl.signal});
    clearTimeout(t);
    if(res.ok){const j=await res.json();if(j.rate&&j.rate>100){D.rate=j.rate;}}
  }catch{}
  // 방법 1: Yahoo Finance USDKRW=X (USD 환율 fallback)
  if(!D.rate||D.rate<100){
    try{
      const res=await yahooQuote('USDKRW=X');
      if(res&&res.price>0)D.rate=Math.round(res.price);
    }catch{}
  }
  // 방법 2: frankfurter.app (HKD/JPY/EUR/GBP 동시 조회, USD도 포함)
  const url='https://api.frankfurter.app/latest?from=KRW&to=USD,HKD,JPY,EUR,GBP';
  for(const mkP of PROXIES){
    try{
      const r=await fetch(mkP(url));
      if(!r.ok)continue;
      const text=await r.text();
      const d=JSON.parse(text.startsWith('{"contents"')?JSON.parse(text).contents:text);
      if(d&&d.rates){
        // KRW→FX 환율을 FX→KRW로 역산 (1/rate)
        D.fxMap=D.fxMap||{};
        if(d.rates.USD)D.fxMap.USD=Math.round(1/d.rates.USD);
        if(d.rates.HKD)D.fxMap.HKD=+(1/d.rates.HKD).toFixed(2);
        if(d.rates.JPY)D.fxMap.JPY=+(1/d.rates.JPY).toFixed(3);
        if(d.rates.EUR)D.fxMap.EUR=Math.round(1/d.rates.EUR);
        if(d.rates.GBP)D.fxMap.GBP=Math.round(1/d.rates.GBP);
        break;
      }
    }catch{}
  }
  // fxMap이 못 받아왔어도 기본값 설정 (하드코딩 안전망)
  D.fxMap=D.fxMap||{};
  if(!D.fxMap.USD)D.fxMap.USD=D.rate||1380;
  if(!D.fxMap.HKD)D.fxMap.HKD=180;
  if(!D.fxMap.JPY)D.fxMap.JPY=9.2;
  if(!D.fxMap.EUR)D.fxMap.EUR=1500;
  if(!D.fxMap.GBP)D.fxMap.GBP=1750;
  save();render();
}

async function refreshAll(){
  if(LDALL||!D.h.length)return;
  LDALL=true;setBusy(true);showG('시세 조회 중...');
  try{
    await fetchRate();
    // 전체 병렬 조회 (종목당 5초 타임아웃)
    await Promise.allSettled(D.h.map(async h=>{
      // 비배당 자산(현금/코인/기타)은 시세 조회 스킵
      if(h.assetType&&h.assetType!=='stock')return;
      LDS.add(h.id);
      try{
        let sym=h.sym||toSym(h.n);
        const to=new Promise((_,rej)=>setTimeout(()=>rej(new Error('timeout')),5000));
        let p;
        if((isKR(sym)||isKRName(h.n))&&!_isUSSym(sym)){
          if(!isKR(sym)){const f=await findKRSymbol(h.n);if(f)sym=f;}
          try{const res=await Promise.race([yahooQuote(sym),to]);p=Math.round(res.price);if(res.resolvedSym)sym=res.resolvedSym;}catch{}
          if(!p){const code=sym.replace(/\.(KS|KQ)$/,'').replace(/^A/,'');p=await serverPrice(code)||await stooqPrice(code)||await naverPrice(code);}
        }else{
          // 미국/해외 주식 - yahooQuote가 currency 반환 → fxToKrw로 환산 (sym 전달로 접미사 override)
          const res=await Promise.race([yahooQuote(sym),to]);
          p=fxToKrw(res.price,res.currency||'USD',sym);
          if(res.resolvedSym)sym=res.resolvedSym;
        }
        // 알파뉴메릭 코드 ETF hardcode 가격 fallback
    if(!p||isNaN(p)){
      var _HCPRICE={'0132K0':9260};
      var _sc=(sym||'').replace(/\.(KS|KQ)$/i,'');
      if(_HCPRICE[_sc])p=_HCPRICE[_sc];
    }
    if(!p||isNaN(p))throw new Error('가격 없음');
        D.h=D.h.map(x=>x.id===h.id?{...x,cur:p,sym,err:0}:x);
      }catch{
        D.h=D.h.map(x=>x.id===h.id?{...x,err:1}:x);
      }
      LDS.delete(h.id);
    }));
    D.at=new Date().toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'});
    save();
  }finally{
    hideG();setBusy(false);LDALL=false;LDS.clear();render();
  }
}

// ── 자동 시세 갱신 (10초마다, 화면 보는 동안) ──
setInterval(async()=>{
  if(document.hidden)return;
  if(LDALL||SILENT_REFRESHING||!D.h.length)return;
  await silentRefresh();
},10000);

// 깜빡임 없는 조용한 시세 업데이트
async function silentRefresh(){
  if(LDALL||SILENT_REFRESHING||!D.h.length)return;
  SILENT_REFRESHING=true;
  try{
    await fetchRate();
    for(const h of D.h){
      try{
        let sym=h.sym||toSym(h.n);
        const timeout=new Promise((_,rej)=>setTimeout(()=>rej(new Error('timeout')),7000));
        // Promise.race가 이기면 timeout은 버려지므로 unhandled rejection 방지
        timeout.catch(()=>{});
        let p;
        if((isKR(sym)||isKRName(h.n))&&!_isUSSym(sym)){
          if(!isKR(sym)){const f=await findKRSymbol(h.n);if(f)sym=f;}
          try{const res=await Promise.race([yahooQuote(sym),timeout]);p=Math.round(res.price);if(res.resolvedSym&&res.resolvedSym!==sym)sym=res.resolvedSym;}catch{}
          if(!p){const code=sym.replace(/\.(KS|KQ)$/,'').replace(/^A/,'');p=await serverPrice(code)||await stooqPrice(code)||await naverPrice(code);}
        }else{
          // 미국 주식: 서버 us_price → 서버 code= (A우회) → Yahoo 직접
          let usp=await serverUSPrice(sym);
          if(usp)p=Math.round(usp*D.rate);
          if(!p)p=await serverPrice(sym);
          if(!p){
            try{p=Math.round((await Promise.race([fhQuote(sym),timeout]))*D.rate);}catch{}
          }
        }
        if(!p||isNaN(p))continue;
        D.h=D.h.map(x=>x.id===h.id?{...x,cur:p,sym,err:0}:x);
        // 서버 캐시 업데이트
        if(isKR(sym)){const code=sym.replace(/\.(KS|KQ)$/,'').replace(/^A/,'');fetch(SERVER_URL+'/price.php?code='+code).catch(()=>{});}
        // DOM 직접 업데이트 (재렌더 없이)
        const card=document.querySelector('#hList [data-id="'+h.id+'"]');
        if(card){
          const cur=p,avgCost=h.avgCost||h.avg,qty=h.qty;
          const dispQty=(()=>{
            if(FLT==='all')return qty;
            const buys=h.buys||[];
            if(!buys.length)return qty;
            return buys.filter(b=>FLT==='tax'?_isTaxAcct(b.acct):!_isTaxAcct(b.acct)).reduce((s,b)=>s+b.qty,0);
          })();
          const val=cur*dispQty;
          const pp=(cur-avgCost)*dispQty;
          const pp2=avgCost?((cur-avgCost)/avgCost*100):0;
          const pnlColor=pp>=0?'#e63946':'#2563eb';
          const valEl=card.querySelector('.sval2');
          const pnlEl=card.querySelector('.spnl');
          if(valEl)valEl.textContent=fmt(val);
          if(pnlEl){pnlEl.style.color=pnlColor;pnlEl.innerHTML=(pp>=0?'+':'')+fmt(pp)+'<span style="font-size:12px;font-weight:500">('+pp2.toFixed(2)+'%)</span>';}
        }
      }catch{}
    }
    D.at=new Date().toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'});
    save();
    _updateHeaderOnly();
  }catch{}
  finally{SILENT_REFRESHING=false;}
}

function _updateHeaderOnly(){
  const H=D.h;
  const tV=H.reduce((s,h)=>(h.cur||h.avg)*h.qty+s,0);
  const tC=H.reduce((s,h)=>h.avgCost*h.qty+s,0);
  const pnl=tV-tC,pct=tC>0?pnl/tC*100:0;
  const tvEl=document.getElementById('hTotal');
  const pnlEl=document.getElementById('hPnl');
  if(tvEl){tvEl.textContent=fmt(tV);tvEl.classList.toggle('has-amount', tV>0);}
  if(pnlEl){
    pnlEl.className='pnl '+(pnl>=0?'pos':'neg');
    if(H.length){
      const arrow=pnl>=0?'↑':'↓';
      pnlEl.innerHTML=`<span style="display:inline-flex;align-items:center;justify-content:center;width:14px;height:14px;border-radius:50%;background:${pnl>=0?'#22c55e':'#ef4444'};color:#fff;font-size:8px;font-weight:900;line-height:1">${arrow}</span><span>${pnl>=0?'+':''}${fmt(pnl)}</span><span style="opacity:.85">${pct>=0?'+':''}${pct.toFixed(2)}%</span>`;
    } else { pnlEl.innerHTML=''; }
    pnlEl.style.color='';
  }
  const botUpd=document.getElementById('botUpd');
  if(botUpd)botUpd.textContent=D.at?`업데이트 ${D.at} · USD/KRW ${fN(D.rate)}원`:'';
}


