let _sess=localStorage.getItem('kakao_sess')||'';
let _nick=localStorage.getItem('kakao_nick')||'';

async function kakaoLogin(){
  if(!Kakao.isInitialized()) Kakao.init('86f8319f6722cc6363d7464850e678f4');
  try{
    // 새 SDK 방식
    const result = await Kakao.API.request({url:'/v2/user/me'}).catch(async ()=>{
      // 로그인 후 다시 시도
      await new Promise((res,rej)=>Kakao.Auth.authorize({redirectUri:window.location.origin+'/auth.php',success:res,fail:rej}));
    });
  }catch(e){}
  // 팝업 방식
  Kakao.Auth.authorize({
    redirectUri: window.location.origin + '/auth.php'
  });
}
function kakaoLogout(){
  _sess='';_nick='';
  localStorage.removeItem('kakao_sess');
  localStorage.removeItem('kakao_nick');
  updateLoginUI();
  alert('로그아웃됐습니다.');
}
