/* ===== REINVEST SIMULATION ===== */
function parseOcrText(text){
  var N=function(s){return parseInt(String(s).replace(/[,\s]/g,'').replace(/[Ool]/g,function(c){return c==='O'||c==='o'?'0':'1';}),10);};
  var lines=text.split(/[\n\r]+/).map(function(l){return l.trim();}).filter(Boolean);
  var full=text.replace(/\s+/g,' ');
  var results=[];
  var taxKw=['절세','ISA','IRP','연금','연금저축','개인형','종합자산관리','신연금','각시','퇴직연금','DC형','DB형','세금우대'];
  var genKw=['위탁','일반계좌','일반 계좌'];
  var seen=new Set();

  function acctOf(nearby){
    if(taxKw.some(function(k){return nearby.includes(k);}))return{acct:'tax',acctName:taxKw.find(function(k){return nearby.includes(k);})||'절세'};
    if(genKw.some(function(k){return nearby.includes(k);}))return{acct:'general',acctName:'위탁'};
    return{acct:'general',acctName:'일반'};
  }
  function push(name,qty,price,acctObj,code){
    if(!name||qty<=0||price<=0||qty>5000000||price<5)return;
    var k=name+'|'+qty+'|'+price;
    if(seen.has(k))return;
    seen.add(k);
    results.push({name:name.slice(0,30),code:code||null,qty:qty,avgPrice:price,acct:acctObj.acct,acctName:acctObj.acctName});
  }
  function cleanN(s){return s.replace(/[^\uAC00-\uD7A3A-Za-z0-9\s\-]/g,'').replace(/\s{2,}/g,' ').trim();}

  // ── 패턴 A: "N주 · M원" (계좌별 목록 형식) ──
  var pA=/([가-힣A-Za-z][가-힣A-Za-z0-9\s\-]*?)\s+([\d,]+)주\s*[··・\-]\s*([\d,]+)원/g;
  var mA;
  while((mA=pA.exec(text))!==null){
    var nm=cleanN(mA[1]), qty=N(mA[2]), price=N(mA[3]);
    var ctx=text.slice(Math.max(0,mA.index-80),mA.index+80);
    push(nm,qty,price,acctOf(ctx));
  }

  // ── 패턴 B: 보유량/평단가 형식 (단일 종목 상세 화면) ──
  var qty2=0,price2=0,name2='';
  var mQty=full.match(/보유[량주]?\s*([\d,]+)\s*주/);
  var mPrc=full.match(/평단[가]?\s*([\d,]+)\s*원/);
  if(mQty)qty2=N(mQty[1]);
  if(mPrc)price2=N(mPrc[1]);
  if(qty2>0&&price2>0){
    // 종목명: 6자리 코드 앞에 있는 한글 이름 찾기
    var mName=full.match(/([가-힣A-Z][가-힣A-Za-z0-9\s\-]{3,40}?)\s+\d{6}/);
    if(mName)name2=cleanN(mName[1]);
    else{
      // 첫 번째 긴 한글 텍스트
      for(var i=0;i<lines.length;i++){
        if(/[가-힣]{3}/.test(lines[i])&&lines[i].length>=4&&!/\d{4}/.test(lines[i])){name2=cleanN(lines[i]);break;}
      }
    }
    // 코드
    var mCode=full.match(/\b(\d{6})\b/);
    var code2=mCode?mCode[1]:null;
    // 계좌: 전체 텍스트 기준
    var acct2=acctOf(full);
    push(name2||'종목',qty2,price2,acct2,code2);
  }

  // ── 패턴 C: "N주\n M원" 두 줄에 걸친 경우 ──
  for(var i=0;i<lines.length-1;i++){
    var mQ=lines[i].match(/^([\d,]+)\s*주$/);
    var mP=lines[i+1].match(/^([\d,]+)\s*원$/);
    if(mQ&&mP){
      var qty3=N(mQ[1]), price3=N(mP[1]);
      var ctx3=lines.slice(Math.max(0,i-4),i+3).join(' ');
      var nm3='';
      for(var j=i-1;j>=Math.max(0,i-4);j--){
        if(/[가-힣A-Z]/.test(lines[j])&&lines[j].length>=3){nm3=cleanN(lines[j]);break;}
      }
      push(nm3||'종목',qty3,price3,acctOf(ctx3));
    }
  }

  return results;
}

function cleanName(s){
  return s.replace(/[^\uAC00-\uD7A3A-Za-z0-9\s\-]/g,'').replace(/\s{2,}/g,' ').trim().slice(0,30);
}

/* ===== REINVEST COMPOUND SIMULATION ===== */
/* ===== 세전/세후 토글 ===== */
window._divTaxMode = 'after'; // 기본: 세후
function _setTaxMode(mode){
  window._divTaxMode = mode;
  ['taxAfter','taxBefore','ctaxAfter','ctaxBefore'].forEach(function(id){
    var el = document.getElementById(id);
    if(!el) return;
    var isAfter = id.includes('After');
    var active = (mode === 'after') === isAfter;
    if(active){
      el.style.background = isAfter
        ? 'linear-gradient(135deg,#1d4ed8,#3b82f6)'
        : 'linear-gradient(135deg,#7c3aed,#a78bfa)';
      el.style.color = '#fff';
      el.style.borderColor = 'transparent';
      el.style.boxShadow = isAfter
        ? '0 4px 14px rgba(29,78,216,.35)'
        : '0 4px 14px rgba(124,58,237,.35)';
    } else {
      el.style.background = '#fff';
      el.style.color = '#94a3b8';
      el.style.borderColor = '#e2e8f0';
      el.style.boxShadow = 'none';
    }
  });
  _mountSimTaxFab();
  render();
}


function _escHtml(s){return String(s==null?'':s).replace(/[&<>"']/g,function(m){return({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'})[m];});}
function _syncSimTaxFab(){
  var fab=document.getElementById('simTaxFab');
  if(!fab)return;
  if(TAB==='sim'||TAB==='chart'){
    fab.classList.add('show');
  }else{
    fab.classList.remove('show');
  }
}
function _mountSimTaxFab(){
  var fab=document.getElementById('simTaxFab');
  if(!fab){
    fab=document.createElement('button');
    fab.id='simTaxFab';
    fab.className='sim-tax-fab';
    fab.type='button';
    fab.onclick=function(e){ if(e){e.preventDefault();e.stopPropagation();} _setTaxMode(window._divTaxMode==='after'?'before':'after'); };
    // 앞뒤 두 면 한번만 구성
    fab.innerHTML=
      '<div class="sim-tax-fab-inner">'
      +'<div class="sim-tax-fab-face sim-tax-fab-front">'
        +'<div class="sim-tax-fab-t">세후</div>'
        +'<div class="sim-tax-fab-s">AFTER</div>'
      +'</div>'
      +'<div class="sim-tax-fab-face sim-tax-fab-back">'
        +'<div class="sim-tax-fab-t">세전</div>'
        +'<div class="sim-tax-fab-s">BEFORE</div>'
      +'</div>'
      +'</div>';
    document.body.appendChild(fab);
  }
  // 상태는 클래스만 토글 (CSS가 rotateY 처리)
  fab.classList.remove('before','after');
  fab.classList.add(window._divTaxMode==='after' ? 'after' : 'before');
  _syncSimTaxFab();
}
// 월 카드 HTML 생성 헬퍼 (renderSim과 _setSimMonth가 공유)
function _buildMonthCardHtml(sm, monthIdx, taxLbl){
  if(!sm) return '';
  const hasData = sm.t>0;
  const chipGeneral = sm.general>0 ? `<div class="month-detail-chip general"><span class="month-detail-chip-label">일반</span><span class="month-detail-chip-val">${fmt(Math.round(sm.general))}</span></div>` : '';
  const chipTax = sm.tax>0 ? `<div class="month-detail-chip tax"><span class="month-detail-chip-label">절세</span><span class="month-detail-chip-val">${fmt(Math.round(sm.tax))}</span></div>` : '';
  const chipsBoth = (chipGeneral||chipTax) ? `<div class="month-detail-chips">${chipGeneral}${chipTax}</div>` : '';
  const stockRows = sm.details&&sm.details.length ? sm.details.map(it=>{
    const acctDots = [
      it.general>0?`<span class="split-chip general">${fmt(Math.round(it.general))}</span>`:'',
      it.tax>0?`<span class="split-chip tax">${fmt(Math.round(it.tax))}</span>`:''
    ].filter(Boolean).join('');
    return `<div class="month-stock-row"><div class="month-stock-top"><div class="month-stock-name" title="${_escHtml(it.full||it.n)}">${_escHtml(it.full||it.n)}</div><div class="month-stock-right"><div class="month-stock-accts">${acctDots}</div><div class="month-stock-val">${fmt(Math.round(it.v))}</div></div></div></div>`;
  }).join('') : `<div class="month-empty">${monthIdx+1}월에는 예상 입금이 없습니다.</div>`;
  return `<div class="month-detail-wrap">
    <div class="month-detail-summary">
      <div class="month-detail-total-row">
        <div class="month-detail-title">${monthIdx+1}월 ${taxLbl} 배당</div>
        <div class="month-detail-total">${hasData?fmt(Math.round(sm.t)):'—'}</div>
      </div>
      ${chipsBoth}
    </div>
    ${hasData?`<div class="month-stock-divider">종목별 내역</div><div class="month-stock-list">${stockRows}</div>`:''}
  </div>`;
}

function _setSimMonth(i, dir){
  const prev = Number(window._simSelectedMonth);
  const cur = Number.isFinite(prev) ? prev : i;
  if(cur === i) return;

  const monthMeta = window._simMonthMeta;
  const taxLbl = window._simTaxLbl || '세후';
  const track = document.getElementById('monthSlideTrack');

  // 월바 차트 active 상태 업데이트
  document.querySelectorAll('#simCont .mcol').forEach((el, idx)=>{
    el.classList.toggle('active', idx===i);
    const bar = el.querySelector('.mbar');
    if(bar && monthMeta){
      const m = monthMeta[idx];
      const hasDiv = m && m.t>0;
      bar.style.background = (idx===i)
        ? (hasDiv ? 'linear-gradient(180deg,var(--acct-general-text) 0%,var(--acct-general) 100%)' : 'var(--c-muted)')
        : (hasDiv ? 'linear-gradient(180deg,var(--acct-general) 0%,var(--acct-general-g1) 100%)' : 'var(--c-border)');
    }
  });

  if(!track || !monthMeta){
    window._simSelectedMonth = i;
    try{ renderSim(window._simDvH||[], window._simTV||0); }catch(e){}
    return;
  }

  window._simSelectedMonth = i;
  _animateMonthSlide(track, cur, i, monthMeta, taxLbl);
}

// 3-card 트랙에서 부드럽게 슬라이드 + 카드 재배치
function _animateMonthSlide(track, fromIdx, toIdx, monthMeta, taxLbl){
  if(!track) return;
  const direction = toIdx > fromIdx ? 1 : -1;  // 1: 다음달(오른쪽→왼쪽), -1: 이전달
  // 현재 translate 상태 (중앙=-100%). direction에 따라 -200% 또는 0%로 이동
  track.classList.remove('dragging');
  track.classList.add('animating');
  track.style.transform = 'translate3d(' + (direction > 0 ? -200 : 0) + '%, 0, 0)';

  const onEnd = function(){
    track.removeEventListener('transitionend', onEnd);
    track.classList.remove('animating');
    // 카드 내용 재배치: toIdx 기준으로 [prev|cur|next] 다시 채움
    _rebuildMonthCards(track, toIdx, monthMeta, taxLbl);
    track.style.transform = 'translate3d(-100%, 0, 0)';
  };
  track.addEventListener('transitionend', onEnd);
  // 안전장치
  setTimeout(function(){
    if(track.classList.contains('animating')){
      track.removeEventListener('transitionend', onEnd);
      onEnd();
    }
  }, 600);
}

// [prev | current | next] 3장 카드를 toIdx 기준으로 재구성
function _rebuildMonthCards(track, toIdx, monthMeta, taxLbl){
  const prev = toIdx > 0 ? toIdx - 1 : -1;
  const next = toIdx < 11 ? toIdx + 1 : -1;
  const emptyHtml = '<div style="min-height:100px"></div>';
  const buildOne = function(idx){
    return idx >= 0 ? _buildMonthCardHtml(monthMeta[idx], idx, taxLbl) : emptyHtml;
  };
  track.innerHTML =
    '<div class="month-slide-card" data-idx="'+prev+'">'+buildOne(prev)+'</div>' +
    '<div class="month-slide-card" data-idx="'+toIdx+'">'+buildOne(toIdx)+'</div>' +
    '<div class="month-slide-card" data-idx="'+next+'">'+buildOne(next)+'</div>';
}
// ─── iOS 스타일 라이브 드래그 스와이프 (손가락 따라오기 + 속도 기반 스냅) ───
function _bindSimMonthSwipe(){
  var host = document.querySelector('#simCont .month-detail-host');
  if(!host || host._swipeBound) return;
  host._swipeBound = true;

  var state = {
    sx:0, sy:0, lastX:0, lastT:0, velocity:0,
    tracking:false, horizontal:false, decided:false,
    startTime:0, hostW:0
  };

  function getTrack(){ return host.querySelector('.month-slide-track'); }

  host.addEventListener('touchstart', function(e){
    if(!e.touches || !e.touches[0]) return;
    var track = getTrack();
    if(!track || track.classList.contains('animating')) return; // 애니 중 무시
    var t = e.touches[0];
    state.sx = state.lastX = t.clientX;
    state.sy = t.clientY;
    state.lastT = state.startTime = Date.now();
    state.velocity = 0;
    state.tracking = true;
    state.horizontal = false;
    state.decided = false;
    state.hostW = host.offsetWidth || 360;
    e.stopPropagation();
  }, {passive:true});

  host.addEventListener('touchmove', function(e){
    if(!state.tracking || !e.touches || !e.touches[0]) return;
    var t = e.touches[0];
    var dx = t.clientX - state.sx;
    var dy = t.clientY - state.sy;

    // 방향 결정 (최초 10px 이상 움직임에서)
    if(!state.decided){
      if(Math.abs(dx) < 8 && Math.abs(dy) < 8) return; // 너무 작은 움직임
      state.decided = true;
      state.horizontal = Math.abs(dx) > Math.abs(dy);
    }
    if(!state.horizontal) return;

    // 속도 측정 (최근 touchmove 기준)
    var now = Date.now();
    var dt = now - state.lastT;
    if(dt > 0){
      state.velocity = (t.clientX - state.lastX) / dt; // px/ms
    }
    state.lastX = t.clientX;
    state.lastT = now;

    if(e.cancelable) e.preventDefault();
    e.stopPropagation();

    var track = getTrack();
    if(!track) return;

    // 경계 처리: 첫 달에서 오른쪽으로, 마지막 달에서 왼쪽으로 → rubber band
    var cur = Number(window._simSelectedMonth) || 0;
    var effectiveDx = dx;
    if((cur === 0 && dx > 0) || (cur === 11 && dx < 0)){
      // 고무줄 효과: 저항 적용 (dx의 30%만 이동)
      effectiveDx = dx * 0.3;
    }

    // 실시간 드래그: translate3d로 손가락 따라감
    track.classList.remove('animating');
    track.classList.add('dragging');
    var translatePct = -100 + (effectiveDx / state.hostW * 100);
    track.style.transform = 'translate3d(' + translatePct + '%, 0, 0)';
  }, {passive:false});

  host.addEventListener('touchend', function(e){
    if(!state.tracking) return;
    state.tracking = false;
    if(!state.horizontal) return;

    var t = (e.changedTouches && e.changedTouches[0]) ? e.changedTouches[0] : null;
    if(!t) return;
    var dx = t.clientX - state.sx;
    var elapsed = Date.now() - state.startTime;
    var velocity = state.velocity; // px/ms

    var track = getTrack();
    if(!track) return;

    var cur = Number(window._simSelectedMonth) || 0;
    var hostW = state.hostW || 360;

    // 스냅 결정: 거리 30% 이상 OR 속도 0.3px/ms 이상 (iOS 기준)
    var distPct = Math.abs(dx) / hostW;
    var shouldSnap = distPct > 0.30 || Math.abs(velocity) > 0.3;
    var direction = (dx < 0) ? 1 : -1; // 1: 다음달, -1: 이전달
    // 속도가 강하게 반대로 움직이면 속도 우선
    if(Math.abs(velocity) > 0.3){
      direction = velocity < 0 ? 1 : -1;
    }

    // 경계 체크: 더 이상 넘길 수 없는 경우 스냅 취소
    if(direction === 1 && cur >= 11) shouldSnap = false;
    if(direction === -1 && cur <= 0) shouldSnap = false;

    if(shouldSnap){
      // 목표 월로 스냅 애니메이션
      var target = cur + direction;
      track.classList.remove('dragging');
      track.classList.add('animating');
      track.style.transform = 'translate3d(' + (direction > 0 ? -200 : 0) + '%, 0, 0)';

      var onEnd = function(){
        track.removeEventListener('transitionend', onEnd);
        track.classList.remove('animating');
        window._simSelectedMonth = target;
        // 월바 업데이트
        document.querySelectorAll('#simCont .mcol').forEach(function(el, idx){
          el.classList.toggle('active', idx === target);
          var bar = el.querySelector('.mbar');
          var meta = window._simMonthMeta;
          if(bar && meta){
            var m = meta[idx];
            var hasDiv = m && m.t > 0;
            bar.style.background = (idx === target)
              ? (hasDiv ? 'linear-gradient(180deg,var(--acct-general-text) 0%,var(--acct-general) 100%)' : 'var(--c-muted)')
              : (hasDiv ? 'linear-gradient(180deg,var(--acct-general) 0%,var(--acct-general-g1) 100%)' : 'var(--c-border)');
          }
        });
        _rebuildMonthCards(track, target, window._simMonthMeta, window._simTaxLbl || '세후');
        track.style.transform = 'translate3d(-100%, 0, 0)';
      };
      track.addEventListener('transitionend', onEnd);
      setTimeout(function(){
        if(track.classList.contains('animating')){
          track.removeEventListener('transitionend', onEnd);
          onEnd();
        }
      }, 600);
    } else {
      // 취소: 원위치로 부드럽게 복귀
      track.classList.remove('dragging');
      track.classList.add('animating');
      track.style.transform = 'translate3d(-100%, 0, 0)';
      setTimeout(function(){
        track.classList.remove('animating');
      }, 450);
    }

    e.stopPropagation();
  }, {passive:false});

  // 터치 취소 (전화 등)
  host.addEventListener('touchcancel', function(){
    state.tracking = false;
    var track = getTrack();
    if(track){
      track.classList.remove('dragging');
      track.classList.add('animating');
      track.style.transform = 'translate3d(-100%, 0, 0)';
      setTimeout(function(){ track.classList.remove('animating'); }, 450);
    }
  }, {passive:true});
}
