function openReinvest(){
  const ss=window._simSS||[];
  if(!ss.length){alert('배당 시뮬 데이터가 없습니다.');return;}
  // 50년치 데이터 계산 (캐시)
  _reinvCompute();
  window._reinvYrs=window._reinvYrs||5;
  _reinvBuildUI();
  // (탭에서 직접 표시)
}

// 50년 전체 시뮬 1회 계산
function _reinvCompute(){
  // 현재 설정(ON/OFF)에 따른 snap + 비교(반대 설정) snap 모두 계산
  const _origOn = !!window._reinvExtraOn;
  // 1) 현재 설정
  _reinvBuildSnapInternal();
  // H는 현재 기준으로 저장된 거 유지
  const savedSnap = window._reinvSnap;
  const savedH = window._reinvH;
  // 2) 비교용 (반대 설정) — snap만 갈아끼우고 다시 계산
  // try/finally로 에러 시에도 반드시 원복
  try {
    window._reinvExtraOn = !_origOn;
    _reinvBuildSnapInternal();
    window._reinvSnapCmp = window._reinvSnap;
  } finally {
    window._reinvExtraOn = _origOn;
    window._reinvSnap = savedSnap;
    window._reinvH = savedH;
  }
}

function _reinvBuildSnapInternal(){
  const ss=window._simSS||[];
  if(!ss.length){window._reinvSnap=[];window._reinvH=[];return;}

  const map={};
  ss.forEach(x=>{
    const id=x.id;
    if(!map[id]) map[id]={
      id,n:x.n,sym:x.sym||'',df:x.df,
      cur:x.cur||x.avg,
      qty:0, annAfterAcc:0
    };
    map[id].qty        += x.qty;
    map[id].annAfterAcc+= x.annAfter;
  });

  const H=Object.values(map).filter(h=>h.annAfterAcc>0&&h.qty>0&&h.cur>0);
  if(!H.length){window._reinvSnap=[];window._reinvH=[];return;}

  const totalV=H.reduce((s,h)=>s+h.cur*h.qty,0);
  H.forEach(h=>{
    h.frac = h.qty;
    h.pc   = h.cur;
    h.wt   = h.pc*h.qty/totalV;
    h.annPSAfter = h.annAfterAcc / h.qty;
  });

  const initAnnDiv=H.reduce((s,h)=>s+h.annAfterAcc,0);
  let cash=0, cumDiv=0;
  const snap=[{yr:0, monDiv:initAnnDiv/12, annDiv:initAnnDiv, cumDiv:0}];

  const extraOn = !!window._reinvExtraOn;
  const extraAmt = Math.max(0, Number(window._reinvExtraAmt)||0) * 10000;
  const extraPerMonth = extraOn ? extraAmt : 0;

  for(let m=0;m<40*12;m++){
    const mi=m%12;
    H.forEach(h=>{
      const ann=h.frac*h.annPSAfter;
      const pp=ann/dvN(h.df);
      let recv=0;
      if(h.df==='월배당') recv=ann/12;
      else if(h.df==='분기배당'&&[2,5,8,11].includes(mi)) recv=pp;
      else if(h.df==='반기배당'&&[5,11].includes(mi)) recv=pp;
      else if(h.df==='연배당'&&mi===11) recv=pp;
      else recv=ann/12;
      cash+=recv; cumDiv+=recv;
    });
    cash += extraPerMonth;
    if(cash>0){H.forEach(h=>{h.frac+=cash*h.wt/h.pc;});cash=0;}
    if((m+1)%12===0){
      const yr=(m+1)/12;
      const annDiv=H.reduce((s,h)=>s+h.frac*h.annPSAfter,0);
      snap.push({yr, monDiv:annDiv/12, annDiv, cumDiv});
    }
  }
  window._reinvSnap=snap;
  window._reinvH=H;
}

// UI 최초 렌더 (슬라이더 포함)
function _reinvBuildUI(){
  // 이전 차트 인스턴스 항상 정리 (innerHTML 덮어쓰기 전 - canvas ref 유실 방지)
  if(window._reinvCI){ try{window._reinvCI.destroy();}catch(e){} window._reinvCI=null; }
  // 이전 FAB도 제거 — 재마운트 시 이벤트 중복 바인딩 방지
  var _oldFab = document.getElementById('reinvYrFab');
  if(_oldFab){ _oldFab.remove(); }
  const snap=window._reinvSnap||[];
  const H=window._reinvH||[];
  if(!snap.length){document.getElementById('reinvestCont').innerHTML='<div style="padding:30px;text-align:center;color:#aaa">데이터 없음</div>';return;}

  const initMonDiv=snap[0].monDiv;
  const YRS=Math.min(Math.max(window._reinvYrs||5,1),40);

  // 밀레스톤 감지 (2배/3배/5배/10배 도달 연도)
  _reinvRecalcMilestones();
  const _ms = window._reinvMilestones || [];
  const _msMap={}; _ms.forEach(m=>{_msMap[m.yr]=m;});
  // 프리셋 + 밀레스톤 합산 (중복 제거, 정렬)
  const _presets=[1,5,10,15,20,25,30,35,40];
  const _allChips=[..._presets,..._ms.map(m=>m.yr)].filter((v,i,a)=>a.indexOf(v)===i).sort((a,b)=>a-b);

  document.getElementById('reinvestCont').innerHTML=`
<!-- 히어로 -->
<div id="riHero" style="background:linear-gradient(125deg,#0a0e1a 0%,var(--c-dark-1) 40%,var(--c-blue-900) 100%);border-radius:16px;padding:18px 18px 20px;margin-bottom:12px;color:#fff;position:relative;overflow:hidden">
  <div style="position:absolute;top:-25px;right:-25px;width:120px;height:120px;border-radius:50%;background:radial-gradient(circle,rgba(147,197,253,.22),transparent 60%);filter:blur(16px);pointer-events:none"></div>
  <div style="position:absolute;inset:0;background-image:linear-gradient(rgba(147,197,253,.05) 1px,transparent 1px),linear-gradient(90deg,rgba(147,197,253,.05) 1px,transparent 1px);background-size:22px 22px;mask-image:radial-gradient(ellipse at top right,black 20%,transparent 70%);pointer-events:none"></div>
  <div style="position:relative;z-index:2">
    <div id="riHeroLbl" style="font-size:9px;font-weight:800;color:var(--c-dark-label);letter-spacing:2px;text-transform:uppercase;opacity:.85">MONTHLY DIVIDEND · ${YRS}년 후</div>
    <div id="riHeroAmt" style="font-family:'Plus Jakarta Sans','Noto Sans KR',sans-serif;font-size:38px;font-weight:900;letter-spacing:-1.4px;line-height:1;margin-top:10px;background:linear-gradient(95deg,#e0e7ff,#a5b4fc);-webkit-background-clip:text;background-clip:text;-webkit-text-fill-color:transparent"></div>
    <div style="margin-top:10px;display:flex;gap:6px;flex-wrap:wrap">
      <span id="riMult" style="background:rgba(255,255,255,.12);border:1px solid rgba(147,197,253,.25);padding:4px 10px;border-radius:99px;font-size:11px;font-weight:800;color:#fff;letter-spacing:-.2px"></span>
      <span id="riCagr" style="background:rgba(110,231,183,.18);border:1px solid rgba(110,231,183,.35);padding:4px 10px;border-radius:99px;font-size:11px;font-weight:800;color:#6ee7b7;letter-spacing:-.2px"></span>
    </div>
    <div id="riHeroSub" style="margin-top:10px;font-size:10.5px;color:#cbd5e1;font-weight:500;letter-spacing:-.1px;opacity:.8"></div>
    <div id="riMsBadge" style="display:none;margin-top:10px;padding:5px 12px;border-radius:99px;font-size:11px;font-weight:800;align-self:flex-start;letter-spacing:-.1px"></div>
  </div>
</div>

<div id="riTopControls" style="margin-bottom:14px;background:#fff;border:1px solid var(--c-border);border-radius:14px;overflow:hidden">
  <!-- 상단 2-column 히어로: 왼쪽 연도+마일스톤 / 오른쪽 추가투자 컨트롤 -->
  <div class="ri-hero-row">
    <div class="ri-hero-left">
      <span id="riYrLbl" class="ri-yr-grad">${YRS}</span>
      <span class="ri-hero-left-sub">년 후</span>
      <span class="ri-ms-mini">
        <span>마일스톤</span>
        <span id="riMsBanner" style="display:none;padding:2px 7px;background:linear-gradient(95deg,var(--c-gold-100),#fde68a);border:1px solid var(--c-gold-400);border-radius:99px;font-family:'Plus Jakarta Sans','Noto Sans KR',sans-serif;font-size:9.5px;font-weight:800;color:var(--c-gold-900);letter-spacing:-.1px;text-transform:none;margin-left:2px">★ 2배 달성</span>
      </span>
    </div>
    <div class="ri-hero-right">
      <!-- 1행: 타이틀 + 토글 -->
      <div class="ri-hero-line">
        <div style="width:30px;height:30px;border-radius:8px;background:linear-gradient(135deg,#e0e7ff,#a5b4fc);display:flex;align-items:center;justify-content:center;color:#3730a3;font-weight:900;font-size:15px;flex-shrink:0;letter-spacing:-.5px">+</div>
        <div class="ri-hero-lbl">
          <div class="ri-hero-title">매월 추가 투자</div>
          <div class="ri-hero-desc">배당 + 내 돈 재투자</div>
        </div>
        <button id="riExtraSw" onclick="_reinvToggleExtra()" style="width:42px;height:24px;border-radius:99px;background:#d4cfc0;border:none;position:relative;cursor:pointer;transition:background .2s;flex-shrink:0;padding:0">
          <span style="position:absolute;top:2px;left:2px;width:20px;height:20px;border-radius:50%;background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.25);transition:left .2s" id="riExtraSwThumb"></span>
        </button>
      </div>
      <!-- 2행: 월 매수 + 입력 -->
      <div id="riExtraInputWrap" class="ri-hero-line">
        <span class="ri-hero-row-label">월 매수</span>
        <div class="ri-compact-input-wrap">
          <input id="riExtraInput" type="number" inputmode="numeric" min="0" step="10" value="100" oninput="_reinvChangeExtra(this.value)">
          <span class="suf">만원</span>
        </div>
      </div>
    </div>
  </div>
  <!-- 하단 타임라인 -->
  <div class="ri-tl-section">
    <div class="ri-tl-scroll-wrap">
      <div class="ri-tl-fade-l"></div>
      <div class="ri-tl-fade-r"></div>
      <div id="riChipsArea" class="ri-tl-scroll"></div>
    </div>
  </div>
</div>

<!-- 힌트 배지 (토글 on 시 표시, 카드 밖) -->
<div id="riExtraHint" style="display:none;margin-bottom:14px;padding:11px 13px 11px 12px;background:linear-gradient(95deg,var(--acct-general-soft) 0%,var(--acct-general-bg) 50%,var(--acct-general-bg) 100%);border:1px solid var(--acct-general-g1);border-radius:10px;font-size:12px;color:var(--acct-general-text);font-weight:700;line-height:1.45;box-shadow:0 2px 8px rgba(79,70,229,.12);align-items:center;gap:9px">
  <span style="display:inline-flex;align-items:center;justify-content:center;width:24px;height:24px;background:linear-gradient(135deg,var(--c-gold-400),var(--c-gold-500));border-radius:50%;font-size:13px;flex-shrink:0;box-shadow:0 2px 4px rgba(245,158,11,.3)">💡</span>
  <span id="riExtraHintText" style="flex:1;letter-spacing:-.2px">매월 100만원 추가 시 5년 후 +X만/월 성장</span>
</div>

<!-- 차트 카드 (스탯 통합: 차트 → 스크럽 → 3분할 스탯) -->
<div style="background:#fff;border:1px solid var(--c-border);border-radius:14px;padding:14px 14px 10px;margin-bottom:14px">
  <div style="font-size:9.5px;font-weight:800;color:var(--c-label);letter-spacing:1.8px;text-transform:uppercase;margin-bottom:10px">월 배당 복리 성장 곡선</div>
  <div style="position:relative;width:100%;max-height:260px"><canvas id="reinvChartCvs" height="200" style="max-height:260px;display:block;pointer-events:none;touch-action:none"></canvas></div>
  <!-- 스크럽 정보 패널 (차트 터치 시 해당 연차 상세) -->
  <div id="riScrubInfo" style="display:grid;grid-template-columns:auto 1fr auto;gap:10px;align-items:center;padding:10px 12px;margin-top:10px;background:linear-gradient(95deg,#f8f6ee,var(--c-surface-2));border:1px solid var(--c-border-2);border-radius:10px;font-family:'Plus Jakarta Sans','Noto Sans KR',sans-serif">
    <div style="min-width:0">
      <div style="font-size:9px;color:var(--c-label);font-weight:800;letter-spacing:1.5px;text-transform:uppercase">Year</div>
      <div style="font-size:18px;color:var(--c-dark-1);font-weight:900;letter-spacing:-.6px;line-height:1" id="riScrubYr">5</div>
    </div>
    <div style="min-width:0;text-align:center;padding:0 8px;border-left:1px solid var(--c-border);border-right:1px solid var(--c-border)">
      <div style="font-size:9px;color:var(--c-label);font-weight:800;letter-spacing:1.5px;text-transform:uppercase">월 배당</div>
      <div style="font-size:17px;color:var(--asset-value);font-weight:900;letter-spacing:-.4px;line-height:1;font-family:'Plus Jakarta Sans',sans-serif;margin-top:2px" id="riScrubMon">0</div>
    </div>
    <div style="min-width:0;text-align:right">
      <div style="font-size:9px;color:var(--c-label);font-weight:800;letter-spacing:1.5px;text-transform:uppercase">성장</div>
      <div style="font-size:15px;color:var(--metric-yield);font-weight:900;letter-spacing:-.3px;line-height:1;margin-top:2px" id="riScrubGrow">×1.0</div>
    </div>
  </div>
  <!-- 3분할 스탯 (미니멀 인라인): 점선 구분선 + 얇은 세로선 -->
  <div class="ri-stats-inline" style="display:grid;grid-template-columns:1fr 1fr 1fr;padding:12px 6px 4px;margin-top:10px;border-top:1px dashed var(--c-border-2)">
    <div style="text-align:center;padding:0 4px">
      <div style="font-size:9px;color:var(--c-label);font-weight:800;letter-spacing:.5px;text-transform:uppercase;margin-bottom:4px">총 수령 배당</div>
      <div id="riCumDiv" style="font-size:14px;font-weight:900;color:var(--c-text);font-family:'Plus Jakarta Sans',sans-serif;letter-spacing:-.4px"></div>
    </div>
    <div style="text-align:center;padding:0 4px;border-left:1px solid var(--c-border-2);border-right:1px solid var(--c-border-2)">
      <div style="font-size:9px;color:var(--c-label);font-weight:800;letter-spacing:.5px;text-transform:uppercase;margin-bottom:4px">배당 성장률</div>
      <div id="riGrowth" style="font-size:14px;font-weight:900;color:var(--metric-growth);font-family:'Plus Jakarta Sans',sans-serif;letter-spacing:-.4px"></div>
    </div>
    <div style="text-align:center;padding:0 4px">
      <div style="font-size:9px;color:var(--c-label);font-weight:800;letter-spacing:.5px;text-transform:uppercase;margin-bottom:4px">연 복리수익</div>
      <div id="riCagrStat" style="font-size:14px;font-weight:900;color:var(--metric-yield);font-family:'Plus Jakarta Sans',sans-serif;letter-spacing:-.4px"></div>
    </div>
  </div>
</div>

<!-- 이정표 -->
<div id="riMilestones" style="margin-bottom:14px"></div>

<!-- 종목 리스트 -->
<div id="riHoldings"></div>

<div style="font-size:9.5px;color:var(--c-muted);margin-top:12px;padding-top:10px;border-top:1px solid var(--c-border-2);line-height:1.5;font-weight:500;letter-spacing:-.1px">※ 현재가 고정 기준 · 세후 배당 전액 즉시 재투자 · 주가 변동 미반영</div>`;

  // 차트 초기 생성 — 동기 실행 (innerHTML 직후 DOM 준비됨, setTimeout race 방지)
  (function(){
    const cvs=document.getElementById('reinvChartCvs');
    if(!cvs)return;
    if(window._reinvCI){window._reinvCI.destroy();window._reinvCI=null;}
    const ctx2=cvs.getContext('2d');
    const grad=ctx2.createLinearGradient(0,0,0,150);
    grad.addColorStop(0,'rgba(37,99,235,0.28)');
    grad.addColorStop(1,'rgba(37,99,235,0.01)');
    window._reinvCI=new Chart(cvs,{
      type:'line',
      data:{labels:[],datasets:[
        {
          // 메인 라인 (현재 설정)
          data:[],
          label:'현재',
          borderColor:'#2563eb',backgroundColor:grad,
          borderWidth:2.5,pointRadius:0,pointHoverRadius:6,
          pointBackgroundColor:'#fff',pointBorderColor:'#2563eb',pointBorderWidth:2,
          tension:0.4,fill:true,order:1
        },
        {
          // 비교 라인 (반대 설정) - 점선
          data:[],
          label:'비교',
          borderColor:'rgba(100,116,139,.6)',
          backgroundColor:'transparent',
          borderWidth:1.8,
          borderDash:[5,4],
          pointRadius:0,pointHoverRadius:5,
          pointBackgroundColor:'#fff',pointBorderColor:'#64748b',pointBorderWidth:1.5,
          tension:0.4,fill:false,order:2
        }
      ]},
      options:{
        responsive:true,
        maintainAspectRatio:true,
        aspectRatio:2.0,
        animation:{duration:250},
        events:[],
        plugins:{
          legend:{display:false},
          tooltip:{enabled:false}
        },
        scales:{
          x:{grid:{display:false},ticks:{font:{size:9},color:'#bbb',maxTicksLimit:8}},
          y:{grid:{color:'rgba(0,0,0,.04)'},ticks:{font:{size:9},color:'#bbb',callback:v=>v+'만'},beginAtZero:false}
        },
        interaction:{intersect:false,mode:'index'}
      }
    });
    // 차트 터치 스크럽 제거 (UI 버벅임 방지 · 반영만 충실)
    // _reinvBindChartScrub(cvs); ← 의도적으로 비활성화
    _reinvUpdateDisplay(YRS);
    // 타임라인 칩 초기 렌더 (1~40 칩 + 마일스톤 ★)
    if(typeof _reinvRerenderChips === 'function') _reinvRerenderChips();
    // 차트 아래 스크럽 정보 초기 업데이트
    if(typeof _reinvUpdateScrubInfo === 'function') _reinvUpdateScrubInfo(YRS);
    // 추가투자 스위치/입력 UI 초기 상태 동기화
    if(typeof _reinvSyncExtraUI === 'function') _reinvSyncExtraUI();
    const _inp = document.getElementById('riExtraInput');
    if(_inp) _inp.value = window._reinvExtraAmt;
    // 연도 조절 FAB observer 셋업
    if(typeof _setupReinvFabObserver === 'function') _setupReinvFabObserver();
    // 타임라인을 현재 YRS 위치로 초기 스크롤
    setTimeout(function(){
      const _chipsEl = document.getElementById('riChipsArea');
      if(_chipsEl){
        const _target = _chipsEl.querySelector('[data-riyr="'+YRS+'"]');
        if(_target){
          const _tRect = _target.getBoundingClientRect();
          const _cRect = _chipsEl.getBoundingClientRect();
          const _offset = (_tRect.left + _tRect.width/2) - (_cRect.left + _cRect.width/2);
          _chipsEl.scrollLeft += _offset;
        }
      }
    }, 30);
  })();
}

// 연도 변경: 즉시(숫자·칩) + 디바운스(무거운 DOM)
var _reinvDispTimer=null;
function _reinvSlide(y){
  y=Math.max(1,Math.min(40,+y));
  window._reinvYrs=y;

  // ① 즉시: 숫자·칩만 (레이아웃 변화 없음)
  var lbl=document.getElementById('riYrLbl');
  if(lbl) lbl.textContent=y;
  // FAB 년차 숫자 + 양옆 이웃 동기화
  _updateReinvYrFabDisplay(y);
  document.querySelectorAll('[data-riyr]').forEach(function(btn){
    var by=parseInt(btn.dataset.riyr);
    var bms=(window._reinvMilestones||[]).find(function(m){return m.yr===by;});
    var isAct=by===y;
    if(isAct){ btn.classList.add('active'); } else { btn.classList.remove('active'); }
  });

  // ② 디바운스 60ms: 나머지 DOM 업데이트
  clearTimeout(_reinvDispTimer);
  _reinvDispTimer=setTimeout(function(){
    // 이전 연도에서 남아있는 플래시/불꽃 효과 선제 제거 (DOM 누적 방지)
    var _fabElPre = document.getElementById('reinvYrFab');
    if(_fabElPre){
      _fabElPre.querySelectorAll('[data-ri-fx]').forEach(function(el){ el.remove(); });
    }
    var _heroPre = document.getElementById('riHero');
    if(_heroPre){
      _heroPre.querySelectorAll('[data-ri-fx]').forEach(function(el){ el.remove(); });
      _heroPre.classList.remove('_riFlashHero');
    }
    var ms=(window._reinvMilestones||[]).find(function(m){return m.yr===y;});
    var _banner = document.getElementById('riMsBanner');
    if(_banner){
      if(ms){
        _banner.textContent = '★ '+ms.label+' 달성';
        _banner.classList.remove('show'); void _banner.offsetWidth;
        _banner.classList.add('show');
      } else {
        _banner.classList.remove('show');
      }
    }
    if(ms){
      if(navigator.vibrate) navigator.vibrate([15,5,25]);
      if(lbl){
        lbl.style.animation='none';
        void lbl.offsetWidth;
        lbl.style.animation='riYrPop .4s ease';
        lbl.classList.add('flash');
        setTimeout(function(){lbl.classList.remove('flash');},400);
      }
      // FAB 숫자도 동일한 화이어 기믹
      var fabN=document.getElementById('reinvYrFabNum');
      if(fabN){
        fabN.style.animation='none';
        void fabN.offsetWidth;
        fabN.style.animation='riYrPop .4s ease';
        fabN.style.color='#f59e0b';
        setTimeout(function(){fabN.style.color='';},500);
      }
      // FAB 전체 배경 플래시
      var fabEl=document.getElementById('reinvYrFab');
      if(fabEl && fabEl.classList.contains('show')){
        var fabOv=document.createElement('div');
        fabOv.dataset.riFx='1';
        fabOv.style.cssText='position:absolute;inset:0;border-radius:inherit;pointer-events:none;z-index:1;'
          +'background:linear-gradient(135deg,rgba(251,146,60,.45),rgba(239,68,68,.35));'
          +'animation:riBgFlash .9s ease forwards';
        fabEl.appendChild(fabOv);
        setTimeout(function(){ if(fabOv.parentNode) fabOv.remove(); },950);
        // 작은 불꽃 이모지 1~2개 (FAB 위로 튀어오름)
        var fabEmojis=ms.m>=10?['💎','🔥']:ms.m>=5?['🔥','🔥']:ms.m>=3?['✨','🔥']:['🔥'];
        fabEmojis.forEach(function(em,ei){
          var fp=document.createElement('div');
          fp.dataset.riFx='1';
          fp.textContent=em;
          fp.style.cssText='position:absolute;font-size:'+(16+ei*2)+'px;left:'+(30+ei*30)
            +'%;bottom:12px;z-index:2;pointer-events:none;animation:riFireUp '+(0.7+ei*.1)
            +'s ease forwards;animation-delay:'+(ei*.06)+'s';
          fabEl.appendChild(fp);
          setTimeout(function(){ if(fp.parentNode) fp.remove(); }, 900+ei*100);
        });
      }
      var hero=document.getElementById('riHero');
      if(hero){
        var ov=document.createElement('div');
        ov.dataset.riFx='1';
        ov.style.cssText='position:absolute;inset:0;border-radius:18px;pointer-events:none;z-index:1;'
          +'background:linear-gradient(135deg,rgba(251,146,60,.55),rgba(239,68,68,.45));'
          +'animation:riBgFlash .9s ease forwards';
        hero.appendChild(ov);
        setTimeout(function(){ov.remove();},950);
        var emojis=ms.m>=10?['🔥','💎','🔥']:ms.m>=5?['🔥','🔥','🔥']:ms.m>=3?['🔥','✨','🔥']:['🚀','🔥','🚀'];
        emojis.forEach(function(e,i){
          var p=document.createElement('div');
          p.dataset.riFx='1';
          p.textContent=e;
          p.style.cssText='position:absolute;font-size:'+(18+i*3)+'px;left:'+(15+i*30)
            +'%;bottom:8px;z-index:2;pointer-events:none;animation:riFireUp '+(0.7+i*.1)
            +'s ease forwards;animation-delay:'+(i*.08)+'s';
          hero.appendChild(p);
          setTimeout(function(){p.remove();},900+i*100);
        });
        hero.classList.remove('_riFlashHero');
        void hero.offsetWidth;
        hero.classList.add('_riFlashHero');
        setTimeout(function(){hero.classList.remove('_riFlashHero');},950);
      }
    }
    _reinvUpdateDisplay(y);
    // 차트 아래 스크럽 정보 패널 업데이트
    if(typeof _reinvUpdateScrubInfo === 'function') _reinvUpdateScrubInfo(y);
    // 타임라인 스크롤도 해당 연도로 (FAB/프로그래매틱 호출 시)
    if(typeof _reinvTLScrollTo === 'function') _reinvTLScrollTo(y);
  },60);
}
// 매월 추가 투자 기본값
if(typeof window._reinvExtraOn === 'undefined') window._reinvExtraOn = false;
if(typeof window._reinvExtraAmt === 'undefined') window._reinvExtraAmt = 100;

// 추가 투자 토글 ON/OFF
function _reinvToggleExtra(){
  window._reinvExtraOn = !window._reinvExtraOn;
  _reinvSyncExtraUI();
  _reinvRebuildAndRefresh();
  // 스크롤 위치 유지 (사용자가 보던 화면 그대로)
}
// 추가 투자 금액 변경 (만원 단위) — 300ms 디바운스로 과도한 재계산 방지
var _reinvChangeExtraTimer=null;
function _reinvChangeExtra(val){
  const v = Math.max(0, Math.min(10000, Number(val)||0));
  window._reinvExtraAmt = v;
  if(!window._reinvExtraOn) return;
  clearTimeout(_reinvChangeExtraTimer);
  _reinvChangeExtraTimer = setTimeout(function(){
    _reinvRebuildAndRefresh();
  }, 300);
}
// 스위치/힌트 UI 상태 동기화 (재계산 없이 DOM만)
function _reinvSyncExtraUI(){
  const on = !!window._reinvExtraOn;
  const sw = document.getElementById('riExtraSw');
  const thumb = document.getElementById('riExtraSwThumb');
  const wrap = document.getElementById('riExtraInputWrap');
  const hint = document.getElementById('riExtraHint');
  if(sw) sw.style.background = on ? '#1c1917' : '#d4cfc0';
  if(thumb) thumb.style.left = on ? '20px' : '2px';
  if(wrap) wrap.style.opacity = on ? '1' : '.45';
  if(hint) hint.style.display = on ? 'flex' : 'none';
}
// snap 재계산 + 현재 YRS로 화면 갱신
function _reinvRebuildAndRefresh(){
  if(typeof _reinvCompute === 'function') _reinvCompute();
  const y = window._reinvYrs || 5;
  // 힌트 텍스트 업데이트 (추가투자 ON일 때 성장 차이 표시)
  const snap = window._reinvSnap||[];
  const hintT = document.getElementById('riExtraHintText');
  if(hintT && snap.length>y){
    const curMon = snap[Math.min(y,40)].monDiv;
    const _wasOn = window._reinvExtraOn;
    try {
      window._reinvExtraOn = false;
      _reinvCompute();
      const offSnap = window._reinvSnap||[];
      const offMon = offSnap[Math.min(y,40)]?.monDiv || 0;
      window._reinvExtraOn = _wasOn;
      _reinvCompute();
      const diff = Math.max(0, curMon - offMon);
      hintT.textContent = `매월 ${window._reinvExtraAmt}만원 추가 시 ${y}년 후 +${fmt(Math.round(diff))}/월 더 성장`;
    } finally {
      // 에러 발생 시에도 플래그 원복 + snap 재계산 보장
      if(window._reinvExtraOn !== _wasOn){
        window._reinvExtraOn = _wasOn;
        try{ _reinvCompute(); }catch(e){}
      }
    }
  }
  // 🎯 마일스톤 재계산 + 칩 영역 재렌더 (추가투자로 달성시점 바뀜)
  _reinvRecalcMilestones();
  _reinvRerenderChips();
  _reinvUpdateDisplay(y);
}

// 스텝 이동 (−10/−1/+1/+10)
function _reinvStep(delta){
  const curr=window._reinvYrs||5;
  let next=Math.max(1,Math.min(40,curr+delta));
  // 밀레스톤이 중간에 있으면 그 지점에서 한 번 걸림
  const ms=window._reinvMilestones||[];
  if(Math.abs(delta)>1){
    const crossed=ms.filter(m=>delta>0?m.yr>curr&&m.yr<next:m.yr<curr&&m.yr>next);
    if(crossed.length>0){
      next=delta>0?Math.min(...crossed.map(m=>m.yr)):Math.max(...crossed.map(m=>m.yr));
    }
  }
  _reinvSlide(next);
}

// ============= 차트 터치 스크럽 =============
// 캔버스 위에서 손가락/마우스 드래그 → 해당 연도로 slide
// 탭 좌우 스와이프와 body 세로 스크롤 모두 차단
function _reinvBindChartScrub(cvs){
  if(!cvs || cvs._scrubBound) return;
  cvs._scrubBound = true;
  cvs.style.touchAction = 'none';

  let scrubbing = false;
  let lastYr = -1;
  let rafId = null;
  let pendingYr = null;

  function xToYear(clientX){
    const rect = cvs.getBoundingClientRect();
    if(rect.width<=0) return 0;
    const ratio = Math.max(0, Math.min(1, (clientX - rect.left) / rect.width));
    // 차트 range 고정 (0~40년)이므로 절대 매핑 — 스크럽해도 스케일 변형 없음
    return Math.max(1, Math.min(40, Math.round(ratio * 40)));
  }
  function flushPending(){
    rafId = null;
    if(pendingYr!==null && pendingYr!==lastYr){
      lastYr = pendingYr;
      _reinvSlide(pendingYr);
    }
  }
  function onDown(e){
    scrubbing = true;
    try{ cvs.setPointerCapture(e.pointerId); }catch(ex){}
    const y = xToYear(e.clientX);
    if(y !== lastYr){
      lastYr = y;
      _reinvSlide(y);
    }
    e.preventDefault();
    e.stopPropagation();
  }
  function onMove(e){
    if(!scrubbing) return;
    e.preventDefault();
    e.stopPropagation();
    pendingYr = xToYear(e.clientX);
    if(!rafId) rafId = requestAnimationFrame(flushPending);
  }
  function onUp(e){
    scrubbing = false;
    lastYr = -1;
    pendingYr = null;
    if(rafId){cancelAnimationFrame(rafId); rafId=null;}
    try{ cvs.releasePointerCapture(e.pointerId); }catch(ex){}
  }
  cvs.addEventListener('pointerdown', onDown);
  cvs.addEventListener('pointermove', onMove);
  cvs.addEventListener('pointerup', onUp);
  cvs.addEventListener('pointercancel', onUp);
  cvs.addEventListener('pointerleave', function(e){ if(scrubbing) onUp(e); });
}

// ============= 마일스톤/칩 재계산 (매월 추가투자 토글 시 반영) =============
function _reinvRecalcMilestones(){
  const snap = window._reinvSnap||[];
  if(!snap.length){ window._reinvMilestones=[]; return; }
  const defs=[{m:2,emoji:'🚀',label:'2배'},{m:3,emoji:'✨',label:'3배'},{m:5,emoji:'🔥',label:'5배'},{m:10,emoji:'💎',label:'10배'}];
  const base = snap[0].monDiv;
  const ms = defs.map(d=>{
    const f = snap.findIndex(s=>s.monDiv >= base*d.m);
    return (f>0 && f<=40) ? {...d, yr:f} : null;
  }).filter(Boolean);
  window._reinvMilestones = ms;
}
// 차트 아래 스크럽 정보 패널 업데이트
function _reinvUpdateScrubInfo(y){
  var yrEl = document.getElementById('riScrubYr');
  var monEl = document.getElementById('riScrubMon');
  var growEl = document.getElementById('riScrubGrow');
  if(!yrEl || !monEl || !growEl) return;
  var snap = window._reinvSnap || [];
  if(!snap.length) return;
  var idx = Math.max(0, Math.min(40, y|0));
  var cur = snap[idx];
  var base = snap[0];
  if(!cur || !base) return;
  yrEl.textContent = idx + '년';
  monEl.textContent = fmt(Math.round(cur.monDiv));
  var growth = base.monDiv > 0 ? (cur.monDiv / base.monDiv) : 1;
  growEl.textContent = '×' + growth.toFixed(1);
  // 마일스톤이면 골드, 아니면 민트
  var ms = (window._reinvMilestones || []).find(function(m){return m.yr===idx;});
  if(ms){
    growEl.style.color = '#d97706';
  } else {
    growEl.style.color = '#059669';
  }
}

// 타임라인 재렌더
function _reinvRerenderChips(){
  const chipsEl = document.getElementById('riChipsArea');
  if(!chipsEl) return;
  const ms = window._reinvMilestones||[];
  const msMap = {}; ms.forEach(m=>{msMap[m.yr]=m;});
  const YRS = window._reinvYrs || 5;
  let html = '<div class="ri-pad" style="width:calc(50% - 23px)"></div>';
  for(let y=1; y<=40; y++){
    const m = msMap[y];
    const clsArr = ['ch'];
    if(m) clsArr.push('ms');
    if(y===YRS) clsArr.push('active');
    html += '<button data-riyr="'+y+'" class="'+clsArr.join(' ')+'" onclick="_reinvTLClick('+y+')" title="'+(m?m.label+' 달성':'')+'">'+y+'</button>';
  }
  html += '<div class="ri-pad" style="width:calc(50% - 23px)"></div>';
  chipsEl.innerHTML = html;
  // innerHTML 교체로 scrollLeft가 0이 됨 → 현재 YRS 위치로 즉시 복귀 (레이아웃 완료 후)
  requestAnimationFrame(function(){
    const _t = chipsEl.querySelector('[data-riyr="'+YRS+'"]');
    if(_t){
      const _tr = _t.getBoundingClientRect();
      const _cr = chipsEl.getBoundingClientRect();
      const _off = (_tr.left + _tr.width/2) - (_cr.left + _cr.width/2);
      chipsEl.scrollLeft += _off;
    }
  });
  if(!chipsEl._tlBound){
    chipsEl._tlBound = true;
    let scrollT = null;
    chipsEl.addEventListener('scroll', function(){
      clearTimeout(scrollT);
      scrollT = setTimeout(_reinvTLDetectCenter, 45);
    });
  }
}
function _reinvTLClick(y){
  _reinvTLScrollTo(y);
  _reinvSlide(y);
}
function _reinvTLDetectCenter(){
  const chipsEl = document.getElementById('riChipsArea');
  if(!chipsEl) return;
  const rect = chipsEl.getBoundingClientRect();
  const cx = rect.left + rect.width/2;
  const chs = chipsEl.querySelectorAll('.ch');
  let best = null, bestDist = Infinity;
  chs.forEach(function(c){
    const cr = c.getBoundingClientRect();
    const ccx = cr.left + cr.width/2;
    const d = Math.abs(ccx - cx);
    if(d < bestDist){ bestDist = d; best = c; }
  });
  if(best){
    const y = +best.dataset.riyr;
    if(y && y !== window._reinvYrs){ _reinvSlide(y); }
  }
}
function _reinvTLScrollTo(y){
  const chipsEl = document.getElementById('riChipsArea');
  if(!chipsEl) return;
  const target = chipsEl.querySelector('[data-riyr="'+y+'"]');
  if(!target) return;
  // scrollIntoView는 수직 스크롤까지 건드리므로 수평만 직접 조정
  const tRect = target.getBoundingClientRect();
  const cRect = chipsEl.getBoundingClientRect();
  const offset = (tRect.left + tRect.width/2) - (cRect.left + cRect.width/2);
  const targetLeft = chipsEl.scrollLeft + offset;
  chipsEl.scrollTo({left: targetLeft, behavior: 'smooth'});
}

// ============= 연도 조절 FAB (스크롤 시 페이드인) =============
function _mountReinvYrFab(){
  let fab = document.getElementById('reinvYrFab');
  if(!fab){
    fab = document.createElement('div');
    fab.id = 'reinvYrFab';
    fab.className = 'reinv-yr-fab';
    var _yrItems = '';
    for(var _i = 1; _i <= 40; _i++){
      _yrItems += '<div class="y" data-yr="'+_i+'">'+_i+'<span class="unit-mini">년</span></div>';
    }
    fab.innerHTML =
      '<div class="reinv-yr-fab-center" id="reinvYrFabCenter">'
        +'<div class="y-spacer"></div>'
        +_yrItems
        +'<div class="y-spacer"></div>'
      +'</div>';
    // 호환성: 기존 코드가 참조하는 reinvYrFabNum ID 유지 (hidden span)
    fab.insertAdjacentHTML('beforeend','<span id="reinvYrFabNum" style="display:none"></span>');
    document.body.appendChild(fab);
    // iOS 스타일 픽커 바인딩
    _initReinvYrPicker(fab.querySelector('.reinv-yr-fab-center'));
  }
  return fab;
}
// ─── FAB 라이브 드래그: 손가락 따라 연도 실시간 변경 ───
function _bindReinvFabDrag(fab){
  if(!fab || fab._dragBound) return;
  fab._dragBound = true;

  var center = fab.querySelector('.reinv-yr-fab-center');
  if(!center) return;

  // 사이드 숫자 탭 → 해당 연도로 점프 (드래그 아닐 때만)
  center.addEventListener('click', function(e){
    if(state.moved) return;
    var target = e.target.closest('[data-yr-offset]');
    if(!target) return;
    var offset = parseInt(target.dataset.yrOffset);
    if(!offset) return;
    if(typeof _reinvStep === 'function') _reinvStep(offset);
  });

  var state = {
    active:false, sx:0, sy:0, startYr:0, lastX:0, lastT:0,
    velocity:0, decided:false, horizontal:false, moved:false
  };
  // 1년당 이동 거리(px): 작을수록 민감. 16px가 iOS 느낌
  var PX_PER_YEAR = 16;

  // 터치/마우스 통합 이벤트 좌표 추출
  function getPoint(e){
    if(e.touches && e.touches[0]) return {x:e.touches[0].clientX, y:e.touches[0].clientY};
    if(e.changedTouches && e.changedTouches[0]) return {x:e.changedTouches[0].clientX, y:e.changedTouches[0].clientY};
    return {x:e.clientX, y:e.clientY};
  }

  function onStart(e){
    // +/- 버튼에서 시작하면 무시 (탭 동작 유지)
    if(e.target && e.target.closest('button')) return;
    var p = getPoint(e);
    state.active = true;
    state.sx = state.lastX = p.x;
    state.sy = p.y;
    state.startYr = Number(window._reinvYrs) || 5;
    state.lastT = Date.now();
    state.velocity = 0;
    state.decided = false;
    state.horizontal = false;
    state.moved = false;
    // stopPropagation 안 함: 세로 스크롤은 허용
  }

  function onMove(e){
    if(!state.active) return;
    var p = getPoint(e);
    var dx = p.x - state.sx;
    var dy = p.y - state.sy;

    if(!state.decided){
      if(Math.abs(dx) < 6 && Math.abs(dy) < 6) return;
      state.decided = true;
      state.horizontal = Math.abs(dx) > Math.abs(dy);
      if(state.horizontal){
        fab.classList.add('dragging');
      } else {
        // 세로 움직임 → 드래그 취소 (스크롤 허용)
        state.active = false;
        return;
      }
    }
    if(!state.horizontal) return;

    state.moved = true;

    // 속도 계산
    var now = Date.now();
    var dt = now - state.lastT;
    if(dt > 0){
      state.velocity = (p.x - state.lastX) / dt; // px/ms
    }
    state.lastX = p.x;
    state.lastT = now;

    // 가로 스와이프: 페이지 스크롤 방지
    if(e.cancelable && e.preventDefault) e.preventDefault();

    // 1년당 16px. 드래그 거리만큼 연도 변경
    var yearDelta = Math.round(dx / PX_PER_YEAR);
    var nextYr = Math.max(1, Math.min(40, state.startYr + yearDelta));

    // 이전값과 다르면 즉시 업데이트 (햅틱 포함)
    if(nextYr !== (window._reinvYrs||5)){
      // 연도 변경 시 가벼운 햅틱
      if(navigator.vibrate) navigator.vibrate(5);
      _reinvSlide(nextYr);
    }
  }

  function onEnd(e){
    if(!state.active){ fab.classList.remove('dragging'); return; }
    state.active = false;

    if(!state.horizontal || !state.moved){
      fab.classList.remove('dragging');
      return;
    }

    // Flick 관성: 속도가 크면 몇 년 더 밀기
    var v = state.velocity; // px/ms
    var absV = Math.abs(v);
    if(absV > 0.5){
      // 빠른 flick → 관성 추가 (속도의 일부를 연도로 변환)
      var momentum = Math.round((v / PX_PER_YEAR) * 120); // 120ms 관성
      var curYr = Number(window._reinvYrs) || 5;
      var target = Math.max(1, Math.min(40, curYr + momentum));
      if(target !== curYr){
        if(navigator.vibrate) navigator.vibrate([8, 6, 10]);
        _reinvSlide(target);
      }
    }
    fab.classList.remove('dragging');
  }

  // Touch
  center.addEventListener('touchstart', onStart, {passive:true});
  center.addEventListener('touchmove', onMove, {passive:false});
  center.addEventListener('touchend', onEnd, {passive:true});
  center.addEventListener('touchcancel', function(){
    state.active = false;
    fab.classList.remove('dragging');
  }, {passive:true});

  // Mouse (데스크톱 테스트용)
  center.addEventListener('mousedown', function(e){
    onStart(e);
    var moveHandler = function(ev){ onMove(ev); };
    var upHandler = function(ev){
      onEnd(ev);
      window.removeEventListener('mousemove', moveHandler);
      window.removeEventListener('mouseup', upHandler);
    };
    window.addEventListener('mousemove', moveHandler);
    window.addEventListener('mouseup', upHandler);
  });
}

// FAB 픽커에서 현재 연도로 스크롤 (외부 호출 시)
function _updateReinvYrFabDisplay(y){
  y = parseInt(y) || (window._reinvYrs || 5);
  // hidden span 업데이트 (밀레스톤 코드가 참조)
  var num = document.getElementById('reinvYrFabNum');
  if(num) num.textContent = y;
  var track = document.getElementById('reinvYrFabCenter');
  if(!track || !track._pickerBound) return;
  // 이미 active인 연도면 스크롤 불필요 (무한 루프 방지)
  var active = track.querySelector('.y.active');
  var curActiveYr = active ? parseInt(active.dataset.yr) : 0;
  if(curActiveYr === y) return;
  if(typeof track._scrollToYr === 'function') track._scrollToYr(y);
}

// iOS 스타일 휠 픽커: CSS scroll-snap + 스크롤 리스너로 중앙 연도 감지
function _initReinvYrPicker(track){
  if(!track || track._pickerBound) return;
  track._pickerBound = true;

  var activeYr = 0;
  var isProgrammatic = false;
  var progTimer = null;
  var idleTimer = null;
  var settleTimer = null;
  var fab = track.closest('.reinv-yr-fab');

  function findCenterYr(){
    var rect = track.getBoundingClientRect();
    var centerX = rect.left + rect.width/2;
    var items = track.querySelectorAll('.y[data-yr]');
    var closestYr = 0;
    var closestDist = Infinity;
    items.forEach(function(el){
      var r = el.getBoundingClientRect();
      var itemCenter = r.left + r.width/2;
      var dist = Math.abs(itemCenter - centerX);
      if(dist < closestDist){
        closestDist = dist;
        closestYr = parseInt(el.dataset.yr);
      }
    });
    return closestYr;
  }

  function setActive(yr){
    if(!yr || yr === activeYr) return;
    activeYr = yr;
    track.querySelectorAll('.y[data-yr]').forEach(function(el){
      var on = parseInt(el.dataset.yr) === yr;
      if(on) el.classList.add('active'); else el.classList.remove('active');
    });
  }

  function onScroll(){
    // dragging 클래스 (스크롤 중이면 활성)
    if(fab) fab.classList.add('dragging');
    clearTimeout(idleTimer);
    idleTimer = setTimeout(function(){
      if(fab) fab.classList.remove('dragging');
    }, 180);

    var yr = findCenterYr();
    if(yr && yr !== activeYr){
      setActive(yr);
      // 라이브 업데이트: 실시간으로 _reinvSlide 호출
      if(!isProgrammatic && yr !== (window._reinvYrs||0)){
        if(navigator.vibrate) navigator.vibrate(5);
        if(typeof _reinvSlide === 'function') _reinvSlide(yr);
      }
    }

    // 스크롤 정착 후 마지막 정리
    clearTimeout(settleTimer);
    settleTimer = setTimeout(function(){
      if(isProgrammatic) return;
      var finalYr = findCenterYr();
      if(finalYr && finalYr !== (window._reinvYrs||0)){
        if(typeof _reinvSlide === 'function') _reinvSlide(finalYr);
      }
    }, 120);
  }

  track.addEventListener('scroll', onScroll, {passive:true});

  // 숫자 직접 탭 → 해당 연도로 스무스 스크롤 + 즉시 데이터 업데이트
  track.addEventListener('click', function(e){
    var target = e.target.closest('.y[data-yr]');
    if(!target) return;
    var yr = parseInt(target.dataset.yr);
    // PC 호환성: smooth scroll 완료 이벤트 미발생 대비, _reinvSlide 즉시 호출
    if(yr && yr !== (window._reinvYrs||0) && typeof _reinvSlide === 'function'){
      _reinvSlide(yr);
    }
    scrollToYr(yr, true);
  });

  function scrollToYr(yr, smooth){
    if(!yr) return;
    var target = track.querySelector('.y[data-yr="'+yr+'"]');
    if(!target) return;
    isProgrammatic = true;
    clearTimeout(progTimer);
    progTimer = setTimeout(function(){ isProgrammatic = false; }, smooth ? 500 : 80);
    // 중앙 정렬 스크롤
    var trackRect = track.getBoundingClientRect();
    var targetRect = target.getBoundingClientRect();
    var offset = (targetRect.left - trackRect.left) - (trackRect.width/2 - targetRect.width/2);
    var targetLeft = track.scrollLeft + offset;
    try{
      track.scrollTo({left: targetLeft, behavior: smooth ? 'smooth' : 'auto'});
    }catch(e){
      track.scrollLeft = targetLeft;
    }
    setActive(yr);
  }

  track._scrollToYr = scrollToYr;

  // 초기 위치 설정 — requestAnimationFrame으로 레이아웃 완료 후
  requestAnimationFrame(function(){
    var cur = window._reinvYrs || 5;
    scrollToYr(cur, false);
  });
}

function _showReinvYrFab(){
  if(window._reinvFabLocked) return;
  if(typeof TAB!=='undefined' && TAB!=='reinv') return;
  // 페이지 최상단 근처에서는 강제 숨김 (고무줄 스크롤 등 오탐 방지)
  if((window.scrollY||document.documentElement.scrollTop||0) < 80) return;
  // 칩 영역이 뷰포트 내 일부라도 보이면/아래로 밀려난 경우 숨김
  const chips = document.getElementById('riChipsArea');
  if(chips){
    const r = chips.getBoundingClientRect();
    if(r.bottom >= 0) return;
  }
  const f = _mountReinvYrFab();
  _updateReinvYrFabDisplay(window._reinvYrs || 5);
  f.classList.add('show');
}
function _hideReinvYrFab(){ const f=document.getElementById('reinvYrFab'); if(f) f.classList.remove('show'); }
// 스크롤 기반 노출 제어: 상단 컨트롤 영역이 뷰포트 위로 벗어날 때만 FAB 표시
function _setupReinvFabObserver(){
  const chips = document.getElementById('riChipsArea');
  if(!chips) return;
  if(window._reinvFabIO) window._reinvFabIO.disconnect();
  window._reinvFabIO = new IntersectionObserver(function(entries){
    entries.forEach(function(en){
      // 현재 탭이 reinv일 때만 토글
      if(typeof TAB!=='undefined' && TAB!=='reinv'){ _hideReinvYrFab(); return; }
      // 칩이 보이면 숨김
      if(en.isIntersecting){ _hideReinvYrFab(); return; }
      // 칩이 안 보이는 경우: 위로 벗어난 건지(아래로 스크롤) 아래로 벗어난 건지(위로 스크롤) 확인
      const r = en.boundingClientRect;
      if(r.bottom < 0){
        // 칩이 뷰포트 위쪽 밖 → 아래로 스크롤한 상태 → FAB 등장
        _showReinvYrFab();
      } else {
        // 칩이 뷰포트 아래쪽 밖 (위로 당긴 고무줄/최상단 위 드래그) → 숨김 유지
        _hideReinvYrFab();
      }
    });
  }, {threshold:0, rootMargin:'0px 0px -10px 0px'});
  window._reinvFabIO.observe(chips);
}

// 숫자+차트만 업데이트 (DOM 재생성 없음)
function _reinvUpdateDisplay(YRS){
  const snap=window._reinvSnap||[];
  const H=window._reinvH||[];
  if(!snap.length) return;  // 차트가 없어도 히어로/이정표는 갱신되게

  const fin=snap[Math.min(YRS,40)];
  const s0=snap[0];
  const mult=fin.monDiv/s0.monDiv;
  const cagr=(Math.pow(mult,1/YRS)-1)*100;

  // 히어로 업데이트
  const el=id=>document.getElementById(id);
  if(el('riHeroLbl'))el('riHeroLbl').textContent=YRS+'년 후 월 배당';
  if(el('riHeroAmt'))el('riHeroAmt').textContent=fmt(Math.round(fin.monDiv));
  if(el('riMult'))el('riMult').textContent='×'+mult.toFixed(1)+' 성장';
  if(el('riCagr'))el('riCagr').textContent='연 복리 '+cagr.toFixed(1)+'%';
  if(el('riHeroSub'))el('riHeroSub').textContent=fmt(Math.round(s0.monDiv))+'/월 → '+fmt(Math.round(fin.monDiv))+'/월';
  // 밀레스톤 도달 뱃지
  const _msCurrent=(window._reinvMilestones||[]).filter(m=>m.yr<=YRS);
  const _msLatest=_msCurrent[_msCurrent.length-1];
  const _msBadge=el('riMsBadge');
  if(_msBadge){
    if(_msLatest){
      _msBadge.style.display='block';
      _msBadge.textContent=_msLatest.emoji+' '+_msLatest.label+' 달성!';
      _msBadge.style.background=_msLatest.m>=10?'rgba(251,191,36,.22)':_msLatest.m>=5?'rgba(251,191,36,.18)':_msLatest.m>=3?'rgba(165,180,252,.22)':'rgba(147,197,253,.18)';
      _msBadge.style.color=_msLatest.m>=10?'#fde68a':_msLatest.m>=5?'#fbbf24':_msLatest.m>=3?'#c7d2fe':'#93c5fd';
      _msBadge.style.border='1px solid '+(_msLatest.m>=10?'rgba(251,191,36,.4)':_msLatest.m>=5?'rgba(251,191,36,.3)':_msLatest.m>=3?'rgba(165,180,252,.4)':'rgba(147,197,253,.3)');
    } else {
      _msBadge.style.display='none';
    }
  }
  if(el('riCumDiv'))el('riCumDiv').textContent=fmt(Math.round(fin.cumDiv));
  if(el('riGrowth'))el('riGrowth').textContent='+'+Math.round((mult-1)*100)+'%';
  if(el('riCagrStat'))el('riCagrStat').textContent=cagr.toFixed(1)+'%';

  // 추가투자 힌트 텍스트: 연도 변화에 따라 동기화 (ON일 때만)
  if(window._reinvExtraOn){
    const hintT=el('riExtraHintText');
    const snapCmp=window._reinvSnapCmp||[];
    if(hintT && snapCmp.length>YRS){
      // snapCmp는 추가투자 OFF 기준(비교 라인) - 차트 업데이트에서 이미 계산됨
      const offMon=snapCmp[Math.min(YRS,40)]?.monDiv||0;
      const diff=Math.max(0, fin.monDiv - offMon);
      hintT.textContent=`매월 ${window._reinvExtraAmt||0}만원 추가 시 ${YRS}년 후 +${fmt(Math.round(diff))}/월 더 성장`;
    }
  }

  // 차트: 항상 0~40년 고정 range + 현재 YRS 지점 하이라이트 (차트 인스턴스 있을 때만)
  if(window._reinvCI){
    const snapAll=snap; // 41개 (0~40년)
    const snapCmpAll=window._reinvSnapCmp||[];
    const CI=window._reinvCI;
    CI.data.labels=snapAll.map((d,i)=>String(i));
    CI.data.datasets[0].data=snapAll.map(d=>+(d.monDiv/10000).toFixed(1));
    CI.data.datasets[1].data=snapCmpAll.map(d=>+(d.monDiv/10000).toFixed(1));
    // 현재 YRS 지점만 큰 포인트 + 골드색 (나머지는 숨김)
    CI.data.datasets[0].pointRadius=snapAll.map((_,i)=>i===YRS?6:0);
    CI.data.datasets[0].pointHoverRadius=snapAll.map((_,i)=>i===YRS?8:0);
    CI.data.datasets[0].pointBackgroundColor=snapAll.map((_,i)=>i===YRS?'#fbbf24':'#fff');
    CI.data.datasets[0].pointBorderColor=snapAll.map((_,i)=>i===YRS?'#f59e0b':'#2563eb');
    CI.data.datasets[0].pointBorderWidth=snapAll.map((_,i)=>i===YRS?2.5:0);
    // x축 라벨: 현재/5/10/20/30/40년만 표시
    CI.options.scales.x.ticks.callback=function(val,idx){
      if(idx===0) return '현재';
      if([5,10,15,20,25,30,35,40].includes(idx)) return idx+'년';
      return '';
    };
    // 비교 라인 라벨
    const _isOn=!!window._reinvExtraOn;
    CI.data.datasets[0].label = _isOn ? '추가투자 ON' : '배당만 재투자';
    CI.data.datasets[1].label = _isOn ? '배당만 재투자 (비교)' : '+'+(window._reinvExtraAmt||0)+'만 추가 시';
    CI.update('none');
  }

  // 이정표
  const mlIcons=['⭐','🎯','💎','🏆'];
  const mlTargets=[30,50,100,200,300,500,1000,2000,3000].map(v=>v*10000);
  const mls=mlTargets.map(t=>{
    const f=snap.find(d=>d.monDiv>=t&&d.yr<=YRS);
    return f?{t,yr:f.yr}:null;
  }).filter(Boolean).slice(0,4);
  const mlBox=el('riMilestones');
  if(mlBox)mlBox.innerHTML=mls.length?`
<div style="background:#fff;border:1px solid var(--c-border);border-radius:14px;padding:12px 14px 8px">
  <div style="font-size:9.5px;font-weight:800;color:var(--c-label);letter-spacing:1.8px;text-transform:uppercase;margin-bottom:10px">달성 이정표</div>
  <div style="display:flex;flex-direction:column;gap:5px">
${mls.map((m,i)=>`<div style="display:flex;align-items:center;justify-content:space-between;padding:9px 11px;background:linear-gradient(95deg,var(--c-green-50),var(--c-green-100));border:1px solid #a7f3d0;border-radius:10px">
  <div style="display:flex;align-items:center;gap:9px">
    <span style="font-size:15px">${mlIcons[i]||'★'}</span>
    <div style="font-size:12px;font-weight:800;color:#065f46;letter-spacing:-.2px">월 ${fmt(m.t)} 달성</div>
  </div>
  <div style="font-size:11.5px;font-weight:800;color:#047857;font-family:'Plus Jakarta Sans',sans-serif;letter-spacing:-.2px">${m.yr===0?'이미 달성!':m.yr+'년째'}</div>
</div>`).join('')}
  </div>
</div>`:'';

  // 종목별
  const hBox=el('riHoldings');
  if(hBox&&H.length){
    // YRS년치 개별 계산 (H는 이미 50년 끝 상태라 재계산 필요)
    const ss2=window._simSS||[];
    const map2={};
    ss2.forEach(x=>{if(!map2[x.id])map2[x.id]={...x};});
    const H0=Object.values(map2).filter(x=>x.qty>0&&(x.cur||x.avg)>0);
    const tv0=H0.reduce((s,h)=>s+(h.cur||h.avg)*h.qty,0);
    H0.forEach(h=>{h.frac2=h.qty;h.pc2=h.cur||h.avg;h.wt2=h.pc2*h.qty/tv0;});
    let c2=0;
    const _extraOn2 = !!window._reinvExtraOn;
    const _extraAmt2 = (Math.max(0, Number(window._reinvExtraAmt)||0)) * 10000;
    const _extraPerMon2 = _extraOn2 ? _extraAmt2 : 0;
    for(let m=0;m<YRS*12;m++){
      const mi=m%12;
      H0.forEach(h=>{
        const ann=h.frac2*h.pc2*(h.dy/100)*(1-h.tx);
        const pp=ann/dvN(h.df);let r=0;
        if(h.df==='월배당')r=ann/12;
        else if(h.df==='분기배당'&&[2,5,8,11].includes(mi))r=pp;
        else if(h.df==='반기배당'&&[5,11].includes(mi))r=pp;
        else if(h.df==='연배당'&&mi===11)r=pp;
        else if(!['월배당','분기배당','반기배당','연배당'].includes(h.df))r=ann/12;
        c2+=r;
      });
      c2 += _extraPerMon2; // 매월 추가 투자금 반영
      if(c2>0){H0.forEach(h=>{h.frac2+=c2*h.wt2/h.pc2;});c2=0;}
    }
    hBox.innerHTML=`
<div style="background:#fff;border:1px solid var(--c-border);border-radius:14px;padding:12px 14px 4px">
  <div style="font-size:9.5px;font-weight:800;color:var(--c-label);letter-spacing:1.8px;text-transform:uppercase;margin-bottom:4px">종목별 ${YRS}년 후 현황</div>
  ${H0.map((h,i)=>`<div style="display:flex;align-items:center;gap:11px;padding:11px 0;${i?'border-top:1px solid var(--c-border-2)':''}">
    <div style="width:38px;height:38px;border-radius:50%;background:${COLORS[(h.idx||i)%COLORS.length]};display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:800;color:#fff;flex-shrink:0;letter-spacing:-.3px">${(h.n||'').replace(/[^A-Za-z가-힣0-9]/g,'').slice(0,2)}</div>
    <div style="flex:1;min-width:0">
      <div style="font-size:12.5px;font-weight:700;color:var(--c-text);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;letter-spacing:-.2px">${h.n}</div>
      <div style="font-size:10.5px;color:var(--c-label);margin-top:3px;font-weight:500">${Math.round(h.qty).toLocaleString()}주 → <span style="color:var(--c-blue-700);font-weight:800;font-family:'Plus Jakarta Sans',sans-serif">${Math.round(h.frac2).toLocaleString()}주</span> <span style="color:var(--c-green-700);font-weight:700">(+${Math.round(h.frac2-h.qty).toLocaleString()}주)</span></div>
    </div>
    <div style="text-align:right;flex-shrink:0">
      <div style="font-size:13px;font-weight:900;color:var(--c-green-700);font-family:'Plus Jakarta Sans',sans-serif;letter-spacing:-.4px">${fmt(Math.round(h.frac2*h.pc2*(h.dy/100)*(1-h.tx)/12))}<span style="font-size:10px;color:var(--c-label);font-weight:600;margin-left:2px">만/월</span></div>
    </div>
  </div>`).join('')}
</div>`;
  }
}

/* ===== PIE / 비중 차트 ===== */
var _chartMode='val';
var _chartH=[], _chartTv=0;

function setChartMode(mode){
  _chartMode=mode;
  ['val','div','sector'].forEach(function(m){
    var btn=document.getElementById('cm'+m.charAt(0).toUpperCase()+m.slice(1));
    if(!btn)return;
    if(m===mode){btn.style.background='#2563eb';btn.style.color='#fff';btn.style.boxShadow='0 1px 4px rgba(37,99,235,.3)';}
    else{btn.style.background='transparent';btn.style.color='#64748b';btn.style.boxShadow='none';}
  });
  renderPie(_chartH,_chartTv);
}

// ── 트리맵 레이아웃 (재귀 이진 분할) ───────────────────────────────────────
function _tmLayout(items, x, y, w, h, horiz){
  if(!items.length) return [];
  if(items.length===1) return [{...items[0],x,y,w,h}];
  var total=items.reduce(function(s,i){return s+i.value;},0);
  var cum=0, split=0;
  for(var k=0;k<items.length-1;k++){
    cum+=items[k].value; split=k+1;
    if(cum/total>=0.5) break;
  }
  var g1=items.slice(0,split), g2=items.slice(split);
  var r1=g1.reduce(function(s,i){return s+i.value;},0)/total;
  if(horiz){
    return _tmLayout(g1,x,y,w*r1,h,!horiz).concat(_tmLayout(g2,x+w*r1,y,w*(1-r1),h,!horiz));
  } else {
    return _tmLayout(g1,x,y,w,h*r1,!horiz).concat(_tmLayout(g2,x,y+h*r1,w,h*(1-r1),!horiz));
  }
}

function _renderTreemap(labels, values, total, colors){
  var wrap=document.getElementById('treemapWrap');
  if(!wrap) return;
  var items=labels.map(function(l,i){return {label:l,value:values[i],idx:i};})
    .filter(function(x){return x.value>0;})
    .sort(function(a,b){return b.value-a.value;});
  if(!items.length){wrap.innerHTML='';return;}
  var GAP=2;
  var cells=_tmLayout(items,0,0,100,100,true);
  wrap.innerHTML=cells.map(function(c){
    var pct=total>0?(c.value/total*100):0;
    var color=colors[c.idx%colors.length];
    var isBig=pct>=12, isMed=pct>=5;
    var lbl=c.label.replace(/…$/,'');
    if(lbl.length>10) lbl=lbl.slice(0,10)+'…';
    var fmtV=fmt(Math.round(c.value));
    var inner;
    if(isBig){
      inner='<div style="font-size:11px;font-weight:800;color:rgba(255,255,255,.9);text-align:center;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;width:100%;padding:0 4px">'+lbl+'</div>'
           +'<div style="font-size:20px;font-weight:900;color:#fff;letter-spacing:-0.5px">'+pct.toFixed(1)+'%</div>'
           +'<div style="font-size:10px;color:rgba(255,255,255,.65);margin-top:1px">'+fmtV+'</div>';
    } else if(isMed){
      inner='<div style="font-size:10px;font-weight:700;color:rgba(255,255,255,.85);overflow:hidden;text-overflow:ellipsis;white-space:nowrap;width:100%;text-align:center;padding:0 3px">'+lbl+'</div>'
           +'<div style="font-size:14px;font-weight:900;color:#fff">'+pct.toFixed(1)+'%</div>';
    } else {
      inner='<div style="font-size:11px;font-weight:800;color:#fff">'+pct.toFixed(0)+'%</div>';
    }
    return '<div style="position:absolute;'
      +'left:calc('+c.x.toFixed(2)+'% + '+GAP+'px);'
      +'top:calc('+c.y.toFixed(2)+'% + '+GAP+'px);'
      +'width:calc('+c.w.toFixed(2)+'% - '+GAP*2+'px);'
      +'height:calc('+c.h.toFixed(2)+'% - '+GAP*2+'px);'
      +'background:'+color+';'
      +'border-radius:10px;'
      +'display:flex;flex-direction:column;align-items:center;justify-content:center;'
      +'overflow:hidden;box-sizing:border-box;cursor:pointer;'
      +'box-shadow:inset 0 0 0 1px rgba(255,255,255,.15),'
      +'0 1px 4px rgba(0,0,0,.12);'
      +'background-image:linear-gradient(160deg,rgba(255,255,255,.12) 0%,transparent 60%);'
      +'">'
      +inner
      +'</div>';
  }).join('');
}

function renderPie(H,tV){
  _chartH=H; _chartTv=tV;
  var empty=document.getElementById('chartEmpty');
  var mag=document.getElementById('chartMag');
  var insec=document.getElementById('insightsSection');

  if(!H.length){
    if(empty)empty.style.display='block';
    if(mag)mag.style.display='none';
    if(insec)insec.style.display='none';
    return;
  }
  if(empty)empty.style.display='none';
  if(mag)mag.style.display='block';
  if(insec)insec.style.display='block';

  _renderMagRanking(H, tV);

  // ===== 인사이트 섹션 렌더 =====
  try{
    _renderAccountMix(H, tV);
    _renderAIInsights(H, tV);
  }catch(e){ console.error('insight render error', e); }
}

// ============================================================
// 매거진 랭킹 렌더링 (3탭: 평가/배당/섹터)
// ============================================================
function _renderMagRanking(H, tV){
  var body=document.getElementById('chartMagBody');
  if(!body)return;

  // 탭 스위처 스타일 업데이트
  ['cmVal','cmDiv','cmSector'].forEach(function(id){
    var el=document.getElementById(id);
    if(!el)return;
    var isOn = (id==='cmVal'&&_chartMode==='val') || (id==='cmDiv'&&_chartMode==='div') || (id==='cmSector'&&_chartMode==='sector');
    if(isOn){
      el.style.background='var(--brand-primary)';
      el.style.color='#fff';
      el.style.fontWeight='800';
      el.style.boxShadow='0 2px 6px rgba(0,0,0,.15)';
    } else {
      el.style.background='transparent';
      el.style.color='var(--c-label)';
      el.style.fontWeight='700';
      el.style.boxShadow='none';
    }
  });

  // 배당 계산 헬퍼: 세전/세후 모드 반영
  function calcAnnDiv(h){
    var isAfter = (window._divTaxMode!=='before');
    var annPS=_annDivPS(h);
    if(!isAfter) return annPS*h.qty;
    var _trx=_getTaxRate(h)/100;
    var buys=h.buys||[];
    if(!buys.length){
      var isTax=(_isTaxAcct(h.acct)||h.acct==='pension');
      return annPS*h.qty*(isTax?1:(1-_trx));
    }
    var total=0;
    buys.forEach(function(b){
      var isTax=(_isTaxAcct(b.acct)||b.acct==='isa'||b.acct==='irp'||b.acct==='pension');
      total += annPS*b.qty*(isTax?1:(1-_trx));
    });
    return total;
  }

  if(_chartMode==='val'){
    body.innerHTML = _renderMagVal(H, tV);
  } else if(_chartMode==='div'){
    body.innerHTML = _renderMagDiv(H, tV, calcAnnDiv);
  } else {
    body.innerHTML = _renderMagSector(H, tV);
  }
}

// ------- 평가금액 탭 -------
// ============ 반원 도넛 차트 헬퍼 ============
function _kshort(n){
  n = Math.round(Math.abs(+n||0));
  if(n >= 1e8) return (n/1e8).toFixed(n>=1e9?0:1).replace(/\.0$/,'') + '억';
  if(n >= 1e4) return Math.round(n/1e4).toLocaleString() + '만';
  return n.toLocaleString();
}
function _p2c(cx,cy,r,deg){ var rad=deg*Math.PI/180; return {x:cx+r*Math.cos(rad), y:cy+r*Math.sin(rad)}; }
function _segPath(cx,cy,iR,oR,s,e){
  var o1=_p2c(cx,cy,oR,s), o2=_p2c(cx,cy,oR,e), i1=_p2c(cx,cy,iR,e), i2=_p2c(cx,cy,iR,s);
  var la = (e-s)>180?1:0;
  return 'M '+o1.x.toFixed(2)+' '+o1.y.toFixed(2)+' A '+oR+' '+oR+' 0 '+la+' 1 '+o2.x.toFixed(2)+' '+o2.y.toFixed(2)+' L '+i1.x.toFixed(2)+' '+i1.y.toFixed(2)+' A '+iR+' '+iR+' 0 '+la+' 0 '+i2.x.toFixed(2)+' '+i2.y.toFixed(2)+' Z';
}
// 실제 도넛 차트 + TOP5 범례 (6번째부터 "기타"로 합산)
function _renderSemiDonut(items, centerLabel, centerSub){
  if(!items || !items.length) return '';

  // === TOP5 + 기타 집계 ===
  var top = items.slice(0, 5);
  var rest = items.slice(5);
  if(rest.length > 0){
    var restPct = rest.reduce(function(s,x){return s+(x.pct||0);},0);
    var restAmt = rest.reduce(function(s,x){return s+(x.amt||0);},0);
    top.push({name:'기타 '+rest.length+'종목', pct:restPct, amt:restAmt, color:'var(--c-border)', isOther:true});
  }

  // === SVG 도넛 ===
  var cx=100, cy=100, iR=56, oR=92;
  var startA = -90;
  var paths = '';
  top.forEach(function(it){
    if(!it.pct || it.pct <= 0) return;
    var arc = (it.pct/100)*360;
    var endA = startA + arc;
    // 100% 근처면 원 전체를 그려야 함 (단일 세그먼트 케이스)
    if(arc >= 359.9){
      // 외곽 원: 두 개의 반원 호로 완전한 원 그리기
      // 내곽 원: 두 개의 반원 호로 완전한 원 그리기 (반대 방향)
      var oTop=cy-oR, oBot=cy+oR, iTop=cy-iR, iBot=cy+iR;
      paths += '<path fill-rule="evenodd" style="fill:'+it.color+'" d="'
        + 'M '+cx+' '+oTop+' A '+oR+' '+oR+' 0 0 1 '+cx+' '+oBot
        + ' A '+oR+' '+oR+' 0 0 1 '+cx+' '+oTop+' Z'
        + ' M '+cx+' '+iTop+' A '+iR+' '+iR+' 0 0 0 '+cx+' '+iBot
        + ' A '+iR+' '+iR+' 0 0 0 '+cx+' '+iTop+' Z"/>';
    } else {
      paths += '<path d="'+_segPath(cx,cy,iR,oR,startA,endA)+'" style="fill:'+it.color+'"/>';
    }
    startA = endA;
  });

  var donut = '<div style="display:flex;justify-content:center;padding:10px 14px 14px">'
    + '<div style="position:relative;width:180px;height:180px">'
      + '<svg viewBox="0 0 200 200" width="100%" height="100%" style="display:block">'+paths+'</svg>'
      + '<div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:3px;pointer-events:none">'
        + (centerSub ? '<div style="font-size:9.5px;font-weight:800;color:var(--c-label);letter-spacing:1.2px;text-transform:uppercase">'+_escHtml(centerSub)+'</div>' : '')
        + '<div class="donut-center-num" style="font-size:22px;font-weight:900;color:var(--c-text);line-height:1;font-family:\'Plus Jakarta Sans\',sans-serif">'+_escHtml(centerLabel||'').replace(/(원)$/,'<span class="donut-unit-krw">$1</span>')+'</div>'
      + '</div>'
    + '</div>'
  + '</div>';

  // === 범례 (최대 6행: TOP5 + 기타) ===
  var legend = '<div style="padding:2px 14px 14px;display:flex;flex-direction:column;gap:9px">';
  top.forEach(function(it){
    var amtStr = (it.amt !== undefined && it.amt !== null && it.amt > 0) ? _kshort(it.amt) : '';
    legend += '<div style="display:flex;align-items:center;gap:10px;font-size:12px">'
      + '<span style="width:10px;height:10px;border-radius:3px;background:'+it.color+';flex-shrink:0"></span>'
      + '<span style="flex:1;color:'+(it.isOther?'var(--c-label)':'var(--c-text)')+';font-weight:700;letter-spacing:-.2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0'+(it.isOther?';font-style:italic':'')+'">'+_escHtml(it.name)+'</span>'
      + (amtStr ? '<span style="font-family:\'Plus Jakarta Sans\',sans-serif;font-size:10.5px;color:var(--c-label);font-weight:700;min-width:56px;text-align:right;letter-spacing:-.1px">'+amtStr+'</span>' : '')
      + '<span style="font-family:\'Plus Jakarta Sans\',sans-serif;font-weight:900;color:var(--c-text);font-size:13px;letter-spacing:-.3px;min-width:44px;text-align:right">'+(it.pct||0).toFixed(1)+'%</span>'
    + '</div>';
  });
  legend += '</div>';

  return donut + legend;
}
// 범례 (2열 그리드)
function _renderDonutLegend(items){
  // 가로 막대 차트에 이름/퍼센트 이미 포함되어 별도 범례 불필요
  return '';
}

function _renderMagVal(H, tV){
  var isBuddha = (typeof BUDDHA!=='undefined') && !!BUDDHA;
  var sorted=H.slice().sort(function(a,b){return ((b.cur||b.avg)*b.qty)-((a.cur||a.avg)*a.qty);});
  var totalPnl=H.reduce(function(s,h){return s+((h.cur||h.avg)-h.avgCost)*h.qty;},0);
  var totalCost=H.reduce(function(s,h){return s+h.avgCost*h.qty;},0);
  var totalPct=totalCost>0?totalPnl/totalCost*100:0;

  var palBlue = COLORS;
  var items = sorted.map(function(h,i){
    var val=(h.cur||h.avg)*h.qty;
    return {name:h.n||'종목', pct:tV>0?val/tV*100:0, amt:val, color:palBlue[i%palBlue.length]};
  });

  var head = '<div style="padding:16px 14px 14px">'
    +'<div style="font-size:9px;font-weight:800;letter-spacing:2px;color:var(--c-label);text-transform:uppercase;margin-bottom:5px">EVALUATION · 평가금액 비중</div>'
    +'<div style="font-size:26px;font-weight:900;letter-spacing:-.9px;line-height:1;color:var(--c-text);font-family:\'Plus Jakarta Sans\',\'Noto Sans KR\',sans-serif">'+fmt(Math.round(tV))+'</div>'
    +(isBuddha?'':'<div style="display:flex;gap:14px;margin-top:12px;padding-top:10px;border-top:1px solid var(--c-border-2);font-size:10px;color:var(--c-label);font-weight:600;letter-spacing:.3px;text-transform:uppercase">'
      +'<span>종목<b style="display:block;color:var(--c-text);font-size:13px;margin-top:3px;letter-spacing:-.3px;text-transform:none;font-family:\'Plus Jakarta Sans\',sans-serif">'+H.length+'</b></span>'
      +'<span>평가손익<b style="display:block;color:'+(totalPnl>=0?'var(--c-blue-700)':'var(--state-loss)')+';font-size:13px;margin-top:3px;letter-spacing:-.3px;text-transform:none;font-family:\'Plus Jakarta Sans\',sans-serif">'+(totalPnl>=0?'+':'')+fmt(Math.round(totalPnl))+'</b></span>'
      +'<span>수익률<b style="display:block;color:'+(totalPct>=0?'var(--c-blue-700)':'var(--state-loss)')+';font-size:13px;margin-top:3px;letter-spacing:-.3px;text-transform:none;font-family:\'Plus Jakarta Sans\',sans-serif">'+(totalPct>=0?'+':'')+totalPct.toFixed(2)+'%</b></span>'
    +'</div>')
    +'</div>';

  var chart = _renderSemiDonut(items, _kshort(tV)+'원', 'TOTAL');
  var legend = _renderDonutLegend(items);
  return head + chart + legend;
}

// ------- 배당 탭 -------
function _renderMagDiv(H, tV, calcAnn){
  var isAfter = (window._divTaxMode!=='before');
  var taxLbl = isAfter ? '세후' : '세전';
  var taxSubLbl = isAfter ? 'AFTER TAX' : 'BEFORE TAX';
  // 배당 기준 정렬
  var enriched=H.map(function(h){
    var annDiv=calcAnn(h);
    var yld = h.cur>0 ? (_annDivPS(h)/h.cur*100) : 0;
    return {h:h, annDiv:annDiv, yld:yld};
  }).sort(function(a,b){return b.annDiv-a.annDiv;});

  var totalDiv=enriched.reduce(function(s,e){return s+e.annDiv;},0);
  var maxDiv=enriched[0]?enriched[0].annDiv:1;
  var monAvg=totalDiv/12;
  var yldTotal=tV>0?totalDiv/tV*100:0;

  var head = '<div style="padding:16px 14px 14px">'
    +'<div style="font-size:9px;font-weight:800;letter-spacing:2px;color:var(--c-label);text-transform:uppercase;margin-bottom:5px">DIVIDEND · '+taxSubLbl+' · 연 배당 순</div>'
    +'<div style="font-size:26px;font-weight:900;letter-spacing:-.9px;line-height:1;color:var(--c-text);font-family:\'Plus Jakarta Sans\',\'Noto Sans KR\',sans-serif">'+fmt(Math.round(totalDiv))+'</div>'
    +'<div style="display:flex;gap:14px;margin-top:12px;padding-top:10px;border-top:1px solid var(--c-border-2);font-size:10px;color:var(--c-label);font-weight:600;letter-spacing:.3px;text-transform:uppercase">'
    +'<span>월 평균<b style="display:block;color:var(--c-green-700);font-size:13px;margin-top:3px;letter-spacing:-.3px;text-transform:none;font-family:\'Plus Jakarta Sans\',sans-serif">'+fmt(Math.round(monAvg))+'</b></span>'
    +'<span>'+taxLbl+' 수익률<b style="display:block;color:var(--c-green-700);font-size:13px;margin-top:3px;letter-spacing:-.3px;text-transform:none;font-family:\'Plus Jakarta Sans\',sans-serif">'+yldTotal.toFixed(2)+'%</b></span>'
    +'<span>종목<b style="display:block;color:var(--c-text);font-size:13px;margin-top:3px;letter-spacing:-.3px;text-transform:none;font-family:\'Plus Jakarta Sans\',sans-serif">'+H.length+'</b></span>'
    +'</div>'
    +'</div>';

  var palMint = COLORS;
  var items = enriched.map(function(e,i){
    return {name:e.h.n||'종목', pct:totalDiv>0?e.annDiv/totalDiv*100:0, amt:e.annDiv, color:palMint[i%palMint.length]};
  });
  var chart = _renderSemiDonut(items, _kshort(totalDiv)+'원', '연 배당');
  var legend = _renderDonutLegend(items);
  return head + chart + legend;
}

// ------- 섹터 탭 -------
function _renderMagSector(H, tV){
  // 섹터 분류: 국내주식/국내ETF/미국주식/미국ETF
  function classify(h){
    var sym=(h.sym||'').toUpperCase();
    var n=h.n||'';
    var krEtfKw=/KODEX|TIGER|RISE|KBSTAR|HANARO|SOL |PLUS |ARIRANG|ACE |KINDEX|KOSEF|TREX|KSTAR/i;
    // 주요 미국 ETF 티커 (배당/커버드콜/인덱스/섹터/채권/테마)
    var usEtfPat=/^(JEPQ|JEPI|QYLD|XYLD|SCHD|VYM|SPY|QQQ|VOO|VTI|VT|IBIT|CONY|TSLY|NVDY|MSFO|YMAX|YMAG|PLTY|SOXL|TQQQ|SCHG|DGRO|DGRW|SDIV|DIV|SPHD|NOBL|DVY|SPYD|FDVV|DIA|IWM|GPIQ|GPIX|QQQI|SPYI|QYLG|RYLD|SVOL|AIPI|FEPI|NUSI|DIVO|ULTY|XDTE|QDTE|RDTE|YDTE|KNG|PAPI|BALI|ISPY|IWMY|SDTY|USOI|HDV|VIG|PFF|PGX|JNK|HYG|LQD|BND|AGG|TLT|IEF|SHY|MUB|EMB|TIP|GLD|SLV|IAU|GDX|GDXJ|FBTC|ARKB|BRRR|SCHF|VXUS|EFA|IEFA|VEA|VWO|IEMG|IXUS|ACWI|XLK|XLF|XLE|XLV|XLY|XLI|XLP|XLU|XLB|XLRE|XLC|VNQ|ARKK|ARKW|ARKF|ARKG|ARKQ|ARKX|AIQ|BOTZ|SMH|SOXX|BITI|SQQQ|SOXS|UVXY|SPXL|SPXS|SSO|SDS|QLD|QID|RDVY|SDY|JPST|SGOV|BIL|VTV|VUG|VO|VB|IVV|IVW|IVE|IJH|IJR|IWF|IWB|VWOB|AVUV|AVDV|CALF|PAVE|AMLP|MLPA|XBI|IBB|ITB|KRE|KBE|KIE|COPX|SIL|GNR|MOO|CORN|WEAT|USO|UNG|DBA|DBC|PALL|PPLT|JEPQ|QQQ5|SCHH|TDIV|FDVV|SDOG|DJIA|QQQM|SCHB|SCHX|SCHV|SCHA|SCHM|SCHD|QUAL|MTUM|USMV|VLUE|SIZE)$/i;
    // ETF 운용사/브랜드 키워드 (이름에 있으면 ETF로 판정)
    var etfBrandKw=/\b(iShares|Vanguard|SPDR|Invesco|ProShares|Direxion|VanEck|Global X|WisdomTree|First Trust|Roundhill|Simplify|Innovator|Amplify|JPMorgan|Goldman Sachs (?:Nasdaq|S&P|Bloomberg|MarketBeta|ActiveBeta|Innovate|Access|Future|Small-Cap|Equal)|Nasdaq (?:100|Bloomberg|Composite)|S&P 500|Russell|MSCI|FTSE)\b/i;
    var isKR = /\.(KS|KQ)$/i.test(sym) || krEtfKw.test(n);
    var isETF = krEtfKw.test(n) || /ETF|Covered Call|Premium Income|Nasdaq-100|index fund/i.test(n) || usEtfPat.test(sym) || etfBrandKw.test(n);
    if(isKR && isETF) return 'KR_ETF';
    if(isKR) return 'KR_STOCK';
    if(isETF) return 'US_ETF';
    return 'US_STOCK';
  }
  var SECTORS={
    KR_STOCK: {label:'국내주식', sub:'KR · Stock', color:'var(--stock-1)'},
    KR_ETF:   {label:'국내ETF', sub:'KR · ETF',   color:'var(--stock-2)'},
    US_STOCK: {label:'미국주식', sub:'US · Stock', color:'var(--stock-3)'},
    US_ETF:   {label:'미국ETF', sub:'US · ETF',   color:'var(--stock-4)'}
  };

  // 그룹별 묶기
  var groups={};
  H.forEach(function(h){
    var s=classify(h);
    if(!groups[s]) groups[s]={stocks:[], total:0};
    var val=(h.cur||h.avg)*h.qty;
    groups[s].stocks.push({h:h, val:val});
    groups[s].total+=val;
  });
  // 그룹을 total 큰 순으로
  var ordered=Object.keys(groups).map(function(k){return {key:k, ...groups[k]};}).sort(function(a,b){return b.total-a.total;});
  var maxGroup=ordered[0]?ordered[0].total:1;

  // 상단 스택 바
  var stackSegs = ordered.map(function(g){
    var pct=tV>0?g.total/tV*100:0;
    return '<div style="flex:'+(isFinite(pct)?pct.toFixed(2):'0')+';background:'+SECTORS[g.key].color+';height:10px"></div>';
  }).join('');
  var stackLabels = ordered.map(function(g){
    var pct=tV>0?g.total/tV*100:0;
    return '<div style="flex:'+(isFinite(pct)?pct.toFixed(2):'0')+';display:flex;justify-content:center;gap:4px;align-items:baseline;min-width:0"><span style="color:var(--c-label);font-weight:700;font-size:9px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+SECTORS[g.key].label+'</span><b style="color:var(--c-text);font-family:\'Plus Jakarta Sans\',sans-serif;letter-spacing:-.2px;font-size:10px;font-weight:800">'+(isFinite(pct)?pct.toFixed(1):'0.0')+'%</b></div>';
  }).join('');

  var maxSec = ordered[0]&&tV>0?SECTORS[ordered[0].key].label+' '+(ordered[0].total/tV*100).toFixed(1)+'%':'-';
  var diversity = ordered.length>=3 ? '양호' : (ordered.length>=2 ? '부족' : '집중');
  var divColor = ordered.length>=3 ? 'var(--state-success)' : (ordered.length>=2 ? 'var(--state-warning)' : 'var(--state-loss)');

  var head = '<div style="padding:16px 14px 14px">'
    +'<div style="font-size:9px;font-weight:800;letter-spacing:2px;color:var(--c-label);text-transform:uppercase;margin-bottom:5px">SECTORS · 섹터별 분산</div>'
    +'<div style="font-size:26px;font-weight:900;letter-spacing:-.9px;line-height:1;color:var(--c-text);font-family:\'Plus Jakarta Sans\',\'Noto Sans KR\',sans-serif">'+ordered.length+'<span style="font-size:16px;color:var(--c-label);font-weight:700;margin-left:4px">개 섹터</span></div>'
    +'<div style="display:flex;gap:14px;margin-top:12px;padding-top:10px;border-top:1px solid var(--c-border-2);font-size:10px;color:var(--c-label);font-weight:600;letter-spacing:.3px;text-transform:uppercase">'
    +'<span>최대 섹터<b style="display:block;color:var(--c-text);font-size:13px;margin-top:3px;letter-spacing:-.3px;text-transform:none">'+maxSec+'</b></span>'
    +'<span>분산도<b style="display:block;color:'+divColor+';font-size:13px;margin-top:3px;letter-spacing:-.3px;text-transform:none">'+diversity+'</b></span>'
    +'</div>'
    +'</div>';

  var sectorItems = ordered.map(function(g){
    return {name:SECTORS[g.key].label, pct:tV>0?g.total/tV*100:0, amt:g.total, color:SECTORS[g.key].color};
  });
  var stackSection = _renderSemiDonut(sectorItems, ordered.length+'개', '섹터') + _renderDonutLegend(sectorItems);

  // 각 섹터별 그룹 + 종목
  var rankCount=0;
  var groupHtml = ordered.map(function(g){
    var sec=SECTORS[g.key];
    var pct=g.total/tV*100;
    var groupHead = '<div style="padding:10px 14px 6px;display:flex;align-items:center;justify-content:space-between;background:var(--c-border-2);border-top:1px solid var(--c-border-2);border-bottom:1px solid var(--c-border-2);font-size:10px;font-weight:800;letter-spacing:.3px;color:var(--c-text);text-transform:uppercase">'
      +'<span><span style="display:inline-block;width:8px;height:8px;border-radius:2px;background:'+sec.color+';margin-right:6px;vertical-align:middle"></span>'+sec.label+' · '+sec.sub+'</span>'
      +'<span style="color:var(--c-label);font-weight:600;font-size:9.5px;text-transform:none">'+g.stocks.length+'종목 · '+fmt(Math.round(g.total))+' · '+pct.toFixed(1)+'%</span>'
      +'</div>';
    // 종목 정렬 (해당 섹터 내 value 큰 순)
    var items = g.stocks.slice().sort(function(a,b){return b.val-a.val;}).map(function(s){
      rankCount++;
      var itemPct=tV>0?s.val/tV*100:0;
      return '<div style="display:grid;grid-template-columns:28px 1fr auto;gap:10px;align-items:center;padding:11px 14px;border-bottom:1px solid var(--c-border-2)">'
        +'<div style="font-size:17px;font-weight:900;color:var(--c-text);letter-spacing:-.5px;font-family:\'Plus Jakarta Sans\',sans-serif;line-height:1">'+String(rankCount).padStart(2,'0')+'</div>'
        +'<div style="display:flex;align-items:center;gap:10px;min-width:0">'
          +'<div style="width:10px;height:10px;border-radius:3px;background:'+sec.color+';flex-shrink:0"></div>'
          +'<div style="min-width:0;flex:1">'
            +'<div style="font-size:12px;font-weight:700;color:var(--c-text);letter-spacing:-.2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+_escHtml(s.h.n||'')+'</div>'
            +'<span style="display:inline-block;font-size:8.5px;font-weight:900;padding:2px 6px;border-radius:4px;letter-spacing:.3px;margin-top:5px;background:var(--c-border-2);color:'+sec.color+'">'+sec.sub.toUpperCase()+'</span>'
          +'</div>'
        +'</div>'
        +'<div style="text-align:right;font-family:\'Plus Jakarta Sans\',sans-serif;min-width:65px">'
          +'<div style="font-size:15px;font-weight:900;color:var(--c-text);letter-spacing:-.4px;line-height:1">'+itemPct.toFixed(1)+'%</div>'
          +'<div style="font-size:9.5px;color:var(--c-label);margin-top:3px;font-weight:600">'+fmt(Math.round(s.val))+'</div>'
        +'</div>'
        +'</div>';
    }).join('');
    return groupHead + items;
  }).join('');

  return head + stackSection + groupHtml;
}

// ============================================================
// 인사이트 ① — 집중도 점수 (Herfindahl 기반)
// ============================================================
function _renderConcentration(H, tV){
  var el=document.getElementById('concentrationCard');
  if(!el)return;
  if(!H.length||tV<=0){ el.style.display='none'; return; }
  el.style.display='block';
  // 각 종목 비중
  var weights=H.map(function(h){return (h.cur||h.avg)*h.qty/tV;});
  weights.sort(function(a,b){return b-a;});
  var top=weights[0]*100;
  // Herfindahl 지수 (0~1, 1이면 1종목)
  var hhi=weights.reduce(function(s,w){return s+w*w;},0);
  var hhiPct=hhi*100;
  // 점수 산정: 집중도 낮을수록 좋음
  var score, label, color, bgColor, advice;
  if(top>=50){ score='집중'; color='#dc2626'; bgColor='linear-gradient(95deg,#fef2f2,#fee2e2)'; advice='1위 종목이 전체의 절반 이상 · 분산 권장'; }
  else if(top>=35){ score='주의'; color='#d97706'; bgColor='linear-gradient(95deg,#fffbeb,#fef3c7)'; advice='상위 종목 의존도 높음 · 추가 종목 검토'; }
  else if(top>=20 && H.length>=5){ score='양호'; color='#059669'; bgColor='linear-gradient(95deg,#ecfdf5,#d1fae5)'; advice='적절한 분산 · 건강한 포트폴리오'; }
  else if(H.length<3){ score='부족'; color='#6366f1'; bgColor='linear-gradient(95deg,#eef2ff,#e0e7ff)'; advice='보유 종목 수 부족 · 3종목 이상 권장'; }
  else { score='우수'; color='#059669'; bgColor='linear-gradient(95deg,#ecfdf5,#a7f3d0)'; advice='고른 분산 · 이상적 구성'; }
  // 1위 종목 이름
  var topName='-';
  var sorted=H.slice().sort(function(a,b){return ((b.cur||b.avg)*b.qty)-((a.cur||a.avg)*a.qty);});
  if(sorted[0])topName=sorted[0].n||'';
  // 게이지 위치 (0~100% → 0~50%+ 범위로 매핑)
  var pos=Math.min(top*2, 100);

  el.innerHTML=
    '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px">'
    +'<div style="display:flex;align-items:center;gap:8px">'
    +'<div style="font-size:10px;font-weight:800;color:var(--c-label);letter-spacing:1.5px;text-transform:uppercase">집중도</div>'
    +'<div style="font-size:9.5px;font-weight:800;color:'+color+';background:'+bgColor+';padding:3px 9px;border-radius:99px;letter-spacing:.3px">'+score+'</div>'
    +'</div>'
    +'<div style="font-size:10.5px;color:var(--c-label);font-weight:600">HHI '+hhiPct.toFixed(1)+'</div>'
    +'</div>'
    // 게이지
    +'<div style="height:26px;background:linear-gradient(90deg,var(--c-green-500) 0% 33%,var(--c-gold-400) 33% 66%,#ef4444 66% 100%);border-radius:6px;position:relative;margin-bottom:10px">'
    +'<div style="position:absolute;top:-4px;bottom:-4px;width:3px;background:var(--c-text);left:calc('+pos+'% - 1.5px);border-radius:2px;box-shadow:0 1px 4px rgba(0,0,0,.3)"></div>'
    +'<div style="position:absolute;top:-18px;left:calc('+pos+'% - 20px);font-size:10px;font-weight:900;color:var(--c-text);white-space:nowrap;font-family:\'Plus Jakarta Sans\',sans-serif">'+top.toFixed(1)+'%</div>'
    +'</div>'
    // 눈금
    +'<div style="display:flex;justify-content:space-between;font-size:8.5px;color:var(--c-label);font-weight:700;letter-spacing:.5px;text-transform:uppercase;margin-bottom:12px">'
    +'<span>분산 · 안전</span><span>중간</span><span>집중 · 위험</span>'
    +'</div>'
    // 설명
    +'<div style="font-size:11px;color:#475569;line-height:1.5;padding-top:10px;border-top:1px solid #f1f5f9">'
    +'<b style="color:var(--c-text)">'+_escHtml(topName)+'</b>이 <b style="color:'+color+'">'+top.toFixed(1)+'%</b> · '+advice
    +'</div>';
}

// ============================================================
// 인사이트 ② — 계좌별 분산도 (일반/ISA/IRP/연금)
// ============================================================
function _renderAccountMix(H, tV){
  var el=document.getElementById('accountMixCard');
  if(!el)return;
  if(!H.length||tV<=0){ el.style.display='none'; return; }
  el.style.display='block';

  // 계좌별 평가금액 집계
  var byAcct={general:0, isa:0, irp:0, pension:0, tax:0};
  H.forEach(function(h){
    var val=(h.cur||h.avg)*h.qty;
    var buys=h.buys||[];
    if(buys.length){
      var totQ=buys.reduce(function(s,b){return s+b.qty;},0);
      buys.forEach(function(b){
        var a=b.acct||'general';
        if(!(a in byAcct))a='general';
        byAcct[a]+=val*(b.qty/totQ);
      });
    } else {
      var a=h.acct||'general';
      if(!(a in byAcct))a='general';
      byAcct[a]+=val;
    }
  });
  // 구형 'tax' 데이터는 isa로 합산
  byAcct.isa+=byAcct.tax; byAcct.tax=0;
  var meta=[
    {k:'general', n:'일반',   col:'linear-gradient(135deg,var(--acct-general-g1),var(--acct-general-g2))', textCol:'var(--acct-general-text)', taxRate:0.154},
    {k:'isa',     n:'ISA',    col:'linear-gradient(135deg,var(--acct-tax-g1),var(--acct-tax-g2))', textCol:'var(--acct-tax-text)', taxRate:0},
    {k:'irp',     n:'IRP',    col:'linear-gradient(135deg,var(--acct-tax-g2),var(--acct-tax))', textCol:'var(--acct-tax-text)', taxRate:0},
    {k:'pension', n:'연금저축',col:'linear-gradient(135deg,var(--acct-tax),var(--acct-tax-text))', textCol:'var(--acct-tax-text)', taxRate:0}
  ];
  var activeAccts=meta.filter(function(m){return byAcct[m.k]>0;});
  if(!activeAccts.length){ el.style.display='none'; return; }

  // 연간 절세 효과 계산 (세전 연배당 × 절세계좌 비율 × 15.4%)
  var annDivPre=H.reduce(function(s,h){return s+_annDivPS(h)*h.qty;},0);
  var taxableAssets=byAcct.general;
  var taxShieldAssets=byAcct.isa+byAcct.irp+byAcct.pension;
  var taxShieldRatio=tV>0?taxShieldAssets/tV:0;
  var yearlySaving=annDivPre*taxShieldRatio*0.154;

  // 스택 바
  var segHtml=activeAccts.map(function(m){
    var pct=byAcct[m.k]/tV*100;
    return '<div style="flex:'+pct.toFixed(2)+';background:'+m.col+';display:flex;align-items:center;justify-content:center;color:#fff;font-size:10px;font-weight:800;letter-spacing:-.2px;min-width:'+(pct<8?'0':'auto')+'">'+(pct>=10?pct.toFixed(0)+'%':'')+'</div>';
  }).join('');

  // 범례
  var legHtml=activeAccts.map(function(m){
    var pct=byAcct[m.k]/tV*100;
    var amt=fmt(Math.round(byAcct[m.k]));
    return '<div style="display:flex;align-items:center;gap:6px;padding:6px 0;font-size:10.5px">'
      +'<div style="width:10px;height:10px;border-radius:3px;background:'+m.col+';flex-shrink:0"></div>'
      +'<div style="flex:1;color:var(--c-text);font-weight:700">'+m.n+'</div>'
      +'<div style="font-family:\'Plus Jakarta Sans\',sans-serif;font-size:11.5px;font-weight:800;color:'+m.textCol+';letter-spacing:-.2px">'+pct.toFixed(1)+'%</div>'
      +'<div style="font-size:9.5px;color:var(--c-label);font-weight:600;min-width:55px;text-align:right">'+amt+'</div>'
      +'</div>';
  }).join('');

  el.innerHTML=
    '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px">'
    +'<div style="font-size:10px;font-weight:800;color:var(--c-label);letter-spacing:1.5px;text-transform:uppercase">계좌 분산</div>'
    +'<div style="font-size:10px;color:var(--c-label);font-weight:600">'+activeAccts.length+'개 계좌</div>'
    +'</div>'
    // 스택 바
    +'<div style="display:flex;gap:2px;height:30px;border-radius:7px;overflow:hidden;box-shadow:0 2px 6px rgba(0,0,0,.08);margin-bottom:10px">'+segHtml+'</div>'
    // 범례
    +'<div style="border-top:1px solid var(--c-border-2);padding-top:4px">'+legHtml+'</div>'
    // 절세 효과 메시지
    +(yearlySaving>=1000
      ? '<div style="margin-top:10px;padding:10px 12px;background:linear-gradient(95deg,var(--acct-tax-soft),var(--acct-tax-bg));border:1px solid var(--acct-tax-g1);border-radius:8px;display:flex;align-items:center;gap:8px">'
        +'<div style="font-size:18px">🌱</div>'
        +'<div style="font-size:11px;color:var(--acct-tax-text);line-height:1.5;font-weight:600">절세계좌 <b style="color:var(--acct-tax-text);font-weight:900">'+(taxShieldRatio*100).toFixed(0)+'%</b> · 연 <b style="color:var(--acct-tax-text);font-family:\'Plus Jakarta Sans\',sans-serif;font-weight:900">'+fmt(Math.round(yearlySaving))+'</b> 절감 중</div>'
        +'</div>'
      : '');
}

// ============================================================
// 한국어 조사 자동 선택 헬퍼 (받침 유무에 따라 "이/가", "은/는", "을/를", "과/와", "으로/로")
// 영어 이름(Tesla, Apple 등), 숫자도 한국어 발음 기준으로 판별
// 사용: _particle('Tesla, Inc.', '이') → '가'  |  _particle('삼성전자', '이') → '가'
// ============================================================
function _particle(word, type){
  if(!word) return type; // 방어: 빈 문자열이면 기본값
  // HTML 태그 제거 (이미 <b> 등이 포함된 경우 대비)
  var clean = String(word).replace(/<[^>]*>/g, '').replace(/&[a-z]+;/gi,'').trim();
  if(!clean) return type;
  // 법인 접미사 제거 (Inc, Corp, Ltd, LLC, Co 등) — 실제 발음 시 생략되는 부분
  clean = clean.replace(/[,\s]+(Inc|Corp|Corporation|Ltd|LLC|Co|Company|Group|Holdings?|Limited|Plc|SA|AG|NV|BV)\.?$/i, '');
  // 구두점 제거 (뒤에서부터)
  clean = clean.replace(/[.,!?;:'"”’\s()[\]{}]+$/g, '');
  if(!clean) return type;
  var lastChar = clean.charAt(clean.length-1);
  var code = lastChar.charCodeAt(0);
  var hasJongseong; // 받침 유무
  if(code>=0xAC00 && code<=0xD7A3){
    // 한글 음절: (code - 0xAC00) % 28 !== 0 이면 받침 있음
    hasJongseong = ((code - 0xAC00) % 28) !== 0;
  } else if(/[a-zA-Z]/.test(lastChar)){
    // 영문자: 한국어 발음 마지막 글자 기준
    // 받침 있는 알파벳(한국어 표기): L(엘), M(엠), N(엔), NG(-ing), R(-아ㄹ), K/G/C(-ㄱ받침)
    var tail = clean.toLowerCase();
    // 묵음 e 처리: Apple, Microsoft(는 e 없음), Google → Google은 'le'로 끝, Apple도 'le'
    // 'e'로 끝나면서 앞이 자음이면 묵음으로 간주하고 그 앞 글자로 판단
    if(tail.slice(-1)==='e' && tail.length>=2 && /[bcdfghjklmnpqrstvwxz]/.test(tail.slice(-2,-1))){
      tail = tail.slice(0, -1);
    }
    var last2 = tail.slice(-2);
    var last1 = tail.slice(-1);
    if(last2==='ng'){
      hasJongseong = true; // '킹', '롱' 등
    } else if(last1==='l' || last1==='m' || last1==='n' || last1==='r'){
      hasJongseong = true;
    } else if(last1==='k' || last1==='g' || last1==='c' || last1==='x' || last1==='p' || last1==='b'){
      hasJongseong = true; // -ㄱ받침/-ㅂ받침
    } else {
      hasJongseong = false;
    }
  } else if(/[0-9]/.test(lastChar)){
    // 숫자: 0(영·공)→있음, 1(일)→있음, 2(이)→없음, 3(삼)→있음, 4(사)→없음
    //       5(오)→없음, 6(육)→있음, 7(칠)→있음, 8(팔)→있음, 9(구)→없음
    var digitHas = {'0':true,'1':true,'2':false,'3':true,'4':false,
                    '5':false,'6':true,'7':true,'8':true,'9':false};
    hasJongseong = digitHas[lastChar];
  } else {
    // 판별 불가: 기본값 반환
    return type;
  }
  // 조사 매핑
  var pairs = {
    '이':'가', '가':'가',  // 받침있음:이, 없음:가
    '은':'는', '는':'는',
    '을':'를', '를':'를',
    '과':'와', '와':'와',
    '으로':'로', '로':'로'
  };
  var withJong = {'이':'이','가':'이','은':'은','는':'은','을':'을','를':'을','과':'과','와':'과','으로':'으로','로':'으로'};
  var withoutJong = {'이':'가','가':'가','은':'는','는':'는','을':'를','를':'를','과':'와','와':'와','으로':'로','로':'로'};
  return hasJongseong ? (withJong[type]||type) : (withoutJong[type]||type);
}

// ============================================================
// 인사이트 ③ — AI 인사이트 카드 (룰 기반 분석 엔진)
// ============================================================
function _renderAIInsights(H, tV){
  var el=document.getElementById('aiInsightsCard');
  if(!el)return;
  if(!H.length||tV<=0){ el.style.display='none'; return; }

  var insights=[];

  // --- 계산 helper ---
  var sorted=H.slice().sort(function(a,b){return ((b.cur||b.avg)*b.qty)-((a.cur||a.avg)*a.qty);});
  var top=sorted[0];
  var topWeight=top?((top.cur||top.avg)*top.qty/tV*100):0;
  var stockCount=H.length;

  // 계좌별 집계
  var byAcct={general:0, isa:0, irp:0, pension:0};
  H.forEach(function(h){
    var val=(h.cur||h.avg)*h.qty;
    var buys=h.buys||[];
    if(buys.length){
      var totQ=buys.reduce(function(s,b){return s+b.qty;},0);
      buys.forEach(function(b){
        var a=b.acct||'general';
        if(a==='tax')a='isa';
        if(!(a in byAcct))a='general';
        byAcct[a]+=val*(b.qty/totQ);
      });
    } else {
      var a=h.acct||'general';
      if(a==='tax')a='isa';
      if(!(a in byAcct))a='general';
      byAcct[a]+=val;
    }
  });
  var taxShield=byAcct.isa+byAcct.irp+byAcct.pension;
  var taxShieldRatio=tV>0?taxShield/tV:0;
  var annDivPre=H.reduce(function(s,h){return s+_annDivPS(h)*h.qty;},0);
  var yearlySaving=annDivPre*taxShieldRatio*0.154;

  // --- 룰 1: 집중도 ---
  if(topWeight>=50){
    insights.push({type:'warn', icon:'⚠️', pri:10,
      msg:'<b>'+_escHtml(top.n||'1위 종목')+'</b>'+_particle(top.n||'1위 종목','이')+' <b>'+topWeight.toFixed(1)+'%</b>로 과도하게 집중 · 분산 권장'});
  } else if(topWeight>=35){
    insights.push({type:'tip', icon:'💡', pri:6,
      msg:'1위 <b>'+_escHtml(top.n||'종목')+' '+topWeight.toFixed(1)+'%</b> · 절반 넘으면 조심하세요'});
  } else if(topWeight<30 && stockCount>=5){
    insights.push({type:'good', icon:'✅', pri:3,
      msg:'1위 종목 <b>'+topWeight.toFixed(1)+'%</b> · 집중도 양호한 분산 포트폴리오'});
  }

  // --- 룰 2: 절세계좌 활용 ---
  if(taxShieldRatio>=0.4){
    insights.push({type:'good', icon:'🌱', pri:4,
      msg:'절세계좌 <b>'+(taxShieldRatio*100).toFixed(0)+'%</b> · 연 <b>'+fmt(Math.round(yearlySaving))+'</b> 세금 절감 중'});
  } else if(taxShieldRatio<0.1 && tV>=30000000){
    var potentialSave=annDivPre*0.5*0.154;
    insights.push({type:'tip', icon:'💡', pri:8,
      msg:'절세계좌 활용 낮음 · ISA/IRP로 이동 시 연 <b>~'+fmt(Math.round(potentialSave))+'</b> 절감 가능'});
  }

  // --- 룰 3: 고배당 이상치 ---
  var highYield=null;
  H.forEach(function(h){
    var annPS=_annDivPS(h);
    if(!h.cur||h.cur<=0||!annPS)return;
    var yld=annPS/h.cur*100;
    if(yld>=30 && (!highYield||yld>highYield.yld)){
      highYield={name:h.n||'', yld:yld};
    }
  });
  if(highYield){
    insights.push({type:'warn', icon:'⚠️', pri:9,
      msg:'<b>'+_escHtml(highYield.name)+'</b> 배당률 <b>'+highYield.yld.toFixed(1)+'%</b> · 초고배당 ETF는 원금 훼손 가능성, 주기 점검 권장'});
  }

  // --- 룰 4: 종목 수 ---
  if(stockCount<3){
    insights.push({type:'tip', icon:'📊', pri:7,
      msg:'보유 종목 <b>'+stockCount+'개</b> · 분산 위해 <b>3~5종목</b> 이상 추천'});
  } else if(stockCount>=10){
    insights.push({type:'good', icon:'🎯', pri:2,
      msg:'<b>'+stockCount+'종목</b> 보유 · 충분한 분산, 이제 비중 관리에 집중'});
  }

  // --- 룰 5: 배당 성장 동기 ---
  if(annDivPre>=6000000 && taxShieldRatio<0.5){
    var nowMonthly=annDivPre*(1-0.154*(1-taxShieldRatio))/12;
    var potentialMonthly=annDivPre/12;
    var diff=potentialMonthly-nowMonthly;
    insights.push({type:'tip', icon:'💸', pri:5,
      msg:'세후 월 <b>'+fmt(Math.round(nowMonthly))+'</b> · 전부 절세계좌면 <b>'+fmt(Math.round(potentialMonthly))+'</b> (+<b>'+fmt(Math.round(diff))+'</b>)'});
  }

  // 우선순위 정렬 후 상위 3개
  insights.sort(function(a,b){return b.pri-a.pri;});
  insights=insights.slice(0,3);

  if(!insights.length){ el.style.display='none'; return; }
  el.style.display='block';

  var color={
    warn:{bg:'linear-gradient(95deg,#fffbeb,#fef3c7)', border:'#fde68a', text:'#78350f', bold:'#92400e'},
    tip: {bg:'linear-gradient(95deg,#eff6ff,#dbeafe)', border:'#bfdbfe', text:'#1e40af', bold:'#1e3a8a'},
    good:{bg:'linear-gradient(95deg,#ecfdf5,#d1fae5)', border:'#a7f3d0', text:'#065f46', bold:'#047857'}
  };

  var inner=insights.map(function(ins){
    var c=color[ins.type]||color.tip;
    return '<div style="background:'+c.bg+';border:1px solid '+c.border+';border-radius:10px;padding:11px 13px;margin-bottom:8px;display:flex;gap:10px;align-items:flex-start">'
      +'<div style="font-size:18px;line-height:1.2;flex-shrink:0">'+ins.icon+'</div>'
      +'<div style="flex:1;font-size:11.5px;line-height:1.5;color:'+c.text+';font-weight:600">'
      +ins.msg.replace(/<b>/g,'<b style="color:'+c.bold+';font-weight:800">')
      +'</div>'
      +'</div>';
  }).join('');

  el.innerHTML=
    '<div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px">'
    +'<div style="font-size:10px;font-weight:800;color:var(--c-label);letter-spacing:1.5px;text-transform:uppercase">💬 인사이트</div>'
    +'<div style="font-size:9.5px;color:var(--c-label);font-weight:600;padding:2px 8px;background:#f1f5f9;border-radius:99px">분석 엔진</div>'
    +'</div>'
    +inner;
}


/* ===== HIST ===== */
function delSellRecord(idx){
  if(!confirm('이 매도 내역을 삭제하고 보유수량을 복원할까요?'))return;
  const sell=D.sells[idx];
  if(!sell)return;
  // 보유종목에서 같은 이름 찾아서 수량 복원
  const h=D.h.find(x=>x.n===sell.n);
  if(h){
    h.qty+=sell.qty;
    // buys에도 복원 기록 추가
    const rid=Date.now()+'_r';
    h.buys=h.buys||[];
    h.buys.push({id:rid,qty:sell.qty,price:sell.avgCost||sell.price,date:sell.date||new Date().toISOString().split('T')[0],acct:h.acct||'general',restored:true});
    // 평균단가 재계산
    const totalQty=h.buys.reduce((s,b)=>s+b.qty,0);
    const totalCost=h.buys.reduce((s,b)=>s+b.qty*b.price,0);
    h.avg=Math.round(totalCost/totalQty);
    h.avgCost=h.avg;
  }
  D.sells.splice(idx,1);
  save();render();renderHist();
}

function renderHist(){
  const hc=document.getElementById('histCont');
  const sells=D.sells;
  const total=sells.reduce((s,x)=>s+x.pnl,0);
  if(!sells.length){hc.innerHTML=`<div class="empty"><div style="font-size:36px;margin-bottom:10px">📋</div><div>매도 내역이 없습니다</div><div style="font-size:12px;margin-top:6px">포트폴리오에서 매도하면 여기에 기록됩니다</div></div>`;return;}
  hc.innerHTML=`
<div class="hist-card" style="margin-bottom:10px">
  <div style="display:flex;justify-content:space-between;align-items:center">
    <div><div style="font-size:11px;color:#aaa;margin-bottom:2px">누적 실현손익</div><div style="font-size:22px;font-weight:700;color:${total>=0?'#e63946':'var(--c-blue-700)'}">${total>=0?'+':''}${fmt(total)}</div></div>
    <button onclick="if(confirm('실현손익 이력을 초기화할까요?')){D.sells=[];save();renderHist();}" style="font-size:11px;padding:6px 12px;border-radius:8px;border:1px solid #fecaca;background:var(--c-red-50);color:var(--state-loss);cursor:pointer">초기화</button>
  </div>
</div>
<div class="hist-card">
  <div class="cttl">매도 내역 (최신순)</div>
  ${[...sells].reverse().map((x,ri)=>{
    const idx=sells.length-1-ri; // 원래 인덱스
    return`<div class="hist-row">
    <div style="flex:1;min-width:0"><div style="font-weight:600">${x.n}</div><div style="color:#aaa;margin-top:1px">${x.date} · ${fN(x.qty)}주 @ ${fN(x.price)}원</div></div>
    <div style="text-align:right;margin-right:10px"><div style="font-weight:700;color:${x.pnl>=0?'#e63946':'var(--c-blue-700)'}">${x.pnl>=0?'+':''}${fmt(x.pnl)}</div><div style="font-size:11px;color:#aaa">${x.pnlRate>=0?'+':''}${x.pnlRate.toFixed(2)}%</div></div>
    <button onclick="delSellRecord(${idx})" style="flex-shrink:0;padding:4px 8px;border:1px solid #fecaca;background:var(--c-red-50);color:var(--state-loss);border-radius:7px;font-size:11px;cursor:pointer">삭제</button>
  </div>`;
  }).join('')}
</div>`;
}

/* ===== TABS / FILTERS ===== */
// 모달 열기/닫기 (원본 파일 잘림으로 누락)
// ── 모달 열/닫기 + 배경 스크롤 잠금 ──
let _scrollY=0;
function lockBodyScroll(){
  _scrollY=window.scrollY||window.pageYOffset||0;
  document.body.style.top='-'+_scrollY+'px';
  document.body.classList.add('modal-open');
}
function unlockBodyScroll(){
  document.body.classList.remove('modal-open');
  document.body.style.top='';
  window.scrollTo(0,_scrollY);
}
function anyModalOpen(){
  const ids=['histOv','addOv','buyOv','sellOv','editBuyOv','ssOv','goalOv','divReportOv'];
  return ids.some(id=>{const el=document.getElementById(id);return el&&el.classList.contains('show');});
}
function openModal(id){
  var el=document.getElementById(id);if(!el)return;
  if(!anyModalOpen())lockBodyScroll();
  el.classList.add('show');
}
function closeModal(id){
  var el=document.getElementById(id);
  if(!el)return;
  if(!el.classList.contains('show'))return;
  // histOv/addOv/divReportOv: 자체 스와이프 애니메이션 사용 시 즉시 닫기 (중복 애니메이션 방지)
  if(id==='histOv'){
    var modal=document.getElementById('histOvModal');
    if(modal&&modal.style.transform){modal.style.transform='';modal.style.transition='';el.style.background='';el.classList.remove('show');if(!anyModalOpen())unlockBodyScroll();return;}
  }
  if(id==='addOv'){
    var am=document.getElementById('addOvModal');
    if(am&&am.style.transform){am.style.transform='';am.style.transition='';el.style.background='';el.classList.remove('show');if(!anyModalOpen())unlockBodyScroll();return;}
  }
  if(id==='divReportOv'){
    // 스와이프 핸들러가 setTimeout 안에서 호출 → transform은 이미 완료 상태
    // 배경도 이미 투명하게 fadeout 완료. 플래그로 판단
    if(el.dataset.swipeClosed==='1'){delete el.dataset.swipeClosed;el.classList.remove('show');if(!anyModalOpen())unlockBodyScroll();return;}
  }
  // 닫기 애니메이션 (시트 슬라이드다운 + 오버레이 페이드아웃 동기)
  el.classList.add('closing');
  var CLOSE_DUR=260;
  setTimeout(function(){
    el.classList.remove('show');
    el.classList.remove('closing');
    if(!anyModalOpen())unlockBodyScroll();
  },CLOSE_DUR);
}

// 🚑 안전장치: 모달 상태와 body 잠금의 정합성 체크
// (오버레이 배경 탭/ESC 등으로 unlock이 누락된 경우 자동 복구)
function _sanityCheckBodyLock(){
  if(!document.body.classList.contains('modal-open'))return;
  var anyOpen=document.querySelector('.ov.show, #bugModal.show, #installModal.show, #onboardingOverlay.show, #betaNoticeOv[style*="flex"]');
  if(!anyOpen){
    document.body.classList.remove('modal-open');
    document.body.style.top='';
  }
}
document.addEventListener('visibilitychange', _sanityCheckBodyLock);
window.addEventListener('pageshow', _sanityCheckBodyLock);
window.addEventListener('focus', _sanityCheckBodyLock);

// ── 스와이프 중 오버레이 비주얼 동기화 (opacity + blur 실시간 연동) ──
// 유저가 모달을 아래로 끌어내릴 때 배경이 자연스럽게 밝아지고 선명해지도록
function _ovSyncSwipe(ov, ratio){
  if(!ov) return;
  var r = Math.max(0, Math.min(1, ratio));
  var BASE_OP = 0.42;
  var BASE_BLUR = 3; // CSS 기본값과 동일
  ov.style.background = 'rgba(0,0,0,' + (BASE_OP * r).toFixed(3) + ')';
  var blurVal = (BASE_BLUR * r).toFixed(2) + 'px';
  ov.style.backdropFilter = 'blur(' + blurVal + ')';
  ov.style.webkitBackdropFilter = 'blur(' + blurVal + ')';
}
// 스와이프 종료 시 인라인 스타일 리셋 (CSS 기본값으로 복귀)
function _ovResetSwipe(ov){
  if(!ov) return;
  ov.style.background = '';
  ov.style.backdropFilter = '';
  ov.style.webkitBackdropFilter = '';
  ov.style.transition = '';
}

// ── 종목상세 카드 스와이프 다운 닫기 ──
(function(){
  var ov,modal,startY,startScroll,deltaY,swiping,cardH;
  var BASE_OP=0.42, DISMISS_TH=120;

  function init(){
    ov=document.getElementById('histOv');
    modal=document.getElementById('histOvModal');
    if(!modal)return;
    modal.addEventListener('touchstart',onStart,{passive:true});
    modal.addEventListener('touchmove',onMove,{passive:false});
    modal.addEventListener('touchend',onEnd,{passive:true});
  }

  function onStart(e){
    startScroll=modal.scrollTop;
    startY=e.touches[0].clientY;
    deltaY=0;
    swiping=false;
    cardH=modal.offsetHeight;
    modal.style.transition='none';
  }

  function onMove(e){
    var curY=e.touches[0].clientY;
    deltaY=curY-startY;
    // 스크롤이 맨 위 + 아래로 당기는 중 → 스와이프 모드
    if(startScroll<=0&&deltaY>0){
      swiping=true;
      e.preventDefault();
      modal.style.transform='translateY('+deltaY+'px)';
      // 배경 opacity + blur 비례 감소 (실시간 동기화)
      var ratio=Math.max(0,1-deltaY/(cardH*0.5));
      _ovSyncSwipe(ov, ratio);
    } else {
      swiping=false;
    }
  }

  function onEnd(){
    if(!swiping){modal.style.transform='';modal.style.transition='';return;}
    if(deltaY>DISMISS_TH){
      // 충분히 내렸으면 → 닫기 애니메이션 (opacity + blur 함께 0으로)
      modal.style.transition='transform .25s ease-out';
      modal.style.transform='translateY('+cardH+'px)';
      ov.style.transition='background .25s ease-out, backdrop-filter .25s ease-out, -webkit-backdrop-filter .25s ease-out';
      _ovSyncSwipe(ov, 0);
      setTimeout(function(){
        // closeModal 이 transform 감지하여 즉시 닫기 경로로 처리 → 스타일 초기화
        closeModal('histOv');
        _ovResetSwipe(ov);
      },260);
    } else {
      // 덜 내렸으면 → 원위치 스프링백 (blur/opacity도 원상 복귀)
      modal.style.transition='transform .22s ease-out';
      modal.style.transform='translateY(0)';
      ov.style.transition='background .22s ease-out, backdrop-filter .22s ease-out, -webkit-backdrop-filter .22s ease-out';
      _ovSyncSwipe(ov, 1);
      setTimeout(function(){modal.style.transition='';_ovResetSwipe(ov);},230);
    }
    swiping=false;
  }

  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',init);
  else init();
})();

// ── 배당 리포트 모달 스와이프 다운 닫기 ──
(function(){
  var ov,modal,handle,startY,deltaY,swiping,cardH;
  var BASE_OP=0.42, DISMISS_TH=120;

  function init(){
    ov=document.getElementById('divReportOv');
    modal=document.getElementById('divReportModal');
    handle=document.getElementById('divReportHandle');
    if(!modal||!handle)return;
    // 핸들바에서만 스와이프 리스너 등록 (preview 영역 스크롤을 방해하지 않음)
    handle.addEventListener('touchstart',onStart,{passive:true});
    handle.addEventListener('touchmove',onMove,{passive:false});
    handle.addEventListener('touchend',onEnd,{passive:true});
    handle.addEventListener('touchcancel',onEnd,{passive:true});
  }

  function onStart(e){
    startY=e.touches[0].clientY;
    deltaY=0;
    swiping=false;
    cardH=modal.offsetHeight;
    modal.style.transition='none';
  }

  function onMove(e){
    var curY=e.touches[0].clientY;
    deltaY=curY-startY;
    if(deltaY>0){
      swiping=true;
      e.preventDefault();
      modal.style.transform='translateY('+deltaY+'px)';
      var ratio=Math.max(0,1-deltaY/(cardH*0.5));
      _ovSyncSwipe(ov, ratio);
    } else {
      swiping=false;
    }
  }

  function onEnd(){
    if(!swiping){modal.style.transform='';modal.style.transition='';return;}
    if(deltaY>DISMISS_TH){
      modal.style.transition='transform .25s ease-out';
      modal.style.transform='translateY('+cardH+'px)';
      ov.style.transition='background .25s ease-out, backdrop-filter .25s ease-out, -webkit-backdrop-filter .25s ease-out';
      _ovSyncSwipe(ov, 0);
      setTimeout(function(){
        ov.dataset.swipeClosed='1';
        closeModal('divReportOv');
        modal.style.transform='';
        modal.style.transition='';
        _ovResetSwipe(ov);
      },260);
    } else {
      modal.style.transition='transform .22s ease-out';
      modal.style.transform='translateY(0)';
      ov.style.transition='background .22s ease-out, backdrop-filter .22s ease-out, -webkit-backdrop-filter .22s ease-out';
      _ovSyncSwipe(ov, 1);
      setTimeout(function(){modal.style.transition='';_ovResetSwipe(ov);},230);
    }
    swiping=false;
  }

  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',init);
  else init();
})();

// ── 종목 추가 모달 스와이프 다운 닫기 ──
(function(){
  var ov,modal,handle,startY,startScroll,deltaY,swiping,cardH,fromHandle;
  var BASE_OP=0.42, DISMISS_TH=110;

  function init(){
    ov=document.getElementById('addOv');
    modal=document.getElementById('addOvModal');
    handle=document.getElementById('addHandle');
    if(!modal)return;
    modal.addEventListener('touchstart',onStart,{passive:true});
    modal.addEventListener('touchmove',onMove,{passive:false});
    modal.addEventListener('touchend',onEnd,{passive:true});
    modal.addEventListener('touchcancel',onEnd,{passive:true});
  }

  function onStart(e){
    startScroll=modal.scrollTop;
    startY=e.touches[0].clientY;
    deltaY=0;
    swiping=false;
    cardH=modal.offsetHeight;
    // 핸들바에서 시작한 터치면 스크롤 위치와 무관하게 스와이프
    fromHandle=!!(handle && (e.target===handle || handle.contains(e.target)));
    modal.style.transition='none';
  }

  function onMove(e){
    var curY=e.touches[0].clientY;
    deltaY=curY-startY;
    // 핸들에서 시작했거나, 스크롤이 맨 위 + 아래로 당기는 중이면 스와이프 모드
    if((fromHandle || startScroll<=0) && deltaY>0){
      swiping=true;
      // 핸들에서 시작한 경우 입력 포커스 해제 (키보드 닫기)
      if(fromHandle && document.activeElement && document.activeElement.blur){
        document.activeElement.blur();
      }
      e.preventDefault();
      modal.style.transform='translateY('+deltaY+'px)';
      var ratio=Math.max(0,1-deltaY/(cardH*0.5));
      _ovSyncSwipe(ov, ratio);
    } else {
      swiping=false;
    }
  }

  function onEnd(){
    if(!swiping){modal.style.transform='';modal.style.transition='';return;}
    if(deltaY>DISMISS_TH){
      modal.style.transition='transform .25s ease-out';
      modal.style.transform='translateY('+cardH+'px)';
      ov.style.transition='background .25s ease-out, backdrop-filter .25s ease-out, -webkit-backdrop-filter .25s ease-out';
      _ovSyncSwipe(ov, 0);
      setTimeout(function(){
        closeModal('addOv');
        modal.style.transition='';
        _ovResetSwipe(ov);
      },260);
    } else {
      modal.style.transition='transform .22s ease-out';
      modal.style.transform='translateY(0)';
      ov.style.transition='background .22s ease-out, backdrop-filter .22s ease-out, -webkit-backdrop-filter .22s ease-out';
      _ovSyncSwipe(ov, 1);
      setTimeout(function(){modal.style.transition='';_ovResetSwipe(ov);},230);
    }
    swiping=false;
  }

  if(document.readyState==='loading') document.addEventListener('DOMContentLoaded',init);
  else init();
})();

