function setAcctType(type){
  document.getElementById('aAcct').value=type;
  var help=document.getElementById('acctHelp');
  var chips={
    general:{el:document.getElementById('acctGeneral'), help:'일반 과세 (배당 15.4%)'},
    isa:    {el:document.getElementById('acctIsa'),     help:'ISA — 200만 초과분 9.9% (비과세 한도 내 0%)'},
    irp:    {el:document.getElementById('acctIrp'),     help:'IRP — 연금 수령 시 5.5% (과세이연 효과)'},
    pension:{el:document.getElementById('acctPension'), help:'연금저축 — 연금 수령 시 5.5% (세액공제 16.5%)'}
  };
  Object.keys(chips).forEach(function(k){
    var c=chips[k].el; if(!c)return;
    c.classList.remove('on','tax-on');
    if(k===type){
      c.classList.add('on');
      if(k!=='general')c.classList.add('tax-on');
    }
  });
  if(help&&chips[type])help.textContent=chips[type].help;
}

