function setManualPrice(id){
  const inp=document.getElementById('manualPriceInput_'+id);
  if(!inp)return;
  const p=Math.round(parseFloat(inp.value));
  if(!p||p<=0){inp.style.border='1.5px solid #dc2626';return;}
  D.h=D.h.map(x=>x.id===id?{...x,cur:p,err:0}:x);
  D.at=new Date().toLocaleTimeString('ko-KR',{hour:'2-digit',minute:'2-digit'});
  save();render();
  openBuyHistory(id);
}

function toggleMenu(trigger){
  const d=document.getElementById('menuDrop');
  if(!d)return;
  // 호출한 버튼 위치 기반: trigger → event.currentTarget → menuBtn (히어로) → menuBtnMini (미니바)
  let btn = trigger;
  if(!btn && typeof event !== 'undefined' && event && event.currentTarget) btn = event.currentTarget;
  if(!btn) btn = document.getElementById('menuBtn');
  if(!btn) btn = document.getElementById('menuBtnMini');
  if(!btn)return;
  if(d.parentElement !== document.body) document.body.appendChild(d);
  const isOpen = d.style.display!=='none' && d.style.display!=='';
  if(isOpen){ d.style.display='none'; return; }
  // 유저 헤더: 로그인된 경우만 표시
  const userHdr = document.getElementById('menuUserHdr');
  if(userHdr){
    if(_sess && _nick){
      userHdr.style.display='flex';
      const av=document.getElementById('menuUserAv');
      const nm=document.getElementById('menuUserNm');
      if(av) av.textContent=_nick.charAt(0).toUpperCase();
      if(nm) nm.textContent=_nick;
    } else {
      userHdr.style.display='none';
    }
  }
  // 버튼 위치 기반 배치
  const r = btn.getBoundingClientRect();
  d.style.position='fixed';
  d.style.top = (r.bottom + 8) + 'px';
  d.style.right = (window.innerWidth - r.right) + 'px';
  d.style.left = 'auto';
  d.style.display='block';
}
