/* ===== 테마 스위처 ===== */
function setTheme(t){
  var allowed = ['default','warm','cool','luxe'];
  if(allowed.indexOf(t) < 0) return;
  if(t === 'default'){
    document.documentElement.removeAttribute('data-theme');
  } else {
    document.documentElement.setAttribute('data-theme', t);
  }
  try{ localStorage.setItem('divd_theme', t); }catch(e){}
  _syncThemeBtns();
}
function _syncThemeBtns(){
  var cur = document.documentElement.getAttribute('data-theme') || 'default';
  var btns = document.querySelectorAll('[data-theme-btn]');
  for(var i=0;i<btns.length;i++){
    var btn = btns[i];
    var isOn = btn.getAttribute('data-theme-btn') === cur;
    btn.style.borderColor = isOn ? 'var(--brand-primary)' : 'var(--c-border)';
    btn.style.background = isOn ? 'var(--acct-general-soft)' : '#fff';
    btn.style.borderWidth = isOn ? '2px' : '1.5px';
  }
}
// 초기 동기화 (DOM 준비 후)
if(document.readyState === 'loading'){
  document.addEventListener('DOMContentLoaded', function(){ try{_syncThemeBtns();}catch(e){} });
} else {
  try{_syncThemeBtns();}catch(e){}
}

