// ── 탭 커스텀 스무스 스크롤 (RAF + easeInOutCubic) ──
// PC(overflow-x:clip)에서는 scrollLeft가 무시되므로 transform 폴백 사용
function _smoothScrollTab(el, target, duration){
  if(!el) return;
  var w=el.offsetWidth;
  if(!w) return;
  var idx=Math.round(target/w);
  var cs=getComputedStyle(el);
  var ox=cs.overflowX;
  // clip 또는 hidden이면 scrollLeft가 동작 안함 → transform 폴백
  if(ox==='clip'||ox==='hidden'){
    var panes=el.querySelectorAll(':scope > .pane');
    panes.forEach(function(p){
      p.style.transition='transform '+duration+'ms cubic-bezier(0.4,0,0.2,1)';
      p.style.transform='translateX('+(-idx*100)+'%)';
    });
    // 애니메이션 완료 후 transition 제거 (향후 즉시 변경 허용)
    setTimeout(function(){
      panes.forEach(function(p){p.style.transition='';});
    },duration+50);
    return;
  }
  // 모바일(scroll): 기존 scrollLeft 애니메이션
  var start=el.scrollLeft;
  var change=target-start;
  if(Math.abs(change)<2)return;
  // 애니메이션 중 scroll-snap 비활성 → 중간 강제 스냅 방지
  el.style.scrollSnapType='none';
  var startTime=null;
  function ease(t){return t<0.5?4*t*t*t:1-Math.pow(-2*t+2,3)/2;}
  function step(now){
    if(!startTime)startTime=now;
    var elapsed=now-startTime;
    var progress=Math.min(elapsed/duration,1);
    el.scrollLeft=start+change*ease(progress);
    if(progress<1){
      requestAnimationFrame(step);
    } else {
      // 완료 후 snap 복원
      el.style.scrollSnapType='x mandatory';
    }
  }
  requestAnimationFrame(step);
}

// 터치 중 플래그 (모바일 스와이프는 네이티브에 맡김)
