let _lottieRocket = null; // 로켓 인스턴스 (재생성 방지)
let _lottieConfeti = null, _lottieCelebration = null, _lottieStars = null;

// ── 내장 종목 DB (KRX 공식 데이터 기반) ──
// STOCK_DB는 상단에 선언됨 (2190개: 보통주 + ETF + ETN)
// 미국 + 한국 전체 DB
function getAllDB(){ return STOCK_DB.concat(US_STOCK_DB); }
async function initKrxDB(){
  const el=document.getElementById('dbStatus');if(el)el.textContent='';
}

/* ===== SEARCH — Yahoo Finance 실시간 (단일 소스) ===== */
let _ddTimer=null;

function _normSearchText(s){
  return String(s||'').toUpperCase().replace(/[\s\-_.·,()/\[\]{}]/g,'');
}
function _aliasList(x){
  const name=String(x&&x.n||'');
  const out=[name, String(x&&x.c||'')];
  const family=(name.match(/(KODEX|TIGER|PLUS|ACE|SOL|RISE|KBSTAR|KOSEF|HANARO|ARIRANG|TIMEFOLIO|KoAct)[^\n]*/i)||[])[0];
  if(family) out.push(family);
  let trimmed=name
    .replace(/^(삼성|미래에셋자산운용|신한자산운용|한화자산운용|키움투자자산운용|KB자산운용|NH-아문디자산운용|한국투자신탁운용)\s+/,'')
    .replace(/\[.*?\]/g,'')
    .replace(/ETF$/i,'')
    .replace(/증권상장지수투자신탁.*$/,'')
    .replace(/상장지수투자신탁.*$/,'')
    .trim();
  if(trimmed) out.push(trimmed);
  if(trimmed && !/ETF$/i.test(trimmed)) out.push(trimmed+'ETF');
  return Array.from(new Set(out.filter(Boolean)));
}
function _localSearch(db,q){
  const nq=_normSearchText(q);
  const scored=[];
  db.forEach(function(x){
    const aliases=_aliasList(x);
    let best=0;
    for(const a of aliases){
      const na=_normSearchText(a);
      if(!na) continue;
      if(na===nq){ best=Math.max(best,300); continue; }
      if(na.startsWith(nq)){ best=Math.max(best,200); continue; }
      if(na.includes(nq)){ best=Math.max(best,100); continue; }
    }
    if(best>0) scored.push({x,score:best});
  });
  scored.sort(function(a,b){
    if(b.score!==a.score) return b.score-a.score;
    return String(a.x.n||'').length-String(b.x.n||'').length;
  });
  return scored.map(v=>v.x).slice(0,20);
}

function doSearchDD(q){
  const dd=document.getElementById('searchDD');
  q=q.trim();
  if(!q){dd.style.display='none';return;}
  if(_ddTimer)clearTimeout(_ddTimer);

  // 1) 로컬 결과 즉시 표시 (instant feedback)
  let localItems = [];
  if(STOCK_DB.length > 0 || US_DB.length > 0){
    const db=getAllDB();
    const local = _localSearch(db,q);
    if(local.length > 0){
      localItems = local.map(x=>{
        let sym, mkt;
        if(x.m==='KQ'){ sym=x.c+'.KQ'; mkt='KOSDAQ'; }
        else if(x.m==='KS'||/^[0-9][0-9A-Z]{5}$/.test(x.c)){ sym=x.c+'.KS'; mkt='KOSPI'; }
        else { sym=x.c; mkt=x.t==='etf'?'ETF':'US'; }
        const div=guessEtfDiv(x.n);
        return{n:x.n, s:sym, dy:div.dy||0, df:div.df||'없음', isDv:div.isDv||false, market:mkt};
      });
      showDD(dd, localItems, q);
    }
  }

  // 2) 항상 Yahoo + 네이버도 병렬 호출해서 결과 병합 (로컬엔 없는 신규 종목 포함되게)
  if(!localItems.length){
    dd.innerHTML='<div style="padding:10px 14px;color:#aaa;font-size:12px">🔍 검색 중...</div>';
    dd.style.display='block';
  }
  _ddTimer=setTimeout(()=>_doYahooSearch(q,dd,localItems),300);
}

async function _doYahooSearch(q,dd,localItems){
  localItems = localItems || [];
  // 한글 포함이면 네이버 우선 + Yahoo 병합. 영문만이면 Yahoo 우선
  const isKorean = /[가-힣]/.test(q);
  const _stripTags = s => String(s||'').replace(/<\/?[a-z][^>]*>/gi,'').replace(/&amp;/g,'&').trim();

  const yahooP = (async()=>{
    try{
      const ctrl=new AbortController();
      const t=setTimeout(()=>ctrl.abort(),5000);
      const res=await fetch(`${SERVER_URL}/price.php?search=${encodeURIComponent(q)}`,{signal:ctrl.signal});
      clearTimeout(t);
      if(!res.ok)return[];
      const j=await res.json();
      return (j?.quotes||[]).map(x=>{
        const sym=x.symbol;
        const name=x.shortname||x.longname||sym;
        const mkt=sym.endsWith('.KS')?'KOSPI':sym.endsWith('.KQ')?'KOSDAQ':x.exchDisp||'US';
        const div=guessEtfDiv(name);
        return{n:name,s:sym,dy:div.dy||0,df:div.df||'없음',isDv:div.isDv||false,market:mkt};
      });
    }catch(e){return[];}
  })();

  const naverP = (async()=>{
    try{
      const data = await naverACJsonp(q, 20);
      const items = acItems(data) || [];
      const out = [];
      items.forEach((group, gi)=>{
        if(!Array.isArray(group)) return;
        group.forEach(item=>{
          if(!Array.isArray(item) || item.length < 2) return;
          let rawName = Array.isArray(item[0]) ? item[0][0] : item[0];
          let code = Array.isArray(item[1]) ? item[1][0] : item[1];
          if(!rawName || !code) return;
          const name = _stripTags(rawName);
          code = _stripTags(code);
          if(!/^[0-9][0-9A-Z]{5}$/.test(String(code))) return;
          const market = gi===0 ? 'KOSPI' : 'KOSDAQ';
          const ext = gi===0 ? '.KS' : '.KQ';
          const div = guessEtfDiv(name);
          out.push({n:name, s:code+ext, dy:div.dy||0, df:div.df||'없음', isDv:div.isDv||false, market:market});
        });
      });
      return out;
    }catch(e){return[];}
  })();

  try{
    const [yahooItems, naverItems] = await Promise.all([yahooP, naverP]);
    // 3개 소스 병합 (로컬 + 네이버 + 야후). 한글 검색이면 네이버 > 로컬 > 야후 순, 아니면 로컬 > 야후 > 네이버
    const seen = new Set();
    const merged = [];
    const addList = arr => arr.forEach(it=>{
      if(!it.s) return;
      // 중복 체크 (.KS/.KQ 제외한 코드 기준)
      const key = String(it.s).replace(/\.(KS|KQ)$/i,'').toUpperCase();
      if(seen.has(key)) return;
      seen.add(key);
      merged.push(it);
    });
    if(isKorean){ addList(naverItems); addList(localItems); addList(yahooItems); }
    else       { addList(localItems); addList(yahooItems); addList(naverItems); }

    if(!merged.length){
      dd.innerHTML='<div style="padding:10px 14px;color:#aaa;font-size:12px">검색 결과 없음</div>';
      return;
    }
    showDD(dd, merged, q);
  }catch(e){
    // 실패 시 로컬 결과라도 유지
    if(localItems.length > 0){
      showDD(dd, localItems, q);
    } else {
      dd.innerHTML='<div style="padding:10px 14px;color:#f87171;font-size:12px">검색 실패 — 잠시 후 다시 시도해주세요</div>';
    }
  }
}

async function _doYahooSearchProxy(q,dd){
  const url=`https://query2.finance.yahoo.com/v1/finance/search?q=${encodeURIComponent(q)}&lang=ko-KR&region=KR&quotesCount=15&newsCount=0`;
  for(const mkP of PROXIES){
    try{
      const ctrl=new AbortController();
      const t=setTimeout(()=>ctrl.abort(),3000);
      const r=await fetch(mkP(url),{signal:ctrl.signal});
      clearTimeout(t);
      if(!r.ok)continue;
      const text=await r.text();
      const j=JSON.parse(text.startsWith('{"contents"')?JSON.parse(text).contents:text);
      const quotes=(j?.quotes||[]).filter(x=>x.symbol&&!x.symbol.includes('^'));
      if(!quotes.length)continue;
      const items=quotes.map(x=>{
        const sym=x.symbol;
        const name=x.shortname||x.longname||sym;
        const mkt=sym.endsWith('.KS')?'KOSPI':sym.endsWith('.KQ')?'KOSDAQ':x.exchDisp||'US';
        const div=guessEtfDiv(name);
        return{n:name,s:sym,dy:div.dy||0,df:div.df||'없음',isDv:div.isDv||false,market:mkt};
      });
      if(items.length){showDD(dd,items,q);return;}
    }catch{}
  }
  dd.innerHTML='<div style="padding:10px 14px;color:#f87171;font-size:12px">검색 실패 — 코드를 직접 입력해주세요</div>';
}

function showDD(dd,items,q){
  _ddIdx=-1;
  if(!items.length){dd.style.display='none';return;}
  const esc=q.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
  dd.innerHTML=items.map(x=>{
    const hl=x.n.replace(new RegExp('('+esc+')','gi'),'<b style="color:var(--brand-primary)">$1</b>');
    const mkt=x.market?'<span style="font-size:10px;background:#f3f3f1;color:#888;padding:1px 5px;border-radius:4px;margin-left:4px">'+x.market+'</span>':'';
    const code=x.s.replace(/\.(KS|KQ)$/,'');
    const dy2=x.isDv&&x.dy>0?' · '+x.dy+'% · '+x.df:'';
    const n2=x.n.replace(/\\/g,'\\\\').replace(/'/g,"\\'");
    return'<div onclick="pickSearch(\''+n2+'\',\''+x.s+'\','+x.dy+',\''+x.df+'\','+(x.isDv?1:0)+')" style="padding:10px 14px;cursor:pointer;border-bottom:1px solid #f3f3f1">'
      +'<div style="font-size:13px;font-weight:600">'+hl+mkt+'</div>'
      +'<div style="font-size:11px;color:#aaa;margin-top:1px">'+code+dy2+'</div>'
      +'</div>';
  }).join('');
  dd.style.display='block';
}

function pickSearch(n,s,dy,df,isDv){
  document.getElementById('aName').value=n;
  document.getElementById('aDy').value=dy||0;
  document.getElementById('aDf').value=df&&df!=='없음'?df:'없음';
  document.getElementById('searchDD').style.display='none';
  if(_ddTimer)clearTimeout(_ddTimer);

  // 선택된 심볼을 hidden input에 저장
  window._pickedSym = s || '';



  updateAvgCurrency(n);
  const chip=document.getElementById('aDivChip');
  if(isDv&&dy>0){
    chip.style.display='block';
    chip.style.background='';chip.style.color='';
    chip.textContent='📊 배당 자동 설정: 연 '+dy+'% · '+df;
  }else{
    chip.style.display='block';
    chip.style.background='#f9f8f5';
    chip.style.color='#aaa';
    chip.textContent='📊 배당 없음 (또는 미등록)';
  }
}

function closeDD(){document.getElementById('searchDD').style.display='none'; window._ddIdx=-1;}

/* ===== 검색 방향키 탐색 ===== */
var _ddIdx = -1;
function handleSearchKey(e){
  const dd = document.getElementById('searchDD');
  const items = dd.querySelectorAll('div[onclick]');
  if(e.key==='Escape'){closeDD();return;}
  if(e.key==='ArrowDown'){
    e.preventDefault();
    if(dd.style.display==='none'||!items.length)return;
    _ddIdx=Math.min(_ddIdx+1,items.length-1);
    _updateDDHighlight(items);
    return;
  }
  if(e.key==='ArrowUp'){
    e.preventDefault();
    if(dd.style.display==='none'||!items.length)return;
    _ddIdx=Math.max(_ddIdx-1,-1);
    _updateDDHighlight(items);
    return;
  }
  if(e.key==='Enter'){
    e.preventDefault();
    if(dd.style.display!=='none' && _ddIdx>=0 && items[_ddIdx]){
      items[_ddIdx].click();
      return;
    }
    // 검색창 닫고 다음 필드로
    closeDD();
    const aAvg=document.getElementById('aAvg');
    if(aAvg && document.getElementById('aName').value.trim()) aAvg.focus();
    return;
  }
  _ddIdx=-1;
}
function _updateDDHighlight(items){
  items.forEach(function(el,i){
    el.style.background = i===_ddIdx ? '#eff6ff' : '';
    el.style.color = i===_ddIdx ? '#1d4ed8' : '';
    if(i===_ddIdx) el.scrollIntoView({block:'nearest'});
  });
}

/* ===== 오버레이 드래그 닫힘 방지 ===== */
var _mousedownInsideModal = false;
document.addEventListener('mousedown', function(e){
  _mousedownInsideModal = !!e.target.closest('.modal');
  // 검색 입력창과 드롭다운 자체 클릭 외엔 항상 드롭다운 닫기
  if(e.target.id !== 'aName' && !e.target.closest('#searchDD')){
    closeDD();
  }
});
// 오버레이 클릭 시 드래그 출처 확인 후 닫기
document.querySelectorAll('.ov').forEach(function(ov){
  ov.addEventListener('click', function(e){
    if(e.target===ov && !_mousedownInsideModal){
      closeModal(ov.id);
    }
  });
  // 스크린샷 모달 특수처리
  if(ov.id==='ssOv'){
    ov.addEventListener('click', function(e){
      if(e.target===ov && !_mousedownInsideModal) closeSsModal();
    });
  }
});


// 보유 종목 배당 정보 + 심볼 + 수량 일관성 자동 갱신
(function syncDivInfo(){
  let changed=false;

  // 보유 종목명 정리 (브랜드명 + 법정 접미사 제거)
  function _cleanEtfName(n){
    if(!n) return n;
    n = n.replace(/^(삼성액티브|삼성|미래에셋TIGER|미래에셋|한화PLUS|한화|신한|KB|NH-Amundi|NH|키움|한국투자|한국밸류|교보악사|BNK BNK|BNK|DB|IBK|타임폴리오|트러스톤|하나|우리|대신|에셋플러스|브이아이|케이씨지아이|마이다스|현대|흥국|더제이|iM에셋|유리)\s+/, '');
    // 법정 접미사 제거 — 원본 완전명 + slice(0,30)으로 잘린 꼬리까지 커버
    n = n.replace(/\s*증권상장지수.*$/, '');   // "증권상장지수투자신탁..." / "증권상장지수투자신" (잘림)
    n = n.replace(/\s*상장지수투자.*$/, '');   // "상장지수투자신탁..."  / "상장지수투자신" (잘림)
    n = n.replace(/\s*상장지수증권.*$/, '');   // "상장지수증권 제X호..."
    n = n.replace(/\s*투자신탁[\[\(].*$/, ''); // "...투자신탁[주식]" / "...투자신탁(주식-재간접형)"
    n = n.replace(/[\[\(]\s*$/, '').trim();
    return n;
  }

  D.h.forEach(h=>{
    // 종목명 정리
    if(h.n){
      const cleaned = _cleanEtfName(h.n);
      if(cleaned !== h.n){ h.n = cleaned; changed = true; }
    }

    // 🩹 h.n이 코드 형식으로 저장된 경우 STOCK_DB에서 정규 이름 자동 복구
    // (예: h.n="441640" → "KODEX 미국배당커버드콜S&P액티브")
    if(h.n && (/^[0-9][0-9A-Z]{5}(\.(KS|KQ))?$/i.test(h.n) || /^[A-Z]{1,6}$/.test(h.n))){
      try{
        var _codeToFind = h.n.replace(/\.(KS|KQ)$/i,'');
        var _dbMatch = getAllDB().find(function(x){return x.c === _codeToFind;});
        if(_dbMatch && _dbMatch.n && _dbMatch.n !== h.n){
          h.n = _dbMatch.n;
          changed = true;
        }
      }catch(e){}
    }

    // ═══ 세율 마이그레이션: auto 모드인데 옛 세율(8/10/12)로 저장된 경우 새 법정세율로 ═══
    // (과거 버전이 커버드콜=10%, 국내상장 해외 ETF=12% 등으로 잘못 저장했던 것 교정)
    if((h.taxRateMode||'auto') === 'auto'){
      const _newInferred = _inferTaxRate(h).rate;
      if(h.taxRate != null && Math.abs(Number(h.taxRate) - _newInferred) > 0.01){
        h.taxRate = _newInferred;
        changed = true;
      }
    }

    // 수량 일관성: buys 합계 ≠ h.qty 이면 buys 기준으로 수정
    if(h.buys&&h.buys.length){
      const sumQty=h.buys.reduce((s,b)=>s+(b.qty||0),0);
      if(sumQty>0&&sumQty!==h.qty){h.qty=sumQty;changed=true;}
    }

    // A+숫자 형식 sym 자동 교정 (예: A482730.KS → 482730.KS)
    if(h.sym&&/^A\d{6}\.(KS|KQ)$/.test(h.sym)){
      h.sym=h.sym.slice(1); changed=true;
    }

    // 잘못된 sym 교정 (공백 포함 = 종목명이 sym에 들어간 경우)
    if(h.sym&&h.sym.includes(' ')){
      h.sym=''; changed=true;
    }

    // 알려진 잘못된 코드 교정
    const symFixes={'494960.KS':'0049M0.KS'};
    if(h.sym&&symFixes[h.sym]){h.sym=symFixes[h.sym];changed=true;}

    // 종목명 기반 sym 교정 (알파뉴메릭 코드 ETF - Yahoo에 없어서 sym이 비거나 잘못 설정됨)
    var _nameSymMap=[
      {match:'테슬라위클리커버드콜', sym:'0132K0.KS'}
    ];
    _nameSymMap.forEach(function(entry){
      if((!h.sym||h.sym.includes(' '))&&h.n&&h.n.includes(entry.match)){
        h.sym=entry.sym; changed=true;
      }
    });

    // 한국 ETF인데 sym이 공백 포함/이름형/빈값이면 → 이름을 DB에서 찾아 코드 교정
    // (스크린샷 OCR로 추가했을 때 sym이 잘못 들어간 경우 자동 복구)
    if(h.n && /[가-힣]/.test(h.n)){
      var _symBad = !h.sym || h.sym.includes(' ') || !/^[0-9A-Z]+\.(KS|KQ)$/i.test(h.sym);
      if(_symBad){
        // 1단계: 로컬 DB 즉시 매칭 시도
        var _db;
        try{ _db = getAllDB().find(function(x){return x.n === h.n;}); }catch(e){}
        if(_db && _db.c && /^[0-9][0-9A-Z]{5}$/.test(_db.c)){
          h.sym = _db.c + (_db.m==='KQ'?'.KQ':'.KS');
          h.divHistory = undefined;
          changed = true;
        } else {
          // 2단계: DB 매칭 실패 시 서버 검색 API로 비동기 해결
          // sym을 임시 placeholder로 두고 바로 background 조회
          h._symPending = true; // flag (다중 호출 방지)
          changed = true;
          (function(hold){
            var qName = hold.n.replace(/\s*(증권상장지수.*|투자신탁.*|\(.*?\))/g,'').trim();
            // 네이버 자동완성(JSONP)으로 한국 종목 검색 → 가장 정확한 단일 매칭
            // "TIGER 미국S&P500타겟데일리커버드콜" → 482730 (전 세계 유일 종목)
            // HTML 태그 제거 헬퍼 (네이버 AC는 <b>하이라이트</b> 태그를 반환함)
            function _stripTags(s){return String(s||'').replace(/<\/?[a-z][^>]*>/gi,'').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').trim();}
            setTimeout(function(){
              naverACJsonp(qName, 20).then(function(data){
                var items = acItems(data) || [];
                var allResults = [];
                items.forEach(function(group, gi){
                  if(!Array.isArray(group)) return;
                  group.forEach(function(item){
                    if(!Array.isArray(item) || item.length < 2) return;
                    var rawName = Array.isArray(item[0]) ? item[0][0] : item[0];
                    var code = Array.isArray(item[1]) ? item[1][0] : item[1];
                    if(!rawName || !code) return;
                    var name = _stripTags(rawName);
                    code = _stripTags(code);
                    if(!/^[0-9][0-9A-Z]{5}$/.test(String(code))) return;
                    var market = gi===0 ? 'KS' : (gi===1 ? 'KQ' : 'KS');
                    allResults.push({name:name, code:code, market:market});
                  });
                });
                if(!allResults.length){
                  console.warn('[sym auto-repair] 네이버 검색 결과 없음:', hold.n);
                  var t0 = D.h.find(function(x){return x.id === hold.id;});
                  if(t0) delete t0._symPending;
                  return;
                }
                console.log('[sym auto-repair] 네이버 검색 결과:', allResults.length, '개', allResults);
                var origNorm = hold.n.replace(/\s/g,'').toLowerCase();
                var best = null, bestScore = 0;
                allResults.forEach(function(r){
                  var nm = r.name.replace(/\s/g,'').toLowerCase();
                  var score = 0;
                  if(nm === origNorm) score = 10;
                  else if(nm.startsWith(origNorm) || origNorm.startsWith(nm)){
                    var shorter = Math.min(nm.length, origNorm.length);
                    var longer = Math.max(nm.length, origNorm.length);
                    score = 5 * (shorter/longer);
                  } else if(nm.indexOf(origNorm.slice(0,8)) !== -1){
                    score = 2;
                  }
                  if(score > bestScore){bestScore = score; best = r;}
                });
                if(!best || bestScore < 1){
                  console.warn('[sym auto-repair] 적합한 매칭 없음:', hold.n, 'candidates:', allResults);
                  var t1 = D.h.find(function(x){return x.id === hold.id;});
                  if(t1) delete t1._symPending;
                  return;
                }
                var newSym = best.code + '.' + best.market;
                var target = D.h.find(function(x){return x.id === hold.id;});
                if(target){
                  console.log('[sym auto-repair] ✅', hold.n, '→', newSym, '(매칭:', best.name, ')');
                  target.sym = newSym;
                  target.divHistory = undefined;
                  target.err = 0;
                  delete target._symPending;
                  save();
                  if(typeof fetchOne === 'function') fetchOne(target.id).catch(function(){});
                  setTimeout(function(){
                    if(typeof fetchDivs === 'function') fetchDivs(target.id).catch(function(){});
                  }, 800);
                }
              }).catch(function(err){
                console.warn('[sym auto-repair] 네이버 검색 실패:', hold.n, err);
                var t2 = D.h.find(function(x){return x.id === hold.id;});
                if(t2) delete t2._symPending;
              });
            }, 500);
          })(h);
        }
      }
    }

    // divHistory 있으면 완전히 넘어감
    if(h.isDv&&h.dy>0&&h.df&&h.df!=='없음'&&Array.isArray(h.divHistory)&&h.divHistory.length>0)return;
    const g=guessEtfDiv(h.n);
    if(g.isDv){
      // df는 이미 설정된 값 유지, dy는 guessEtfDiv 추정값으로 갱신 (divHistory 없을 때 폴백 정확도 향상)
      const keepDf=(h.df&&h.df!=='없음')?h.df:g.df;
      if(h.dy!==g.dy||!h.isDv){h.dy=g.dy;h.df=keepDf;h.isDv=g.isDv;changed=true;}
    }
  });
  if(changed)save();
})();

