// 보유 종목 심볼 백그라운드 자동 검증/탐색
(async function prefetchSymbols(){
  // 1) 심볼 없는 국내 종목
  // 2) 시세 조회 실패한 국내 종목 (심볼이 틀렸을 가능성)
  const targets=D.h.filter(h=>
    isKRName(h.n)&&(!h.sym||(h.err&&h.sym))
  );
  if(!targets.length)return;
  let changed=false;
  for(const h of targets){
    try{
      const sym=await findKRSymbol(h.n);
      if(sym&&sym!==h.sym){
        D.h=D.h.map(x=>x.id===h.id?{...x,sym,err:0}:x);
        changed=true;
      }
    }catch{}
    await new Promise(r=>setTimeout(r,300));
  }
  if(changed){save();render();}
})();

/* ===== SCREENSHOT OCR (OCR.space 무료 API) ===== */
let SS_FILES=[], SS_PARSED=[];

function openSsImport(){
  SS_FILES=[]; SS_PARSED=[];
  document.getElementById('ssDropZone').style.display='block';
  document.getElementById('ssPreviewRow').style.display='none';
  document.getElementById('ssPreviewRow').innerHTML='';
  document.getElementById('ssStatus').style.display='none';
  document.getElementById('ssResult').style.display='none';
  document.getElementById('ssAnalyzeBtn').style.display='none';
  document.getElementById('ssImportBtn').style.display='none';
  openModal('ssOv');
  document.getElementById('ssFileInput').onchange=function(e){
    const files=Array.from(e.target.files||[]).slice(0,5);
    if(!files.length)return;
    SS_FILES=files;
    const row=document.getElementById('ssPreviewRow');
    row.innerHTML=files.map(f=>`<img src="${URL.createObjectURL(f)}" style="height:80px;border-radius:8px;object-fit:cover;flex:1;min-width:0">`).join('');
    row.style.display='flex';
    document.getElementById('ssDropZone').style.display=files.length<5?'block':'none';
    document.getElementById('ssDropZone').innerHTML=`<div style="font-size:13px;color:var(--brand-primary);font-weight:600">+ 추가 선택 (${files.length}/5)</div>`;
    document.getElementById('ssAnalyzeBtn').style.display='block';
    document.getElementById('ssResult').style.display='none';
    document.getElementById('ssImportBtn').style.display='none';
    e.target.value='';
  };
}

function closeSsModal(){
  closeModal('ssOv');
}

async function ocrFile(file, idx, total, stxt, bar){
  const dataUrl = await new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => {
      let w=img.width, h=img.height;
      const MAX=1500;
      if(w>MAX){h=Math.round(h*MAX/w);w=MAX;}
      if(h>MAX){w=Math.round(w*MAX/h);h=MAX;}
      const c=document.createElement('canvas');
      c.width=w; c.height=h;
      c.getContext('2d').drawImage(img,0,0,w,h);
      resolve(c.toDataURL('image/jpeg',0.85));
    };
    img.onerror=reject;
    img.src=URL.createObjectURL(file);
  });
  stxt.textContent=`이미지 ${idx+1}/${total} OCR 전송 중...`;
  bar.style.width=Math.round((idx/total)*80+10)+'%';
  const fd=new FormData();
  fd.append('base64Image',dataUrl);
  fd.append('language','kor');
  fd.append('isOverlayRequired','false');
  fd.append('OCREngine','2');
  fd.append('scale','true');
  fd.append('apikey','helloworld');
  const resp=await fetch('https://api.ocr.space/parse/image',{method:'POST',body:fd});
  if(!resp.ok)throw new Error('서버 오류 '+resp.status);
  const data=await resp.json();
  if(data.IsErroredOnProcessing)throw new Error(data.ErrorMessage?.[0]||'OCR 실패');
  return (data.ParsedResults||[]).map(r=>r.ParsedText||'').join('\n');
}

async function runSsAnalyze(){
  if(!SS_FILES.length){alert('이미지를 먼저 선택하세요');return;}
  const st=document.getElementById('ssStatus');
  const stxt=document.getElementById('ssStatusTxt');
  const bar=document.getElementById('ssProgressBar');
  const btn=document.getElementById('ssAnalyzeBtn');
  const res=document.getElementById('ssResult');
  const imp=document.getElementById('ssImportBtn');

  st.style.display='block';
  stxt.textContent='분석 시작...';
  bar.style.width='0%';
  btn.style.display='none';
  res.style.display='none';
  imp.style.display='none';

  try{
    const allTexts=[];
    const ocrPromises=[];
    for(let i=0;i<SS_FILES.length;i++){
      ocrPromises.push(ocrFile(SS_FILES[i],i,SS_FILES.length,stxt,bar));
    }
    Promise.all(ocrPromises).then(function(results){
      results.forEach(function(text){if(text&&text.trim())allTexts.push(text);});
      bar.style.width='100%';
      st.style.display='none';

    const combinedText=allTexts.join('\n---\n');
    if(!combinedText.trim()){
      res.innerHTML='<div style="background:#fff7ed;border-radius:10px;padding:12px;font-size:12px;color:var(--c-gold-600)">⚠️ 텍스트를 인식하지 못했습니다</div>';
      res.style.display='block';
      btn.style.display='block'; btn.textContent='🔄 재시도';
      return;
    }

    // 각 이미지별 파싱 후 합산
    SS_PARSED=[];
    const seen=new Set();
    allTexts.forEach(t=>{
      parseSsText(t).forEach(x=>{
        const k=x.name+'|'+x.qty+'|'+x.avgPrice+'|'+x.acct;
        if(!seen.has(k)){seen.add(k);SS_PARSED.push(x);}
      });
    });

    const rawBox=`<details style="margin-top:8px"><summary style="font-size:11px;color:#aaa;cursor:pointer">📄 OCR 원본 텍스트</summary><pre style="font-size:10px;color:#666;background:#f9f8f5;padding:8px;border-radius:8px;overflow-x:auto;white-space:pre-wrap;word-break:break-all">${combinedText.replace(/</g,'&lt;')}</pre></details>`;

    if(!SS_PARSED.length){
      res.innerHTML='<div style="background:#fff7ed;border-radius:10px;padding:12px;font-size:12px;color:var(--c-gold-600)">⚠️ 종목 패턴을 찾지 못했습니다</div>'+rawBox;
      res.style.display='block';
      btn.style.display='block'; btn.textContent='🔄 재시도';
      return;
    }
      renderSsParsed(rawBox);
    }).catch(function(e){
      st.style.display='none';
      res.innerHTML='<div style="background:var(--c-red-50);border-radius:10px;padding:12px;font-size:12px;color:var(--state-loss)">❌ '+(e.message||'오류')+'</div>';
      res.style.display='block';
      btn.style.display='block'; btn.textContent='🔄 재시도';
    });
  }catch(e){
    st.style.display='none';
    res.innerHTML='<div style="background:var(--c-red-50);border-radius:10px;padding:12px;font-size:12px;color:var(--state-loss)">❌ '+(e.message||'오류')+'</div>';
    res.style.display='block';
    btn.style.display='block'; btn.textContent='🔄 재시도';
  }
}

function parseSsText(text){
  const lines=text.split(/[\n\r]+/).map(l=>l.trim()).filter(Boolean);
  const N=s=>parseInt(String(s).replace(/[,\s]/g,'').replace(/[Ool]/g,c=>c==='O'||c==='o'?'0':'1'),10);
  const results=[];
  const seen=new Set();

  // genKw 먼저 — 대소문자 무시
  const genKw=['위탁','일반계좌','각시toss','toss'];
  const taxKw=['절세','각시ISA','ISA','IRP','연금저축','연금','개인형','개인종합','신연금','종합자산','퇴직연금','DC형','DB형','세금우대'];
  function acctOf(s){
    if(!s)return'general';
    const sl=s.toLowerCase();
    for(const k of taxKw)if(s.includes(k))return'tax';  // 절세 먼저 체크
    for(const k of genKw)if(sl.includes(k.toLowerCase()))return'general';
    return'general';
  }

  // 상단 종목명/티커 추출
  let topName='', topTicker='', topCode='';
  // 한국 종목코드 패턴: 숫자로 시작하는 6자리 영숫자 (005930, 0144L0, 47814L 등)
  const KRC='[0-9][0-9A-Z]{5}';
  const KRC_RE=new RegExp('^'+KRC+'$');
  const EXCLUDE=['USD','ETF','KRW','ISA','IRP','LTE','ATM','OTM','NAV'];
  const KR_ETF_BRANDS=/^(RISE|KODEX|TIGER|ACE|SOL|HANARO|TIMEFOLIO|KBSTAR|ARIRANG|PLUS|FOCUS|DAISHIN|KIWOOM|VITA|TRUSTON|KoAct|TREX|ITF|WON|TIME|UNICORN|KCGI|HK)\b/i;
  for(let i=0;i<Math.min(lines.length,15);i++){
    const l=lines[i];
    // ── 1순위: 한국 ETF 브랜드 (US 티커보다 먼저!) ──
    if(KR_ETF_BRANDS.test(l)){
      const etfCodeM=l.match(new RegExp('('+KRC+')'));
      if(etfCodeM)topCode=etfCodeM[1];
      topName=l.replace(new RegExp('\\s*'+KRC+'.*$'),'').trim();break;
    }
    // ── 2순위: 한국 종목코드 패턴 ──
    // "삼성전자 005930" 또는 "삼성전자 0144L0" (이름+코드 한 줄)
    const cm=l.match(new RegExp('^(.+?)\\s+('+KRC+')\\b'));
    if(cm){topName=cm[1].trim();topCode=cm[2];break;}
    // "삼성전자(005930)" 또는 "삼성전자(0144L0)"
    const cp=l.match(new RegExp('^(.+?)\\s*\\(?('+KRC+')\\)?'));
    if(cp&&/[가-힣]/.test(cp[1])){topName=cp[1].trim();topCode=cp[2];break;}
    // ── 3순위: US 티커 ──
    // US 티커 + 가격: "AAPL $185.50"
    const tkM=l.match(/^([A-Z]{2,6})\s*[\$S]?\s*([\d,]+\.\d+)/);
    if(tkM&&!EXCLUDE.includes(tkM[1])){topTicker=tkM[1];topName=topTicker;break;}
    // US 티커 단독: "AAPL"
    if(/^[A-Z]{2,6}$/.test(l)&&!EXCLUDE.includes(l)){topTicker=l;topName=l;break;}
    // US 티커 + 한글/영문 이름: "AAPL 애플", "AAPL Apple Inc."
    const tkNM=l.match(/^([A-Z]{2,6})\s+[가-힣A-Za-z]/);
    if(tkNM&&!EXCLUDE.includes(tkNM[1])){topTicker=tkNM[1];topName=topTicker;break;}
    // 국기이모지/기호 뒤 티커: "🇺🇸 JEPQ $58.42", "🇺🇸JEPQ", "■ AAPL"
    const tkFlag=l.match(/(?:[\u{1F1E6}-\u{1F1FF}]{2}|[^\w\s])\s*([A-Z]{2,6})(?:\s+\$[\d,.]+|\s|$)/u);
    if(tkFlag&&!EXCLUDE.includes(tkFlag[1])){topTicker=tkFlag[1];topName=topTicker;break;}
  }

  // 폴백: 전체 15줄에서 "TICKER $price" 또는 "TICKER (+n%)" 패턴 검색
  if(!topTicker&&!topName){
    for(let i=0;i<Math.min(lines.length,15);i++){
      const m=lines[i].match(/\b([A-Z]{2,6})\s+\$[\d,.]+/);
      if(m&&!EXCLUDE.includes(m[1])&&!KR_ETF_BRANDS.test(m[1])){topTicker=m[1];topName=topTicker;break;}
      const m2=lines[i].match(/\b([A-Z]{2,6})\s+\$[\d,.]+\s*\([+-][\d.]+%\)/);
      if(m2&&!EXCLUDE.includes(m2[1])&&!KR_ETF_BRANDS.test(m2[1])){topTicker=m2[1];topName=topTicker;break;}
    }
  }

  // 폴백1: 6자리 코드가 별도 줄에 있는 경우 → 이전 줄을 종목명으로 사용
  if(!topName&&!topTicker){
    for(let i=0;i<Math.min(lines.length,15);i++){
      if(KRC_RE.test(lines[i].trim())){
        topCode=lines[i].trim();
        // 이전 줄이 한글 포함 → 종목명
        if(i>0&&/[가-힣]/.test(lines[i-1])){
          topName=lines[i-1].trim().replace(new RegExp('\\s*\\(?'+KRC+'\\)?.*$'),'').trim();
        }
        break;
      }
    }
  }

  // 폴백2: 6자리 코드 발견 → DB에서 코드로 직접 조회
  if(!topName&&topCode){
    const dbByCode=getAllDB().find(x=>x.c===topCode);
    if(dbByCode) topName=dbByCode.n;
  }

  // 폴백3: 전체 텍스트에서 6자리 코드 찾기
  if(!topName&&!topTicker&&!topCode){
    const codeM=text.match(new RegExp('\\b('+KRC+')\\b'));
    if(codeM){
      topCode=codeM[1];
      const dbByCode=getAllDB().find(x=>x.c===topCode);
      if(dbByCode) topName=dbByCode.n;
    }
  }

  // 폴백4: 첫 한글 줄을 DB에서 직접 매칭 시도 (가장 긴 이름 우선)
  if(!topName&&!topTicker){
    for(let i=0;i<Math.min(lines.length,10);i++){
      const l=lines[i].trim();
      if(!l||!/[가-힣]/.test(l))continue;
      // 계좌/금융 키워드는 스킵
      if(/^(위탁|일반|절세|ISA|IRP|연금|퇴직|세금|보유|평가|수익|매수|매도|주문|체결|원금|총\s*수익|일간|실현|자산|거래|수동|현재가|평균|평단|배당|시세)/.test(l))continue;
      // 정확 매칭 우선
      var exact=getAllDB().find(function(x){return x.n===l;});
      if(exact){topName=exact.n;topCode=exact.c||'';break;}
      // 접두사 매칭 - 가장 긴 이름 우선 + 길이 유사 검증
      var cands=getAllDB().filter(function(x){
        if(!x.n) return false;
        var aInB = x.n.startsWith(l), bInA = l.startsWith(x.n);
        if(!aInB && !bInA) return false;
        var sh=Math.min(x.n.length,l.length), lo=Math.max(x.n.length,l.length);
        return sh/lo >= 0.7;
      });
      if(cands.length){
        cands.sort(function(a,b){return b.n.length - a.n.length;});
        topName=cands[0].n;topCode=cands[0].c||'';
        break;
      }
    }
  }

  // 폴백5: 첫 한글 줄 그대로 사용 (DB에 없어도)
  if(!topName&&!topTicker){
    for(let i=0;i<Math.min(lines.length,10);i++){
      const l=lines[i].trim();
      if(!l||!/[가-힣]/.test(l))continue;
      if(/^(위탁|일반|절세|ISA|IRP|연금|퇴직|세금|보유|평가|수익|매수|매도|주문|체결|총|합계|계좌|전체|잔고|원금|일간|실현|자산|거래|수동|현재가|평균|평단|배당|시세)/.test(l))continue;
      if(l.length>=2&&l.length<=30){topName=l;break;}
    }
  }

  // US 티커 전용: 전체 텍스트에서 "TICKER $price" 검색
  if(!topTicker&&!topName){
    const m=text.match(/\b([A-Z]{2,6})\s+\$[\d,.]+/);
    if(m&&!EXCLUDE.includes(m[1])){topTicker=m[1];topName=m[1];}
  }
  if(topTicker){
    const db=getAllDB().find(x=>(x.c&&x.c===topTicker)||x.n===topTicker);
    if(db)topName=db.n;
    else topName=topTicker;
  }

  // ── 문자열 유사도 (LCS 기반, 0~1) ──
  function strSim(a,b){
    if(!a||!b)return 0;
    if(a===b)return 1;
    const la=a.length,lb=b.length;
    let prev=new Array(lb+1).fill(0),curr=new Array(lb+1).fill(0);
    for(let i=1;i<=la;i++){
      for(let j=1;j<=lb;j++){
        curr[j]=a[i-1]===b[j-1]?prev[j-1]+1:Math.max(prev[j],curr[j-1]);
      }
      [prev,curr]=[curr,prev];curr.fill(0);
    }
    return prev[lb]/Math.max(la,lb);
  }
  // ── 공통 접두사 비율 (0~1) ──
  function prefixRatio(a,b){
    let p=0;
    for(let i=0;i<Math.min(a.length,b.length);i++){
      if(a[i]===b[i])p++;else break;
    }
    return p/Math.max(a.length,b.length);
  }
  // ── 종합 매칭 점수: LCS 70% + 접두사 30% ──
  function matchScore(a,b){return strSim(a,b)*0.7+prefixRatio(a,b)*0.3;}
  function stripSuffix(s){
    return s.replace(/^(삼성액티브|삼성|미래에셋|한국투자|KB|신한|하나|키움|NH-Amundi|교보악사|대신|우리|에셋플러스|타임폴리오|트러스톤|브이아이|한화|흥국|마이다스|더제이|IBK|iM에셋|DB|BNK)\s*/,'').replace(/증권상장지수.*$/,'').replace(/투자신탁.*$/,'').replace(/[\[\]\(\)\{\}]/g,'').trim();
  }

  // ── DB 매칭 함수 (topName, topTicker, topCode 활용) ──
  function findDbMatch(){
    const allDb=getAllDB();
    // 1) 코드로 정확 매칭 (가장 정확 - 최우선)
    if(topCode){
      const m=allDb.find(x=>x.c===topCode);
      if(m)return m;
    }
    // 2) 티커로 매칭 (US 주식)
    if(topTicker){
      const m=allDb.find(x=>x.c===topTicker||x.n===topTicker);
      if(m)return m;
    }
    // 이름 정규화 헬퍼 (공백/기호 제거 + 대문자)
    const normalize = s => String(s||'').toUpperCase().replace(/[\s\-_.·,()/\[\]{}]/g,'');
    // 3) 이름으로 정규화 매칭 (DB는 "TIGER미국S&P500..." 처럼 공백 없음, OCR은 공백 있음)
    if(topName){
      const nq = normalize(topName);
      if(nq){
        // 정확 일치
        let m = allDb.find(x=>x.n && normalize(x.n) === nq);
        if(m) return m;
        // 양방향 startsWith + 길이 유사 (짧은 축약명 오매칭 방지)
        const candidates = allDb.filter(function(x){
          if(!x.n) return false;
          const nx = normalize(x.n);
          if(!nx) return false;
          const aInB = nx.startsWith(nq), bInA = nq.startsWith(nx);
          if(!aInB && !bInA) return false;
          const shorter = Math.min(nx.length, nq.length);
          const longer = Math.max(nx.length, nq.length);
          return shorter/longer >= 0.7;
        });
        if(candidates.length > 0){
          // 가장 긴 이름 우선 (더 구체적)
          candidates.sort(function(a,b){return b.n.length - a.n.length;});
          return candidates[0];
        }
      }
    }
    // 5) 유사도 75% 이상 퍼지 매칭 (길이 비슷한 것만, 동점 시 긴 이름 우선)
    if(topName&&topName.length>=4){
      const stripped=stripSuffix(topName);
      const stripLen=stripped.length;
      let bestMatch=null,bestScore=0;
      for(const x of allDb){
        const dbStripped=stripSuffix(x.n);
        // 길이 차이 70% 이상 차이나면 스킵 (짧은 축약명 오매칭 방지)
        const shorter = Math.min(dbStripped.length, stripLen);
        const longer = Math.max(dbStripped.length, stripLen);
        if(longer>0 && shorter/longer < 0.7) continue;
        const score=matchScore(stripped,dbStripped);
        // 동점/근사 동점이면 더 긴 이름 우선 (커버드콜 등 보호)
        if(score>bestScore || (Math.abs(score-bestScore)<0.02 && bestMatch && x.n.length>bestMatch.n.length)){
          bestScore=score;bestMatch=x;
        }
      }
      if(bestMatch&&bestScore>=0.75)return bestMatch;
    }
    return null;
  }

  // 줄 단위 파싱: "N주 · M원" 또는 "N주 · $M.MM" 패턴
  // OCR이 "1,100"을 "1, 100" 또는 "1,   100"처럼 공백 섞어 읽는 경우 대비 (쉼표 뒤 공백 허용)
  const pNum=/([\d][\d, ]*?\d|\d)\s*주\s*[·・·\-\.•]\s*(\$?[\d][\d, ]*\.?\d*|\d)\s*(?:원|달러|USD)?/;
  const pNum4=/([\d][\d, ]*?\d|\d)\s*주\s+(\d[\d, ]*)\s*원/;

  // OCR 전처리: 숫자 내부 쉼표 뒤 공백 정규화
  // "1, 100주" → "1,100주", "10, 000원" → "10,000원"
  // 쉼표 뒤 공백 + 숫자 패턴만 선택적으로 제거 (일반 문장은 보존)
  function fixCommaSpace(line){
    return String(line||'').replace(/(\d),\s+(\d{2,3})(?=[\s주원달])/g, '$1,$2');
  }

  for(let i=0;i<lines.length;i++){
    const line = fixCommaSpace(lines[i]);
    const m=line.match(pNum);
    if(!m)continue;
    const qty=N(m[1]);
    // 달러 판별: $ 접두사 또는 같은 줄에 "달러"/"USD" 포함
    const isUSD=m[2].startsWith('$')||/달러|USD/i.test(line);
    const rawPrice=parseFloat(m[2].replace('$','').replace(/[,\s]/g,''));
    if(!rawPrice||qty<=0||qty>9999999)continue;
    // 달러면 원화 변환
    const price=isUSD?Math.round(rawPrice*(D.rate||1380)):Math.round(rawPrice);
    if(price<=0)continue;

    const before=line.slice(0,line.indexOf(m[0])).trim();
    const prevLine=i>0?lines[i-1].trim():'';
    const acctSrc=before||prevLine;
    const acct=acctOf(acctSrc);

    // 0주는 스킵
    if(qty===0)continue;

    const k=qty+'|'+price;
    if(seen.has(k))continue;
    seen.add(k);

    const db=findDbMatch();
    const name=db?db.n:(topName||acctSrc||'종목');
    results.push({name:name.slice(0,30),qty,avgPrice:price,acct,db,isUSD,rawUsdPrice:isUSD?rawPrice:null,code:db?db.c:topCode});
  }

  // pNum4: "N주 M원" (· 없는 경우)
  if(!results.length){
    for(let i=0;i<lines.length;i++){
      const line = fixCommaSpace(lines[i]);
      const m=line.match(pNum4);
      if(!m)continue;
      const qty=N(m[1]),price=N(m[2]);
      if(!qty||!price||qty>9999999||price<100)continue;
      const k=qty+'|'+price;
      if(seen.has(k))continue; seen.add(k);
      const db=findDbMatch();
      results.push({name:db?db.n:topName||'종목',qty,avgPrice:price,acct:'general',db,code:db?db.c:topCode});
    }
  }

  // 보유량+평단가 형식 (결과 없을 때만)
  if(!results.length){
    const mQty=text.match(/보유[량주]?\s*[\n\r]?\s*([\d,]+)\s*주/);
    const mPrc=text.match(/평단[가]?\s*[\n\r]?\s*([\d,]+)\s*원/);
    if(mQty&&mPrc){
      const qty=N(mQty[1]),price=N(mPrc[1]);
      if(!seen.has(qty+'|'+price)){
        const db=findDbMatch();
        results.push({name:db?db.n:topName||'종목',qty,avgPrice:price,acct:'general',db,code:db?db.c:topCode});
      }
    }
  }

  // ── US 주식 전용: 멀티라인 수량·가격 파싱 ──
  if(!results.length&&topTicker){
    let usQty=0, usPrice=0, usIsUSD=false, usRaw=0;
    // 수량 추출: "10주", "보유수량 10주", "수량 10", "수량 10주"
    const qM=text.match(/(?:보유[수량]*|수량)\s*[\n\r]?\s*([\d,]+)\s*주?/)||text.match(/([\d,]+)\s*주/);
    if(qM) usQty=N(qM[1]);
    // USD 가격: "$185.50", "매수평균가 $185.50", "평단가 $28.50"
    const pUsd=text.match(/(?:평균?[매단]?[수가]*|평단가|매입단가)?\s*[\n\r]?\s*\$\s*([\d,]+\.?\d*)/);
    if(pUsd){usPrice=parseFloat(pUsd[1].replace(/,/g,''));usIsUSD=true;usRaw=usPrice;usPrice=Math.round(usPrice*(D.rate||1380));}
    // "달러" 가격: "52.30달러", "52.30 달러"
    if(!usPrice){
      const pDlr=text.match(/([\d,]+\.\d+)\s*달러/);
      if(pDlr){usPrice=parseFloat(pDlr[1].replace(/,/g,''));usIsUSD=true;usRaw=usPrice;usPrice=Math.round(usPrice*(D.rate||1380));}
    }
    // "USD" 가격: "185.50 USD", "185.50USD"
    if(!usPrice){
      const pU=text.match(/([\d,]+\.\d+)\s*USD/i);
      if(pU){usPrice=parseFloat(pU[1].replace(/,/g,''));usIsUSD=true;usRaw=usPrice;usPrice=Math.round(usPrice*(D.rate||1380));}
    }
    // 원화 환산가: "268,590원" (수량은 있지만 $ 없을 때)
    if(!usPrice){
      const pW=text.match(/(?:평균?[매단]?[수가]*|평단가|매입단가|매수평균가)\s*[\n\r]?\s*([\d,]+)\s*원/);
      if(pW){usPrice=N(pW[1]);}
    }
    // 소수점 숫자만 있는 경우 (US주식 컨텍스트에서 단독 등장): 라인별 스캔
    if(!usPrice){
      for(const l of lines){
        const solo=l.match(/^[\$]?([\d,]+\.\d{2})$/);
        if(solo){usPrice=parseFloat(solo[1].replace(/,/g,''));usIsUSD=true;usRaw=usPrice;usPrice=Math.round(usPrice*(D.rate||1380));break;}
      }
    }
    if(usQty>0&&usPrice>0){
      const db=findDbMatch();
      results.push({name:db?db.n:topName||topTicker,qty:usQty,avgPrice:usPrice,acct:'general',db,isUSD:usIsUSD,rawUsdPrice:usIsUSD?usRaw:null,code:db?db.c:''});
    }
  }

  // ── "N주 $M.MM" / "N주 M.MM" 구분자 없는 동일줄 (US 주식) ──
  if(!results.length&&topTicker){
    for(const l of lines){
      const m=l.match(/([\d,]+)\s*주\s+\$?([\d,]+\.\d+)/);
      if(m){
        const qty=N(m[1]);
        let rawP=parseFloat(m[2].replace(/,/g,''));
        const isUSD=l.includes('$')||rawP<10000;
        const price=isUSD?Math.round(rawP*(D.rate||1380)):Math.round(rawP);
        if(qty>0&&price>0){
          const db=findDbMatch();
          results.push({name:db?db.n:topName||topTicker,qty,avgPrice:price,acct:'general',db,isUSD,rawUsdPrice:isUSD?rawP:null,code:db?db.c:''});
          break;
        }
      }
    }
  }
  return results;
}

function renderSsParsed(rawBox){
  rawBox=rawBox||'';
  const rows=SS_PARSED.map((x,i)=>{
    const dbMatch=x.db;
    const chip=dbMatch?`<span style="font-size:10px;background:#f0fdf4;color:#16a34a;padding:1px 6px;border-radius:4px;margin-left:4px">DB매칭</span>`:'';
    return`<div style="padding:10px 0;${i>0?'border-top:1px solid #f3f3f1':''}">
      <div style="display:flex;justify-content:space-between;align-items:center">
        <div><span style="font-size:13px;font-weight:700">${x.name}</span>${chip}</div>
        <span style="font-size:10px;padding:2px 7px;border-radius:5px;${_isTaxAcct(x.acct)?'background:#f0fdf4;color:#16a34a':'background:#f3f4f6;color:#888'}">${_isTaxAcct(x.acct)?'절세':'일반'}</span>
      </div>
      <div style="font-size:11px;color:#aaa;margin-top:2px">${fN(x.qty)}주 · 평단 ${x.isUSD?'$'+x.rawUsdPrice.toFixed(2)+' ('+fN(x.avgPrice)+'원)':fN(x.avgPrice)+'원'}${dbMatch?' · '+dbMatch.df:''}</div>
    </div>`;
  }).join('');
  document.getElementById('ssResult').innerHTML=`
    <div style="background:#f0fdf4;border-radius:10px;padding:9px 12px;margin-bottom:10px">
      <div style="font-size:12px;font-weight:700;color:#16a34a">✅ ${SS_PARSED.length}개 종목 인식</div>
    </div>
    <div style="border:1px solid var(--c-border);border-radius:10px;padding:12px;margin-bottom:6px">
    ${rows}
    </div>
    ${rawBox}`;
  document.getElementById('ssResult').style.display='block';
  document.getElementById('ssImportBtn').style.display='block';
  document.getElementById('ssAnalyzeBtn').style.display='block';
  document.getElementById('ssAnalyzeBtn').textContent='🔄 재시도';
}

async function confirmSsImport(){
  if(!SS_PARSED||!SS_PARSED.length){alert('인식된 종목이 없습니다');return;}

  let added=0;
  for(const x of SS_PARSED){
    const db=x.db;

    // ── sym 결정 (addHolding과 동일 로직) ──
    let sym;
    if(db){
      sym = db.s || (db.c ? db.c + (db.m==='KQ'?'.KQ':'.KS') : toSym(x.name));
      // US_STOCK_DB 항목은 t='us'(보통주) 또는 t='ue'(ETF), c=티커
      if((db.t==='us'||db.t==='ue') && db.c && /^[A-Z]{1,6}$/.test(db.c)){
        sym = db.c;
      }
    } else if(x.code && /^[0-9][0-9A-Z]{5}$/.test(x.code)){
      // DB에 없지만 OCR로 한국 종목코드 파악됨 → 그 코드로 sym 구성
      // (실제 .KS/.KQ는 시세 조회 시 서버가 확인하므로 일단 .KS로 시도)
      sym = x.code + '.KS';
    } else if(x.code && /^[A-Z]{1,6}$/.test(x.code)){
      // US 티커 코드
      sym = x.code;
    } else {
      sym = toSym(x.name);
    }

    // ── 배당 정보 (addHolding과 동일 로직) ──
    const dy = db ? (db.dy||0) : 0;
    const _isKRStk = db && db.t==='stk' && db.c && /^[0-9][0-9A-Z]{5}$/.test(db.c);
    const df = db ? (db.df || (_isKRStk ? '분기배당' : '없음')) : '없음';
    const isDv = dy > 0 || _isKRStk || (db && db.df && db.df !== '없음');

    // ── 기존 보유종목 중복 체크 (이름 정규화 + 코드 비교) ──
    const _norm = s => String(s||'').toUpperCase().replace(/[\s\-_.·,()/\[\]{}]/g,'');
    const _extractCode = s => {
      if(!s) return '';
      const m = String(s).match(/([0-9][0-9A-Z]{5})/);
      return m ? m[1] : String(s).toUpperCase();
    };
    const newNameN = _norm(x.name);
    const newCode = _extractCode(sym);
    const existing = D.h.find(function(h){
      if(!h) return false;
      // 1) 심볼(코드) 일치
      if(h.sym && sym){
        const hCode = _extractCode(h.sym);
        if(hCode && newCode && hCode === newCode) return true;
        if(String(h.sym).toUpperCase() === String(sym).toUpperCase()) return true;
      }
      // 2) 이름 정규화 일치 (공백/기호 제거 후)
      if(h.n){
        const hNameN = _norm(h.n);
        if(hNameN && newNameN && hNameN === newNameN) return true;
      }
      return false;
    });
    if(existing){
      // 기존 종목이면 추가매수로 처리
      const nq = existing.qty + x.qty;
      const na = Math.round((existing.avgCost * existing.qty + x.avgPrice * x.qty) / nq);
      existing.qty = nq;
      existing.avgCost = na;
      existing.avg = na;
      if(!existing.buys) existing.buys = [];
      existing.buys.push({id: Date.now()+'_ss'+added, qty: x.qty, price: x.avgPrice, date: new Date().toISOString().split('T')[0], acct: x.acct});
      added++;
      continue;
    }

    // ── 새 종목 추가 ──
    const id = Date.now() + added;
    const avgPrice = x.avgPrice;
    const buys = [{id: id+'_0', qty: x.qty, price: avgPrice, date: new Date().toISOString().split('T')[0], acct: x.acct}];

    D.h.push({
      id: id,
      n: x.name,
      sym: sym,
      avg: avgPrice,
      avgCost: avgPrice,
      qty: x.qty,
      cur: avgPrice,
      dy: dy,
      df: isDv ? df : '없음',
      isDv: isDv,
      err: 0,
      divHistory: undefined,
      acct: x.acct,
      memo: '',
      buys: buys
    });
    added++;
  }

  save();
  closeModal('ssOv');
  render();

  // ── 시세 + 배당 정보 fetch ──
  // 더 안정적인 매칭: 이름 정규화 사용
  const _norm2 = s => String(s||'').toUpperCase().replace(/[\s\-_.·,()/\[\]{}]/g,'');
  for(const x of SS_PARSED){
    const nq = _norm2(x.name);
    const h = D.h.find(hh => hh.n === x.name || _norm2(hh.n) === nq);
    if(h){
      try{ await fetchOne(h.id); }catch(e){ console.warn('fetchOne err:', h.n, e); }
      // 배당 조회도 즉시 (addHolding과 동일하게)
      const isKrSym = isKR(h.sym||'') || (h.sym && /^[0-9][0-9A-Z]{5}\.(KS|KQ)$/i.test(h.sym));
      if(isKrSym || h.isDv){
        setTimeout(function(){ fetchDivs(h.id).catch(function(){}); }, 400);
      }
    }
  }

  save();
  render();
  alert(added + '개 종목이 추가되었습니다');
}

